INSERT INTO public.document_files (
  id,document_id,file_type,storage_path,download_filename,mime_type,file_size,sha256,page_count,is_downloadable,download_block_reason
)
SELECT (x->>'id')::uuid,(x->>'document_id')::uuid,x->>'file_type',x->>'storage_path',x->>'download_filename',
       x->>'mime_type',(x->>'file_size')::bigint,x->>'sha256',(x->>'page_count')::integer,
       (x->>'is_downloadable')::boolean,x->>'download_block_reason'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT DO NOTHING;

COMMIT;

SELECT 'moj-all-verified-judgments-review-002-chunk-105' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"390a20c0-7b08-532a-b69d-ac911675b3a6","document_type":"judgment","category":"judicial","subcategory":"general","title":"استعمال املخدرات -حيازة سيجارة حشيش -حيازة قارورة خمر تعاطي احلشيش -التستر على مصدر اخلمر واحلشيش -قيادة السيارة حتت تأثير تعاطي احلشيش املخدر -إقامة حد املسكر - التعزير بالسجن واجللد واإلبعاد.","document_number":"3432148","case_number":"3445259","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/06","year":"1434","subject":"استعمال املخدرات -حيازة سيجارة حشيش -حيازة قارورة خمر تعاطي احلشيش -التستر على مصدر اخلمر واحلشيش -قيادة السيارة حتت تأثير تعاطي احلشيش املخدر -إقامة حد املسكر - التعزير بالسجن واجللد واإلبعاد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 3432148 :‬تاريخه ‪1434/02/06:‬هـ‬\n                      ‫رقم الدعوى‪3445259 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪    34173165‬تاريخه‪1434/3/28:‬هـ‬\n\n\n\n‫اســتعمال املخــدرات ‪ -‬حيــازة ســيجارة حشــيش ‪ -‬حيــازة قــارورة خمــر‬\n‫ـ تعاطــي احلشــيش ‪ -‬التســتر علــى مصــدر اخلمــر واحلشــيش ‪ -‬قيــادة‬\n‫الســيارة حتــت تأثيــر تعاطــي احلشــيش املخــدر ‪ -‬إقامــة حــد املســكر ‪-‬‬\n                                    ‫التعزيــر بالســجن واجللــد واإلبعــاد‪.‬‬\n\n\n\n\n            ‫‪-1‬املادة (‪ )41‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n            ‫‪-2‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n            ‫‪-3‬املادة (‪ )60‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n\n\n\n\n‫توجيــه االتهــام للمدعــى عليهمــا‪ :‬األول بتعاطــي احلشــيش وحيــازة قــارورة‬\n‫مســكر بقصــد الشــرب وتســتره علــى مصــدر املســكر‪ ،‬والثانــي‬\n‫حيــازة ســيجارة حشــيش بقصــد التعاطــي‪ ،‬وتعاطيــه احلشــيش وتســتره‬\n‫علــى مصــدر احلشــيش‪ ،‬وقيادتــه للســيارة حتــت تأثيــر تعاطــي احلشــيش‬\n‫املخــدر‪ ،‬حيــث قبــض عليهمــا مــن قبــل إحــدى فــرق دوريــات األمــن يف‬\n‫إحــدى نقــاط التفتيــش يف الطريــق العــام ‪ ،‬حيــث مت اســتيقاف الســيارة‬\n‫التــي كان يقودهــا األول و يرافقــه الثانــي وبتفتيــش الســيارة وجــد حتــت‬\n‫مقعــد الســائق ســيجارة مخلوطــه باحلشــيش‪ ،‬كمــا عثــر علــى قــارورة‬\n\n                                                                                 ‫‪52‬‬\n\f       ‫بهــا ســائل مســكر‪ ،‬باســتجواب املدعــى عليــه األول اعتــرف بتعاطــي‬\n       ‫احلشــيش  وحيــازة قــارورة املســكر بقصــد الشــرب ولــم يــدل مبعلومــات‬\n     ‫عــن مصــدر مــا ضبــط‪ ،‬باســتجواب الثانــي اعتــرف بتعاطــي احلشــيش‪  ،‬‬\n       ‫وحيــازة ســيجارة احلشــيش بقصــد التعاطــي ‪ ،‬ولــم يــدل مبعلومــات عــن‬\n       ‫مصــدر ماضبــط‪ ،‬طلــب املدعــي العــام إثبــات إدانتهمــا مبــا نســب إليهــم‬\n       ‫وإجــراء املقتضــى الشــرعي لقــاء تعاطيهمــا احلشــيش املخــدر‪ ،‬احلكــم‬\n       ‫بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام مكافحــة‬\n       ‫املخــدرات بحــق الثانــي لقــاء مــا أســند إليــه‪ ،‬إبعادهمــا خــارج اململكــة‬\n       ‫بعــد انتهــاء تنفيــذ عقوبــة ســجنهما‪ ،‬تعزيــر األول لقــاء حيــازة املســكر‬\n       ‫بقصــد الشــرب‪ ،‬تعزيرهمــا لقــاء تســترهما علــى مصــدر ماضبــط‪ ،‬أقــر‬\n       ‫املدعــى عليهمــا مبــا نســب إليهمــا‪ ،‬صــدر احلكــم بإثبــات مــا أســند‬\n       ‫إليهــم و احلكــم عليهمــا بإقامــة حــد املســكر‪ ،‬التعزيــر بالســجن واجللــد‬\n       ‫واإلبعــاد‪ ،‬إثبــات قيــادة األول للســيارة حتــت تأثيــر احلشــيش املخــدر‬\n       ‫والعقوبــة يف ذلــك عائــدة للجهــة املختصــة‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                                           ‫االســتئناف ‪.‬‬\n\n\n\n\n‫‪53‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ............‬القاضــي يف احملكمــة‬\n‫اجلزائيــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة بالريــاض برقــم  وتاريــخ ‪ 1434/01/26‬هــ  املقيــدة‬\n‫باحملكمــة برقــم   وتاريــخ ‪ 1434/01/26‬هــ   ففــي يــوم   األربعــاء‬\n‫املوافــق‪ 1434/02/06‬ه ـ افتتحــت اجللســة الســاعة ‪  11 : 15‬وفيهــا قــدم‬\n                                         ‫املدعــي العــام دعــواه علــى كل مــن‪:‬‬\n‫‪ .......... -1‬البالــغ مــن العمــر( ‪ ) 24‬عام ـ ًا ‪ ،‬ســوداني اجلنســية مبوجــب‬\n‫بطاقــة رخصــة إقامــة  رقــم (‪  )..........‬أعــزب ‪ ،‬جامعــي ‪ ،‬مرافــق لوالــده‪،‬‬\n‫يقيــم  يف مدينــة الريــاض ‪ ،‬أوقــف بتاريــخ ‪1433/12/23‬ه ـ ‪ ،‬وأحيــل‬\n‫إلــى شــعبة ســجن امللــز مبوجــب أمــر اإلحالــة ومتديــد التوقيــف رقــم (ه ـ‬\n‫ر‪ )610/5/1‬وتاريــخ  ‪1434/1/3‬ه ـ ‪ ،‬اســتناد ًا لبرقيــة ســمو ولــي العهــد‬\n‫النائــب األول لرئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم (‪)..........‬‬\n                                 ‫وتاريــخ ‪1433/12/20‬ه ـ ‪ ،‬لكونــه أجنبــي‪.‬‬\n  ‫‪ .......... ، .2‬البالــغ مــن العمــر( ‪ ) 22‬عام ـ ًا ‪ ،‬ســوداني اجلنســية مبوجــب‬\n  ‫بطاقــة رخصــة إقامــة رقــم (‪  )..........‬أعــزب ‪ ،‬طالــب ‪ ،‬يقيــم  يف مدينــة‬\n  ‫الريــاض‪ ،‬أوقــف بتاريــخ ‪1433/12/23‬ه ـ ‪ ،‬وأحيــل إلــى شــعبة ســجن‬\n‫امللــز مبوجــب أمــر اإلحالــة ومتديــد التوقيــف رقم (ه ـ ر‪ )609/5/1‬وتاريخ  ‬\n  ‫‪1434/1/3‬ه ـ ‪ ،‬اســتناد ًا لبرقيــة ســمو ولــي العهــد النائــب األول لرئيــس‬\n  ‫مجلــس الــوزراء وزيــر الداخليــة رقــم (‪ )79425‬وتاريــخ ‪1433/12/20‬ه ـ‬\n                                                                ‫‪ ،‬لكونــه أجنبــي‪.‬‬\n  ‫حيــث إنــه بتاريــخ ‪1433/12/23‬ه ـ ‪ ،‬قبــض علــى املذكوريــن مــن قبــل‬\n\n                                                                                      ‫‪54‬‬\n\f     ‫إحــدى فــرق دوريــات األمــن يف أحــد نقــاط التفتيــش يف طريــق ‪ ....‬مــع ‪....‬‬\n     ‫حيــث مت اســتيقاف ســيارة مــن نــوع ‪ .....‬وحتمــل اللوحــة رقــم (‪)....‬بقيــادة‬\n     ‫األول ويرافقــه الثانــي ‪ ،‬وبتفتيــش الســيارة وجــد حتــت مقعــد الســائق‬\n     ‫ســيجارة تــزن (‪ )1.2‬جرام ـ ًا واحــد ًا وعشــري اجلــرام يشــتبه أن يكــون‬\n     ‫تبغهــا مخلــوط باحلشــيش املخــدر وعثــر أيض ـ ًا علــى قــارورة بهــا ســائل‬\n     ‫يشــتبه أن يكــون مــن املســكر ســعة (‪)0.6‬لتــر بهــا أكثــر مــن النصــف ‪.‬‬\n     ‫    وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز‬\n     ‫مراقبــة الســموم و الكيميــاء الطبيــة الشــرعية  املرفــق رقــم (‪/11773‬‬\n     ‫س) لعام‪1433‬ه ـ ايجابيــة مســتخلص التبــغ يف الســيجارة املضبوطــة‬\n     ‫للحشــيش وهــو مــن املــواد املخــدرة املدرجــة باجلــدول رقــم (‪ )1‬فئــة ( أ )‬\n     ‫امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬وايجابيــة عينــة‬\n               ‫الســائل املضبــوط يف القــارورة ملــادة الكحــول بنســبة  (‪.)%42‬‬\n     ‫    وبســماع أقــوال األول األوليــة واســتجوابه اعتــرف بتعاطــي احلشــيش‬\n     ‫املخــدر يف نفــس يــوم القبــض عليــه ‪ ،‬وحيــازة قــارورة املســكر بقصــد‬\n                           ‫الشــرب ‪ ،‬ولــم يــدل مبعلومــات عــن مصــدر ماضبــط‪.‬‬\n     ‫وبســماع أقــوال الثانــي األوليــة اعتــرف بتعاطــي احلشــيش املخــدر ‪،‬‬\n     ‫وباســتجوابه اعتــرف بحيــازة ماضبــط مــن ســيجارة حشــيش مخــدر‬\n     ‫لــه بقصــد التعاطــي ‪ ،‬واعتــرف بتعاطــي احلشــيش املخــدر ‪ ،‬ولــم يــدل‬\n                                                 ‫مبعلومــات عــن مصــدر ماضبــط‪.‬‬\n     ‫وقــد أســفرت إجــراءات التحقيــق عــن اتهــام األول‪ ..... /‬بتعاطي احلشــيش‬\n     ‫املخــدر ‪ ،‬وللثانــي‪ ،..... /‬بحيــازة ســيجارة مخلوط ـ ًا تبغهــا باحلشــيش‬\n     ‫املخــدر تــزن (‪ )1.2‬جرام ـ ًا واحــد ًا وعشــري اجلــرام بقصــد التعاطــي‬\n     ‫وتعاطيــه احلشــيش املخــدر‪ ،‬املجــرم مبوجــب املــادة (الثالثــة) مــن نظــام‬\n\n\n‫‪55‬‬\n\f  ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n  ‫( م ‪ )39 /‬وتاريــخ ‪1426/7/8‬ه ـ ‪ ،‬وحيــازة األول قــارورة املســكر ســعة‬\n  ‫(‪ )0.6‬لتــر بهــا أكثــر مــن النصــف بقصــد الشــرب ‪ ،‬وتســتر األول علــى‬\n  ‫مصــدر مــا ضبــط مــن مســكر‪  ،‬وتســتر الثانــي علــى مصــدر مــا ضبــط‬\n  ‫مــن حشــيش مخــدر املعاقــب علــى ذلــك شــرع ًا ‪ ،‬وقيادتــه للســيارة حتــت‬\n  ‫تأثيــر تعاطــي احلشــيش املخــدر املجــرم مبوجــب املــادة (‪ )68‬مــن نظــام‬\n‫املــرور الصــادر باملرســوم امللكــي رقــم (م‪ )85/‬وتاريــخ ‪1428/10/26‬هـ  ‬\n                                                   ‫وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n  ‫ا علــى‬ ‫‪ .1‬مــا تضمنــه اعترافهمــا حتقيق ـ ًا املنــوه عنــه املــدون تفصي ـ ً‬\n  ‫الصفحــات رقــم (‪ 1‬ـ ـ ‪ )4‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪.)16‬‬\n  ‫‪ .2‬مــا تضمنــه اعترافهمــا مبحضــر ســماع أقوالــه األوليــة املنــوه عنهمــا‬\n                                     ‫املــدون اللفــات مــن رقــم (‪ )3‬إلــى رقــم (‪.)6‬‬\n                 ‫‪ .3‬ما تضمنه محضر القبض املنوه عنه املرفق لفه رقم (‪.)1‬‬\n  ‫‪ .4‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــة‬\n                                                                             ‫رقــم(‪.)15‬‬\n  ‫وببحــث ســوابقهما عثــر لــأول علــى ســابقة مضاربــة ‪ ،‬ولــم يعثــر للثانــي‬\n  ‫علــى ســوابق مســجلة حتــى تاريخــه‪ .‬وحيــث إن مــا أقدم عليــه املذكوران‬\n  ‫فعــل محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا لــذا اطلــب إثبــات إدانتهمــا مبا‬\n                                                    ‫اســند إليهمــا واحلكــم باآلتــي ‪:‬‬\n  ‫‪ .1‬بإجــراء املقتضــى الشــرعي  بحقهمــا لقــاء تعاطيهمــا احلشــيش املخــدر‬\n  ‫‪ .2‬بالعقوبــة الــواردة يف الفقــرة (األولــى)   مــن املــادة (‪ )41‬مــن نظــام‬\n  ‫مكافحــة املخــدرات واملؤثــرات العقليــة املشــار إليــه بحــق الثانــي لقــاء‬\n                                                                       ‫مــا أســند إليــه‪.‬‬\n\n\n                                                                                             ‫‪56‬‬\n\f     ‫‪ .3‬إبعــاد األول والثانــي إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبــة‬\n     ‫ســجنهما وعــدم الســماح لهمــا بالعــودة إليهــا مــرة أخــرى وفق ـ ًا للفقــرة‬\n                              ‫(الثانيــة) مــن املــادة (‪ )56‬مــن النظــام املشــار إليــه ‪.‬‬\n          ‫‪ .4‬بعقوبة تعزيرية بحق األول لقاء حيازته املسكر بقصد الشرب ‪.‬‬\n             ‫‪ .5‬بعقوبة تعزيرية بحقهما لقاء تسترهما على مصدر ما ضبط ‪.‬‬\n     ‫‪ .6‬النظــر فيمــا يتعلــق بقيــادة األول الســيارة حتــت تأثيــر تعاطي احلشــيش‬\n     ‫املخــدر وفــق البنــد (ثاني ـاً) مــن املرســوم امللكــي رقــم(م‪ )85/‬وتاريــخ‬\n     ‫‪1428/10/26‬هــ‪ .‬وبعــرض دعــوى املدعــي العــام علــى املدعــى عليهمــا‬\n     ‫احلاضريــن يف هــذه اجللســة أجــاب كل واحــد منهمــا قائــا‪ :‬مــا جــاء‬\n     ‫بدعــوى املدعــي العــام كلــه صحيــح مــا عــدا التســتر فقــد اشــترينا‬\n     ‫هــذه األشــياء مــن أنــاس ال نعرفهــم هكــذا قــررا‪ .‬بعــد ذلــك جــرى منــا‬\n     ‫الرجــوع إلــى أوراق املعاملــة وقــد وجــدت علــى اللفــة رقــم (‪ )15‬التقريــر‬\n     ‫الكيميائــي املرفــق برقــم (‪/11773‬س) واملتوافــق مــع مــا جــاء يف الئحــة‬\n     ‫الدعــوى كمــا أننــي لــم أجــد يف البينــات التــي قدمهــا املدعــي العــام‬\n     ‫مــا يــدل علــى التســتر فبنــاء علــى مــا تقــدم وإلقــرار املدعــى عليهمــا‬\n     ‫مبــا نســب إليهمــا ومبــا أن مــا قامــا بــه فعــل محــرم يســتدعي إقامــة‬\n     ‫حــد املســكر عليهمــا وتعزيرهمــا وملــا جــاء باملــواد احلاديــة واألربعــن‬\n     ‫والسادســة واخلمســن مــن نظــام مكافحــة املخــدرات ولعــدم وجــود‬\n     ‫ســوابق علــى املدعــى عليهمــا ســوى ســابقة مضاربــة علــى األول ممــا‬\n     ‫يتوجــه معــه مراعــات ذلــك والتخفيــف عليهمــا بتطبيــق املــادة الســتني مــن‬\n     ‫نظــام مكافحــة املخــدرات عليهمــا ولعــدم وجــود البينــة علــى تســترهما‬\n     ‫علــى املصــدر لذلــك كلــه فقــد ثبــت لــدي إدانــة املدعــى عليهمــا بحيــازة‬\n     ‫ســيجارة مخلــوط تبغهــا باحلشــيش املخــدر  تــزن جرامــا واحــدا وعشــري‬\n\n\n‫‪57‬‬\n\f  ‫اجلــرام بقصــد التعاطــي وتعاطــي احلشــيش املخــدر وحيــازة األول قــارورة‬\n  ‫مســكر ســعة (‪ )0،6‬لتــر بهــا أكثــر مــن النصــف بقصــد الشــرب‬\n  ‫وقيــادة األول للســيارة حتــت تأثيــر تعاطــي احلشــيش املخــدر وصــدر منــا‬\n  ‫مــا يلــي‪ :‬أوال‪ :‬حكمــت بســجن كل واحــد مــن املدعــى عليهمــا ملــدة‬\n  ‫ثالثــة أشــهر تبــدأ مــن تاريــخ إيقافهمــا للحيــازة بقصــد التعاطــي‪ .‬ثانيــا‪:‬‬\n  ‫حكمــت بإقامــة حــد املســكر علــى املدعــى عليهمــا وذلــك بجلــد كل‬\n  ‫واحــد منهمــا ثمانــن جلــدة دفعــة واحــدة‪ .‬ثالثــا‪ :‬حكمــت بإبعــاد املدعــى‬\n  ‫عليهمــا مــن اململكــة العربيــة الســعودية بعــد تنفيــذ العقوبــة احملكــوم‬\n  ‫بهــا عليهمــا وعــدم الســماح لهمــا بالعــودة مــا عــدا مــا تســمح بــه تعليمــات‬\n  ‫احلــج والعمــرة‪ .‬رابعــا‪ :‬حكمــت بجلــد املدعــى عليــه األول ثالثــن جلــدة‬\n  ‫دفعــة واحــدة حليــازة املســكر بقصــد شــربه‪ .‬خامســا‪ :‬حكمــت بــرد‬\n  ‫دعــوى املدعــي العــام حيــال مطالبتــه تعزيــر املدعــى عليهمــا للتســتر لعدم‬\n  ‫ثبوتــه‪ .‬سادســا‪ :‬أفهمــت املدعــى عليــه األول بــأن عقوبتــه علــى قيــادة‬\n  ‫الســيارة حتــت تأثيــر احلشــيش املخــدر عائــدة للجهــة املختصــة‪ .‬وبعــرض‬\n  ‫احلكــم علــى املدعــى عليهمــا واملدعــي العــام قنــع املدعــى عليهمــا وقــرر‬\n  ‫املدعــي العــام اعتراضــه علــى احلكــم بــدون الئحــة اعتراضيــة مكتفيــا‬\n  ‫مبــا جــاء بــأوراق املعاملــة‪ .‬واختتمــت اجللســة الســاعة ‪. 12:00‬وبــاهلل‬\n  ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                       ‫حــرر يف  ‪ 1434/02/06‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة األولــى  ‬\n  ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض‬\n  ‫برقــم ‪ ...‬وتاريــخ ‪1434/2/27‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n  ‫القاضــي باحملكمــة الشــيخ‪ ...../‬املســجل برقــم‪ .....‬وتاريــخ  ‪1434/2/6‬‬\n\n\n                                                                                          ‫‪58‬‬\n\f     ‫ه ـ اخلــاص بدعــوى  املدعــي  العــام  ضــد  كل  مــن‪ ...-2 ...-1/‬يف قضيــة‬\n     ‫مخــدرات علــى النحــو املوضــح بالقــرار وانتهــاء نظــر القضيــه  بحكــم‬\n     ‫فضيلتــه مبــا هــو مــدون ومفصــل بــه وبدراســة القــرار وصــورة ضبطــه‬\n              ‫وأوراق املعاملــة لــم يظهــر موجــب للمالحظــة  وبــاهلل التوفيــق ‪.‬‬\n\n\n\n\n‫‪59‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":52,"source_page_end":59,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7a5f0bfa4a2cde746b45ab25c95ebe128b810a9ace77b51bec3a2d2de1ecb2ac","normalized_text_hash":"0b87eceb778113df12624cb3b38cf410dda13bb8158a678d5c5778470221f6fd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p52-3432148"},{"id":"279d3f88-ddde-551e-8190-baae3e066a47","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلشيش املخدر واحلبوب احملظورة -حيازة احلشيش املخدر واحلبوب احملظورة -ترويج احلشيش املخدر واحلبوب احملظورة -تسليم احلشيش املخدر واحلبوب احملظورة - رجوع عن إقرار -وجود سوابق قضائية على املدعى عليه -ثبوت إدانة املدعى عليه -صرف نظر عن اإلدانة بالترويج -تعزير بالسجن واجللدواملنع من السفر والغرامة -مصاردة اجلوال والشريحة","document_number":"34203080","case_number":"3480271","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/1","year":"1434","subject":"مخدرات -تعاطي احلشيش املخدر واحلبوب احملظورة -حيازة احلشيش املخدر واحلبوب احملظورة -ترويج احلشيش املخدر واحلبوب احملظورة -تسليم احلشيش املخدر واحلبوب احملظورة - رجوع عن إقرار -وجود سوابق قضائية على املدعى عليه -ثبوت إدانة املدعى عليه -صرف نظر عن اإلدانة بالترويج -تعزير بالسجن واجللدواملنع من السفر والغرامة -مصاردة اجلوال والشريحة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 34203080 :‬تاريخه‪1434/5/1 :‬هـ  ‬\n                       ‫رقم الدعوى‪3480271 :‬‬\n       ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪  34269418‬تاريخه‪1434/7/16 :‬هـ‬\n\n\n\n‫مخــدرات‪ -‬تعاطــي احلشــيش املخــدر واحلبــوب احملظــورة ‪ -‬حيــازة‬\n‫احلشــيش املخــدر واحلبــوب احملظــورة ‪ -‬ترويــج احلشــيش املخــدر‬\n‫واحلبــوب احملظــورة ‪ -‬تســليم احلشــيش املخــدر واحلبــوب احملظــورة ‪-‬‬\n‫رجــوع عــن إقــرار ‪ -‬وجــود ســوابق قضائيــة علــى املدعــى عليــه ‪ -‬ثبــوت‬\n‫إدانــة املدعــى عليــه‪ -‬صــرف نظــر عن اإلدانة بالترويج ‪ -‬تعزير بالســجن‬\n‫واجللدواملنــع مــن الســفر والغرامــة ‪ -‬مصــاردة اجلــوال والشــريحة‬\n                                                              ‫املســتخدمة‪.‬‬\n\n\n\n\n‫‪ -1‬الفقــرة (‪ )2‬مــن املــادة (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام‬\n                                     ‫مكافحــة املخــدرات واﻤﻟﺆﺛﺮات اﻟﻌﻘﻠﻴﺔ‪.‬‬\n‫‪ -2‬والفقــرة (‪ )2-1‬مــن املــادة (‪ )29‬واملــادة (‪ )9‬مــن نظــام الســجن‬\n                                                                  ‫والتوقيــف‪.‬‬\n\n\n\n‫أقيمــت علــى املدعــى عليهمــا دعــوى جنائيــة لقيــام املدعــى عليــه األول‬\n‫بتســليم املخــدرات للمدعــى عليــه الثانــي ومحاولــة الثانــي إدخالهــا‬\n‫للســجن‪ ،‬أنكــر املدعــى عليهمــا الدعــوى وأقــر املدعــى عليــه الثانــي‬\n‫بواقعــة القبــض‪ ،‬مت القبــض علــى املدعــى عليهمــا وبحوزتهــم مــادة‬\n\n                                                                                  ‫‪60‬‬\n\f      ‫احلشــيش   أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة‬\n      ‫للمخدرات‪،‬كمــا تبــن وجــود ســوابق متعــددة وطلــب املدعــي العــام‬\n     ‫تطبيــق النظــام مــن نظــام مكافحــة املخــدرات واﻤﻟﺆﺛﺮات اﻟﻌﻘﻠﻴﺔ ‬\n      ‫ونظــام الســجن والتوقيــف‪ ،‬حكمــت احملكمــة بثبــوت إدانــة املدعــى‬\n      ‫عليــه الثانــي باحليــازة وتوجهــت التهمــة لــأول بتســليم احلبــوب احملظــورة‬\n      ‫وصــرف النظــر عــن إدانــة املدعــى عليهمــا بالترويــج‪ ،‬وســجن الثانــي‬\n      ‫ثمــان ســنوات وغرامــة ماليــة قدرها ثالثة آالف ري ــال‪ ،‬وجلده خمســمائة‬\n      ‫جلــدة مفرقــة علــى عشــر دفعــات بــن كل دفعــة وأخــرى أســبوعا‪،‬‬\n      ‫ومنعــه مــن الســفر خــارج البــاد بعــد انتهــاء محكوميتــه مــدة مماثلــة‬\n      ‫حملكوميتــه‪ ،‬وســجن املدعــى عليــه الثانــي ثــاث ســنوات تســتأنف‬\n      ‫بعــد انتهــاء محكوميتــه حليازتــه املخــدرات‪ ،‬ومصــادرة شــرائح اجلــوال‪،‬‬\n      ‫وســجن املدعــى عليــه األول ثمــان ســنوات‪ ،‬وجلــده خمســمائة جلــدة‬\n      ‫مفرقــة علــى عشــر دفعــات بــن كل دفعــة وأخــرى أســبوعا‪ ،‬اعتــرض‬\n      ‫املدعــى عليهمــا علــى احلكــم‪ ،‬صــدق احلكــم مــن محكمة االســتئناف‪.‬‬\n\n\n\n\n‫‪61‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪..........‬وتاريــخ‬\n‫‪1434/02/18‬ه ـ املقيــدة باحملكمــة برقــم ‪ 1434/02/17..........‬ه ـ‬\n‫ففــي يــوم الســبت املوافــق‪ 1434/02/23‬ه ـ افتتحــت اجللســة الســاعة ‪15‬‬\n‫‪ / 11 :‬وفيهــا تقــدم املدعــي العــام ‪.......... /‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ( ‪ )..........‬وتكليــف رقــم ( ‪ )..........‬وتاريــخ ‪/ 06‬‬\n‫‪1433 / 03‬ه ـ بالئحــة دعــوى وفيهــا أدعــي علــى ‪)43(..........-1  /‬عامـ ًا‬\n‫‪ ،‬ســعودي اجلنســية‪ ،‬مبوجــب الهويــة الوطنيــة رقم(‪)..........‬متســبب‪،‬‬\n‫موقــوف بالســجن العــام مبحافظــة جــدة علــى ذمــة قضيــة أخــرى مبوجــب‬\n                    ‫مذكــرة توقيــف رقــم (‪)..........‬وتاريخ‪1422/12/9‬هــ‪.‬‬\n‫‪ )43(..........-2‬عام ـ ًا ‪ ،‬ســعودي اجلنســية‪،‬مبوجب الهويــة الوطنيــة‬\n‫رقــم(‪ )..........‬متســبب‪،‬موقوف بالســجن العــام مبحافظــة جــدة علــى ذمــة‬\n                    ‫قضيــة أخــرى رقــم (‪ )..........‬وتاريخ‪14331/9/4‬هــ‪.‬‬\n ‫بتاريخ ‪1433/11/30‬هـ مت القبض على املدعى عليهما من قبل ضابط‬\n ‫وحــدة املستشــفيات باملديريــة العامــة للســجون مبحافظــة جــدة بشــعبة‬\n ‫االصالحيــة حيــث مت ضبــط (‪)152.9‬مائــة وإثنــان وخمســن جرام ـ ًا‬\n ‫وتســعة أعشــار اجلــرام مــن مــادة احلشــيش املخــدر و(‪ )3‬ثــاث شــرائح‬\n ‫جــوال بحــوزة الثانــي كمــا مت العثــور علــى قطعة تــزن (‪ )114‬مائة وأربعة‬\n‫عشــر جرامـ ًا مــن مــادة احلشــيش املخــدر و(‪ )276‬مائتــن وســت وســبعني ‬\n ‫حبــة حتتــوي علــى مــادة اإلمفيتامــن املؤثــرة عقليـ ًا و(‪ )28‬ثمان وعشــرين‬\n\n                                                                                    ‫‪62‬‬\n\f       ‫حبــة حتتــوي علــى مــادة الكلونازيبــام حتــت كرســي األول‪،‬ومجموعــة‬\n     ‫مــن أوراق الشــامكان يضعهــا األول يف فنيلتــه الداخليــة مــن األمــام‪  .‬‬\n       ‫و أثبــت التقريــر الكيميائــي الشــرعي رقــم (‪ )..........‬لعام‪1433‬ه ـ‬\n       ‫إيجابيــة العينــة(أ) ممــا مت ضبطــه وإرســاله للتحليــل ملــادة احلشــيش‬\n       ‫املخــدر واحتواءهــا علــى املــادة الفعالــة لــه وايجابيــة العينــة(ب) ممــا مت‬\n       ‫ضبطــه وإرســاله للتحليــل ملــادة احلشــيش املخــدر واحتواءهــا علــى املــادة‬\n       ‫الفعالــة لــه واحتــواء العينــه (ج) ممــا مت ضبطــه وإرســاله للتحليــل ملــادة‬\n       ‫األمفيتامــن املؤثــرة عقليــا واحتــواء العينــه (د) ممــا مت ضبطــه وإرســاله‬\n       ‫للتحليــل لعقــار الكاونازيبــام املؤثــر عقليـ ًا املدرجــة باجلــدول رقــم (‪)2-1‬‬\n       ‫فئــة (أ‪،‬ب‪ ،‬د) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬‬\n       ‫وباســتجواب املدعــى عليــه الثاني‪/‬أقــر بحيــازة(‪ )114‬مائــة وأربعــة عشــر‬\n                                ‫جرامـ ًا مــن احلشــيش املخــدر وثالثــة شــرائح جــوال ‪.‬‬\n       ‫وإنتهى التحقيق إلى توجيه اإلتهام إلى املدعى عليه األول بتســلم(‪)114‬‬\n       ‫مائــة وأربعــة عشــر جرامـ ًا مــن احلشــيش املخــدر و (‪  )276‬مائتــن وســت‬\n       ‫وســبعني حبــة حتتــوي علــى مــادة األمفيتامــن املؤثــرة عقليــا و(‪)28‬ثمــان‬\n       ‫وعشــرين حبــة حتتــوي علــى مــادة الكلونازيبــام املؤثــرة عقلي ـ ًا بقصــد‬\n       ‫الترويــج‪ ،‬واتهــام الثانــي‪ 00000/‬بتســلم(‪)152.9‬مائه واثنــان وخمســن‬\n       ‫جرامـ ًا وتســعة أعشــار اجلــرام مــن احلشــيش املخــدر لــذات القصــد و(‪)3‬‬\n       ‫ثــاث شــرائح جــوال ومحاولــة إدخالهــا الســجن العــام‪ ،‬اســتنادا للفقــرة‬\n       ‫(‪ )2‬مــن املــادة الثالثــة مــن نظــام مكافحــة املخدرات واملؤثــرات العقلية‪،‬‬\n       ‫والفقــرة (‪ )2-1‬مــن املــادة (‪ )29‬مــن نظــام الســجن والتوقيــف ‪ ،‬وذلــك‬\n                                                            ‫لألدلــة والقرائــن التاليــة ‪-:‬‬\n       ‫‪-1‬مــا ورد يف إقــراره الثانــي املنــوه عنــه املــدون بدفتــر التحقيــق صفحــة‬\n\n\n‫‪63‬‬\n\f                                                 ‫(‪ )6‬واملرفــق لفــة رقــم (‪.)23‬‬\n‫‪-2‬مــا ورد يف محضــر املواجهــه املــدون بدفتــر التحقيــق صفحــه (‪)7‬‬\n                                                     ‫واملرفــق لفــه رقــم (‪)23‬‬\n   ‫ال املرفق لفة رقم (‪. )1‬‬ ‫‪ -3‬ما ورد يف محضر الضبط املنوه عنه تفصي ً‬\n‫‪ -4‬مــا ورد بالتقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــة‬\n                                                                   ‫رقــم(‪. )33‬‬\n‫وباالطــاع علــى صحيفــة ســوابقهما عثــر لــاول علــى تســع ســوابق (‬\n‫اربــع ســوابق حيــازة واســتعمال املخــدرات احداهــا مقترنــه بشــرب‬\n‫املســكرات وســابقة شــرب املســكرات مقترنــه بدخــول منــازل لغــرض‬\n‫ســيء وســابقه شــرب املســكرات مقترنــه بحيــازة مســكر وســابقة‬\n‫شــرب املســكرات وســابقة نشــل وســابقة ســرقه وعثــر للثانــي علــى‬\n‫تســع ســوابق ثــاث ســوابق شــرب املســكرات احدهــا مقترنــه بســرقة‬\n‫ســيارات وحيــازة املخــدرات وســابقه ســرقه وســابقه تكويــن عصابــه‬\n‫للســرقه وســابقه ســرقة ســيارات مقترنــه بالســلب وســابقة ســرقة‬\n‫اســطوانة غــاز مقترنــه بدخــول منــازل لغــرض ســيء وســابقة حيــازة‬\n                               ‫املخــدرات ‪ ،‬وســابقة اســتعمال مخــدرات ‪).‬‬\n‫وحيــث إن مــا أقــدم عليــه املدعــى عليهمــا وهمــا بكامــل أهليتهمــا‬\n‫املعتبــرة شــرعا مــن األفعــال احملرمــة شــرع ًا واملجرمــة نظام ـ ًا طبقــا‬\n‫للمــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫الصــادر باملرســوم امللكــي رقــم م‪ 39/‬وتاريــخ ‪1426/7/8‬ه ــواملعاقب‬\n‫عليهــا اســتنادا للمــواد (‪ )41،38‬مــع مراعــاة مــا ورد باملــادة (‪)62‬مــن ذات‬\n‫النظــام وللفقــرة (‪ )2‬مــن املــادة (‪ )29‬مــن نظــام الســجن والتوقيــف ‪ ،‬لــذا‬\n‫فإنــه يتعــن إحالتهمــا إلــى احملكمــة اجلزئيــة مبحافظــة جــدة اســتناد ًا‬\n\n\n                                                                                   ‫‪64‬‬\n\f     ‫للمادتــن (‪ )126 , 128‬مــن نظــام اإلجــراءات اجلزائيــة لطلــب إثبــات مــا‬\n     ‫أســند إليهمــا ومعاقبتهمــا بالعقوبــات األصليــة والتكميليــة التاليــة ‪-:‬‬\n     ‫‪-1‬بالســجن واجللــد والغرامــة لقــاء مــا أســند إليهمــا اســتناد ًا للفقــرة (‪)1‬‬\n     ‫وتشــديد العقوبــة علــى األول إســتناد ًا للحالة(ج)مــن الفقرة(‪)2‬مــن املــادة‬\n                                                             ‫(‪ )38‬مــن نظــام املخــدرات‬\n     ‫‪-2‬معاقبتهمــا بالســجن إســتناد ًا للفقرة(‪)2‬والفقرة(‪)1‬أيض ـ ًا لــأول مــن‬\n                                        ‫املــادة(‪ )29‬مــن نظــام الســجن والتوقيــف ‪.‬‬\n     ‫‪-3‬مصــادرة الشــرائح املضبوطــة مــن نــوع موبايلــي اســتناد ًا للمــادة (‪)9‬‬\n                                                        ‫مــن نظــام الســجن والتوقيــف ‪.‬‬\n     ‫‪-4‬منعهمــا مــن الســفر خلــارج اململكــة بعــد انتهــاء تنفيــذ عقوبتهمــا‬\n     ‫اســتنادا للفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام املخــدرات املشــار إليــه‪.‬‬\n     ‫كمــا اطلــب تشــديد العقوبــة عليهمــا لقــاء تعــدد ســوابقهما التــي‬\n     ‫لــم تردعهمــا عقوباتهــا إســتناد ًا لتعميــم ســمو نائــب وزيــر الداخليــة‬\n     ‫رقــم(‪ )93958/5/5/1‬وتاريخ‪1429/8/23‬ه ــوبسؤال املدعــى عليــه‬\n     ‫ا مــا ذكــره املدعــي‬  ‫األول ‪..........‬عــن دعــوى املدعــي العــام أجــاب قائ ـ ً‬\n     ‫العــام مــن اتهامــي بتســليم الكميــات وحيازتهــا فهــذا كلــه غيــر‬\n     ‫صحيــح وعلــي الســوابق التــي ذكرهــا هــذه إجابتــي وبســؤال املدعــى‬\n     ‫ا مــا ذكــره‬  ‫عليــه الثانــي ‪..........‬عــن دعــوى املدعــي العــام أجــاب قائ ـ ً‬\n     ‫املدعــي العــام مــن انــه قبــض علــي وبحوزتــي احلشــيش فهــذا صحيــح‬\n     ‫وأمــا مــا ذكــره مــن اتهامــي بالترويــج فهــذا غيــر صحيــح والصحيــح‬\n     ‫ذهبــت للمستشــفى للعــاج ووجــدت كيــس علــى األرض وأخذتــه بــدون‬\n     ‫قصــد منــي وضبــط بداخلــه املضبوطــات وعلــى الســوابق التــي ذكرهــا‬\n     ‫هــذه إجابتــي‪ .‬وبســؤال املدعــي العــام عــن بينتــه طلــب إمهالــه إلحضارهــا‬\n\n\n‫‪65‬‬\n\f‫فاســتجبت لطلبــه ‪ .‬رفعــت اجللســة بتاريــخ ‪1434 / 02 / 23‬ه ـ الســاعة‬\n‫احلاديــة عشــر والنصــف‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                    ‫وعلــى آلــه وصحبــه وســلم‪     .‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبحافظــة جــدة املســاعد برقــم ‪..........‬وتاريــخ‬\n‫‪1434/02/18‬ه ــاملقيدة باحملكمة برقم ‪ 1434/02/17..........‬هـ ففي‬\n‫يــوم اإلثنــن املوافــق ‪ 1434/04/29‬ه ـ افتتحــت اجللســة الســاعة الثامنــة‬\n‫وخمس وأربعون دقيقة ‪ ،‬وفيها حضر املدعي واملدعى عليهما وبســؤال‬\n‫ا لقــد مت طلــب البينــة مــن خــال‬    ‫املدعــي العــام عــن بينتــه أجــاب قائ ـ ً‬\n‫أربــع طلبــات وملتــرد لــذا اكتفــى مبــا ورد بــأوراق املعاملــة هــذه إجابتــي‬\n‫وبســؤال املدعــى عليــه الثانــي عــن قصــده مــن احليــازة اجــاب ليــس لــي‬\n‫قصــد هــذا وقــد جــرى االطــاع علــى إقــرار املدعــى عليــه الثانــي واملرفــق‬\n‫باملعاملــة علــى لفــة رقــم ‪ 23‬وعلــى محضــر املواجهــه واملرفــق علــى لفــة‬\n‫رقــم ‪ 3‬وعلــى التقريــر الكيميائــي الشــرعي رقــم ‪..........‬لعــام ‪1433‬ه ـ‬\n‫واملرفــق علــى لفــة رقــم ‪ 33‬يتضمــن ايجابيــة مــامت ضبطــه واحتــواء املــادة‬\n‫املضبوطــه علــى احلشــيش املخــدرو علــى مــادة اإلمفيتامــن املؤثــرة عقليـ ًا‬\n‫وعلــى عقــار الكلونازيبــام املؤثــرة عقليــا ًســو علــى محضــر االســتجواب‬\n‫ومحضــر القبــض وعلــى صحيفتــي ســوابقهما فوجــد كمــا ذكــر‬\n‫ـاء علــى ماتقــدم مــن الدعــوى واإلجابــه ومــا قــرره‬        ‫املدعــي العــام فبنـ ً‬\n‫الطرفــان وحيــث صــادق املدعــى عليــه الثانــي علــى حيــازة احلشــيش‬\n‫واعتــرف بشــرائح اجلــوال وال بينــة للمدعــي علــى املدعــى عليــه األول ‪...‬‬\n‫وملــا تضمنــه التقريــر الكيميائــي الشــرعي املشــار اليــه اعــاه ومحضــر‬\n\n\n                                                                                          ‫‪66‬‬\n\f     ‫القبــض ومحضــر االســتجواب ولتعــدد ســوابقهما وحيــث ماقامــا بــه فعل‬\n     ‫محــرم شــرع ًا يســتحق اعليــه العقوبــة طبق ـ ًا للقواعــد الشــرعية كمــا‬\n     ‫يســتحق املدعــى عليــه الثانــي العقوبــة وفقـ ًا للمادتــن ‪ 56 ، 39‬مــن نظــام‬\n     ‫مكافحــة املخــدرات كمــا يســتحق العقوبــة وفقــا للمادتــن ‪9 ، 29‬‬\n     ‫مــن نظــام الســجن والتوقيــف ولــكل مــا تقــدم فقــد ثبــت لــدي إدانــة‬\n     ‫املدعــى عليــه الثانــي بحيــازة مائــة واربعــه عشــر جرام ـ ًا مــن احلشــيش‬\n     ‫املخــدر بــدون قصــد الترويــج والتعاطــي وثــاث شــرائح جــوال وتوجــه‬\n     ‫الشــبهه بإدانــة املدعــى عليــه األول بتســليم مائــة وأربعــة عشــر جرامــا‬\n     ‫مــن احلشــيش ومائتــان وســت وســبعون حبــه مــن حبــوب اإلمفيتامــن‬\n     ‫وثمــان وعشــرون حبــه مــن حبــوب الكلونازيبــام بقصــد الترويــج كمــا‬\n     ‫تتوجــه الشــبه بإدانــة املدعــى عليــه الثانــي بتســليم مائــة واثنــان وخمســون‬\n     ‫جرام ـ ًا وتســعة أعشــار اجلــرام مــن احلشــيش املخــدر بقصــد الترويــج‬\n     ‫وقــررت تعزيرهمــا لقــاء مــا اســند إليهمــا مبــا يلــي أوالً‪ :‬صــرف النظــر‬\n     ‫عــن إدانــة املدعــى عليهمــا بالترويــج ومعاقبتهمــا وفــق املــادة ‪38‬مــن نظــام‬\n     ‫مكافحــة املخــدرات وللمدعــى عليــه االول املــادة ‪ 56‬مــن ذات النظــام‬\n     ‫واملــادة ‪29‬مــن نظــام الســجن والتوقيــف ثاني ـاً‪ :‬مجــازات املدعــى عليــه‬\n     ‫الثانــي بســجنه خمــس ســنوات وغرامــه ماليــة قدرهــا ‪ 3000‬ثالثــة آالف‬\n     ‫ريــال ومنعــه مــن الســفر خــارج البــاد بعــد انتهــاء محكوميتــه مــدة‬\n     ‫مماثلــة حملكوميتــه وذلــك وفــق املادتــن ‪ 56 ، 39‬مــن نظــام مكافحــة‬\n     ‫املخــدرات ثانيــا ســجن املدعــى عليــه الثانــي ثــاث ســنوات تســتأنف بعــد‬\n     ‫انتهــاء محكوميتــه حليــازة املخــدرات ومصــادرة شــرائح اجلــوال وذلــك‬\n     ‫وفــق املادتــن ‪ 9 ، 29‬مــن نظــام الســجن والتوقيــف ثالثـاً‪ :‬ســجن املدعــى‬\n     ‫عليــه األول ثمــان ســنوات وجلــده ‪ 500‬خمســمائة جلــده مفرقــه علــى‬\n\n\n‫‪67‬‬\n\f‫عشــر دفعــات بــن كل دفعــة واخــرى عشــرة أيــام وذلــك لقــاء التهمــة‬\n‫رابع ـ ًا ‪ :‬جلــد املدعــى عليــه الثانــي خمســمائة جلــده مفرقــه علــى عشــر‬\n‫دفعــات بــن كل دفعــة وأخــرى عشــرة أيــام وذلــك لقــاء تهمــة الترويــج‬\n‫وبذلــك حكمــت‪ ،‬وبعــرض احلكــم علــى املدعــي العــام واملدعــى عليهما‬\n‫قــرر املدعــي العــام معارضتــه بالئحــة وقــرر املدعــى عليهمــا املعارضــه‬\n‫بالئحه‪،‬جــرى النطــق باحلكــم بتاريــخ ‪1434/4/29‬ه ـ الســاعة التاســعة‬\n‫‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‬\n‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة‬\n‫االســتئناف يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة جــدة برقــم‪..........‬‬\n‫وتاريخ‪1434/6/26‬هاملرفق بها القرار رقم‪ ..........‬وتاريخ‪1434/5/1‬هـ‬\n‫الصــادر مــن فضيلــة الشــيخ‪........../‬القاضي باحملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة املتضمــن دعــوى املدعــي العــام ضــد‪ .......... /‬ســعودي‬\n‫اجلنســية ورفيقــه يف قضيــة مخــدرات احملكــوم فيــه مبــا دون بباطــن‬\n‫القــرار ‪ ،‬وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة قررنــا‬\n‫املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                 ‫وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪68‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":60,"source_page_end":68,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4c4a3024ee0fe513d970ecefc2f3f3fe2841e3a429b47f37cf42cb3edca7273c","normalized_text_hash":"4fef6128f60cc3e0d132316bd3a0f1259d5ca67797cc820a612d4ab90afc7399","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p60-34203080"},{"id":"a876df2f-56e5-50fd-b4f4-cd2884bbc1b0","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -مسكر -تعاطي احلشيش -شرب املسكر -إقامة حد املسكر -منع من السفر.","document_number":"3442674","case_number":"3481710","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/20","year":"1434","subject":"مخدرات -مسكر -تعاطي احلشيش -شرب املسكر -إقامة حد املسكر -منع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪  3442674 :‬تاريخه ‪1434/02/20 :‬هـ‬\n                           ‫رقم الدعوى‪3481710 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34238706‬تاريخه‪1434/06/12 :‬هـ‬\n\n\n\n     ‫مخــدرات ‪ -‬مســكر ‪ -‬تعاطــي احلشــيش ‪ -‬شــرب املســكر ‪ -‬إقامــة حــد‬\n                                               ‫املســكر ‪ -‬منــع مــن الســفر‪.‬‬\n\n\n\n\n     ‫اب‬ ‫ال ْم ُر َو ْالَ ْي ِس ُر َوا َأل َ‬\n     ‫نص ُ‬                                ‫نا ْ َ‬   ‫آم ُنو ْا ِإ َّ َ‬  ‫‪ -1‬قول اهلل تعالى «( َيـا َأ ُّي َها ا َّلذِ َ‬\n                                                                  ‫ين َ‬\n               ‫ون )‪.‬‬ ‫وه َل َع َّل ُك ْم ُت ْفل ُِح َ‬\n                                                   ‫اج َتن ُِب ُ‬                 ‫س ِّم ْن َع َملِ َّ‬\n                                                                 ‫الش ْي َطانِ فَ ْ‬                    ‫َوا َأل ْز َال ُم ِر ْج ٌ‬\n              ‫‪ -2‬املادة (‪ )56/1‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n\n\n\n\n     ‫تقــدم مواطــن ملركــز الشــرطة ببــاغ تضمــن تعرضــه للعقــوق والتهديــد‬\n     ‫مــن قبــل ابنــه املتعاطــي للمســكر واحلشــيش‪ ،‬فــرزت أوراق بقضيــة‬\n     ‫العقــوق ـ طلــب املدعــي العــام إقامــة حــد املســكر علــى املدعــى عليــه‬\n     ‫لشــربه املســكر وتعاطيــه احلشــيش‪ ،‬أقــر املدعــى عليــه مبــا نســب إليــه‬\n     ‫‪ ،‬صــدر احلكــم  بإثبــات إدانــة املدعــى عليــه  بشــرب املســكر وتعاطــي‬\n     ‫احلشــيش‪ ،‬احلكــم بإقامــة حــد املســكر علــى املدعــى عليــه ومنعــه مــن‬\n                             ‫الســفر‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪69‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة مــن فضيلــة الرئيــس‬\n‫برقم  وتاريخ ‪ 1434 / 2 / 18‬هـ املقيدة باحملكمة برقم  وتاريخ ‪/ 18‬‬\n‫‪ 1434 / 2‬ه ـ واملتعلقــة بدعــوى املدعــي العــام ‪ ......./‬ضــد ‪ ،....... /‬حامــل‬\n‫الســجل املدنــي رقــم (‪ )....‬ففــي يــوم  األربعــاء ‪1434/ 2 / 20‬ه ـ فتحــت‬\n‫اجللســة الســاعة ‪  10 : 00‬وفيهــا حضــر  املدعــي العــام واملدعــى عليــه‬\n‫املدونــة هويتــه بعاليــه وقــدم املدعــي العــام الئحــة الدعــوى املتضمنــة مــا‬\n‫يلــي ‪ ( :‬أدعــي علــى‪ ،‬البالــغ مــن العمــر (‪ )23‬عام ـ ًا ‪ ،‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ )....‬غيــر محصــن‪ ،‬عاطــل عــن العمــل‪،‬‬\n‫وأحيــل لســجن محافظــة ‪ ....‬اســتناد ًا للقــرار الــوزاري رقــم (‪)1900‬‬\n‫وتاريــخ ‪1428/7/9‬ه ـ ‪ ،‬حيــث أنــه بتاريــخ ‪1433/12/10‬ه ـ ورود‬\n‫بــاغ الــى مركــز شــرطة صفــوى مــن املواطــن‪ /‬مفــاده قيــام ابنــه الــذي‬\n‫يســكن لديــه يف منزلــه يف محافظــة ‪ ....‬باالعتــداء عليــه وتهديــده بآلــة‬\n‫حــادة وبقيامــه بعقــوق والديــه والتلفــظ عليهمــا كمــا أفــاد بــأن أبنــه‬\n‫املذكــور يقــوم بتعاطــي املخــدرات (أفــرزت أوراق مســتقلة بقضيــة‬\n‫العقــوق وعوجلــت مــن قبــل جهــة االختصــاص)‪ .‬وباســتجواب املدعــى‬\n‫عليــه أقــر بقيامــه بشــرب املســكر وأن أخــر مــرة شــرب املســكر فيهــا‬\n‫هــو قبــل القبــض عليــه بيومــن وأنــه يتعاطــى احلشــيش املخــدر وآخــر‬\n‫مــرة تعاطــى احلشــيش املخــدر قبــل ســنة ونصــف مــن القبــض عليــه‪.‬‬\n‫وقــد أســفر التحقيــق معــه الــى توجيــه االتهــام لــه وبشــرب املســكر‬\n‫وتعاطــي احلشــيش املخــدر ‪ ،‬وذلــك لألدلــة والقرائــن التاليــة ‪ -1:‬إقــرار‬\n\n                                                                                      ‫‪70‬‬\n\f       ‫املدعــى عليــه واملــدون علــى صــورة ملــف التحقيــق واملرفقــة علــى اللفتــن‬\n       ‫رقــم (‪ )11.10‬واملــدون علــى الصفحتــن رقــم ( ‪ )3.2‬مــن ملــف ضبــط‬\n       ‫إجــراءات قضيــة ‪ -2.‬مــا جــاء يف إفــادة املواطــن ‪ /‬واملدونــة علــى صــورة‬\n       ‫تقريــر األحــوال األمنيــة واملرفــق علــى اللفــة رقــم (‪ .)5-1‬وبالبحــث عــن‬\n       ‫ســوابقه عثــر لــه علــى ســابقة عقــوق والديــن‪ .‬وحيــث إن مــا أقــدم عليــه‬\n       ‫املذكــور ‪ -‬وهــو بكامــل أهليتــه املعتبــرة شــرعا ‪ -‬فعــل محــرم ومعاقــب‬\n     ‫عليــه شــرع ًا ونظام ـ ًا لــذا اطلــب مــا يلــي‪ :‬أوال‪ :‬اثبــات شــربه للمســكر  ‬\n       ‫واحلكــم عليــه بحــد الســكر ‪ .‬ثانيــا‪ :‬إثبــات مــا اســند إليــه حيــال تعاطــي‬\n       ‫احلشــيش املخــدر وفــق الفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام‬\n       ‫مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم عليــه مبــا يلــي ‪-1 :‬‬\n       ‫عقوبــة الســجن الــواردة بالفقــرة رقــم(‪ )1‬مــن املــادة رقــم(‪ )41‬مــن النظــام‬\n       ‫‪ -2 .‬منعــه مــن الســفر وفــق الفقــرة (‪ )1‬مــن املــادة رقــم(‪ )56‬مــن النظــام‪.‬‬\n       ‫وبــاهلل التوفيــق) ا‪ .‬ه ـ وبعــرض الدعــوى علــى املدعــى عليــه أجــاب بقولــه‬\n       ‫مــا جــاء يف االتهــام املوجــه لــي كلــه صحيــح هــذا جوابــي فبنــاء علــى مــا‬\n       ‫تقــدم مــن الدعــوى واإلجابــة وبنــاء علــى إقــرار املدعــى عليــه مبــا نســب‬\n       ‫إليــه ولقولــه تعالــى ‪( :‬يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n       ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) فقــد‬\n       ‫حكمــت مبــا يلــي ‪-1 :‬ثبــوت إدانــة املدعــى عليــه بشــرب املســكر‬\n       ‫وتعاطــي احلشــيش املخــدر ‪ -2‬جلــد املدعــى عليــه ثمانــن جلــدة حــد‬\n       ‫املســكر  وأفهمتــه بانطبــاق املــادة ‪ 1/56‬مــن نظــام املخــدرات عليــه‬\n       ‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام عــدم قناعتــه ورغبتــه‬\n       ‫رفــع احلكــم حملكمــة االســتئناف بــدون الئحــة اعتراضيــة وقــرر‬\n       ‫املدعــى عليــه قناعتــه وبــاهلل التوفيــق وقــد مت االنتهــاء مــن حتريــره يف‬\n\n‫‪71‬‬\n\f         ‫متــام الســاعة ‪ 10 : 20‬مــن يــوم األربعــاء ‪1434/ 2 / 20‬ه ـ ‪،،،‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم  الســبت ‪1434/ 5 / 4‬ه ـ فتحــت اجللســة‬\n‫الســاعة (‪  )9 : 30‬وقــد وردتنــا املعاملــة وبرفقهــا قــرار أصحــاب الفضيلــة‬\n‫قضــاة محكمــة االســتئناف باملنطقــة الشــرقية رقــم ‪ 34193816‬يف‬\n‫‪1434/4/21‬ه ـ املتضمــن املالحظــة مبــا نصــه ‪( :‬أوال ‪ :‬أن إجابــة املدعــى‬\n‫عليــه غيــر مكتملــة ‪ .‬ثاني ـ ًا ‪ /‬أفهــم فضيلتــه بانطبــاق املــادة ‪ 1/56‬ولــم‬\n‫يبينهــا حتــى تعلــم لــدى جهــات التنفيــذ) ا‪.‬ه ـ واجلــواب أنــه قــد حضــر يف‬\n‫هــذه اجللســة املدعــى عليــه وجــرى اســتدراك النقــص املشــار إليــه وأخــذ‬\n‫توقيعــه عليــه كمــا جــرى اســتدراكه يف القــرار وأمــا املــادة ‪ 1/56‬فهــي‬\n‫املنــع مــن الســفر مــدة ســنتني وبــاهلل التوفيــق وقــد مت االنتهــاء مــن حتريره‬\n                                                    ‫يف متــام الســاعة (‪.  )9 : 45‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم  الثالثــاء ‪1434/ 6 / 27‬هــ  فتحــت‬\n‫اجللســة الســاعة (‪  )9 : 15‬وقــد وردتنــا املعاملــة وبرفقهــا قــرار أصحــاب‬\n‫الفضيلــة قضــاة محكمــة االســتئناف باملنطقــة الشــرقية رقــم   يف‬\n‫‪1434/6/12‬ه ـ املتضمــن املصادقــة علــى احلكــم  وبــاهلل التوفيــق وقــد‬\n                      ‫مت االنتهــاء مــن حتريــره يف متــام الســاعة (‪.  )9 : 25‬‬\n\n\n\n\n                                                                                        ‫‪72‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":69,"source_page_end":72,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"42b53ff85b8724a126f24086f5ab47b71c9472d3e127e6a4081a35bd47e090d2","normalized_text_hash":"c02615501cba80b0cfd4e2f32ac422a4fe42dbd8721d8970acc87802226bbfd6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p69-3442674"},{"id":"54421161-31e1-5b41-89b8-0c5e3c4dbdf1","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلشيش املخدر -شرب املسكر -قيادة السيارة حتت تأثير املسكر اإلقرار -إقامة حد املسكر -املنع من السفر -1ما رواه أنس بن مالك رضي اهلل عنه أن النبي صلى اهلل عليه وسلم ( :أتى برجل قد شرب اخلمر فجلده بجريدتن نحو أربعن قال وفعله أبو بكر فلما كان عمر استشار الناس فقال عبدالرحمن بن عوف أخف احلدود ثمانون فأمر به) متفق عليه -2وعن علي رضي اهلل عنه يف قصة الوليد بن عقبة قال ( :جلد","document_number":"32343839","case_number":"32240283","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1432/12/02","year":"1434","subject":"مخدرات -تعاطي احلشيش املخدر -شرب املسكر -قيادة السيارة حتت تأثير املسكر اإلقرار -إقامة حد املسكر -املنع من السفر -1ما رواه أنس بن مالك رضي اهلل عنه أن النبي صلى اهلل عليه وسلم ( :أتى برجل قد شرب اخلمر فجلده بجريدتن نحو أربعن قال وفعله أبو بكر فلما كان عمر استشار الناس فقال عبدالرحمن بن عوف أخف احلدود ثمانون فأمر به) متفق عليه -2وعن علي رضي اهلل عنه يف قصة الوليد بن عقبة قال ( :جلد","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 32343839 :‬تاريخه‪1432/12/02 :‬هـ‬\n                        ‫رقم الدعوى‪32240283 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫تاريخه‪1434/6/6 :‬هـ‬        ‫‪34232106‬‬\n\n\n\n     ‫مخــدرات ‪ -‬تعاطــي احلشــيش املخــدر ‪ -‬شــرب املســكر ‪ -‬قيــادة الســيارة‬\n      ‫حتــت تأثيــر املســكر ـ اإلقــرار ‪ -‬إقامــة حــد املســكر ‪ -‬املنــع مــن الســفر‬\n\n\n\n\n     ‫‪-1‬مــا رواه أنــس بــن مالــك رضــي اهلل عنــه أن النبــي صلــى اهلل عليــه‬\n     ‫وســلم ‪ ( :‬أتــى برجــل قــد شــرب اخلمــر فجلــده بجريدتــن نحــو أربعــن‬\n     ‫قــال وفعلــه أبــو بكــر فلمــا كان عمــر استشــار النــاس فقــال عبدالرحمن‬\n                         ‫بــن عــوف أخــف احلــدود ثمانــون فأمــر بــه) متفــق عليــه‬\n     ‫‪-2‬وعــن علــي رضــي اهلل عنــه يف قصــة الوليــد بــن عقبــة قــال ‪ ( :‬جلــد‬\n     ‫النبــي صلــى اهلل عليــه وســلم أربعــن وجلــد أبــو بكــر أربعــن وجلــد عمــر‬\n                                       ‫ثمانــن وهكــذا أحــب إلـ َّـي ) أخرجــه مســلم‬\n     ‫‪-3‬وعــن معاويــة رضــي اهلل عنــه عــن النبــي صلــى اهلل عليــه وســلم ‪ ( :‬أنــه‬\n                ‫قــال شــارب اخلمــر إذا شــرب فاجلــدوه ) أخرجــه أحمــد واألربعــة‬\n                  ‫‪-4‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر  و تعاطــي‬\n     ‫احلشــيش املخــدر و قيــادة الســيارة حتــت تأثيرهمــا وطلــب املدعــي العــام‬\n     ‫إثبــات  مــا أســند للمدعــى عليــه واحلكــم عليــه بعقوبة حد املســكر لقاء‬\n\n‫‪73‬‬\n\f‫تعاطيــه للحشــيش ‪ .‬العقوبــة الــواردة يف الفقــرة األولــى من املادة (‪ )41‬من‬\n‫نظــام مكافحــة املخــدرات لتعاطيــه احلشــيش املخــدر ‪ ،‬العقوبــة الــواردة‬\n‫يف الفقــرة األولــى مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات وذلــك‬\n‫مبنعــه مــن الســفر خــارج البــاد ‪ ،‬إثبــات قيادتــه للســيارة حتــت تأثيــر‬\n‫شــرب املســكر و تعاطيــه احلشــيش املخــدر و إفهامــه بــأن عقوبتــه عائــدة‬\n‫للجهــة املختصــة حيــث انــه قبــض عليــه مــن قبــل رجــال الضبــط اجلنائــي‬\n‫إثــر اشــتراكه مــع أحــد األشــخاص بســرقة محطــة وقــود حتــت اإلنشــاء‬\n‫وعنــد القبــض عليــه تبــن أنــه بحالــة ســكر وباستشــمامه تبــن انبعــاث‬\n‫رائحــة املســكر مــن جوفــه وبتحليــل ســوائله أثبــت تقريــر الســموم‬\n‫الشــرعية إيجابيتهمــا ملركبــات احلشــيش ‪،‬كمــا أقــر املدعــى عليــه مبــا‬\n‫نســب إليــه بنــاء علــى مــا تقــدم حكمــت احملكمــة بإقامــة حــد املســكر‬\n‫عليــه بجلــده ثمانــن جلــدة واملنــع مــن الســفر ملــدة ســنتني وصــرف النظــر‬\n‫عــن تطبيــق املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات وإثبــات إدانــة‬\n‫املدعــى عليــه بقيــادة الســيارة حتــت تأثيــر املســكر و عقوبتــه يف ذلــك‬\n‫عائــدة للجهــة املختصــة‪ ،‬قنــع املدعــى عليــه باحلكــم وقــرر املدعــي العــام‬\n ‫االعتــراض مــن غيــر الئحــة وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n                                                                                    ‫‪74‬‬\n\f     ‫اجلزئيــة‬\n        ‫ّ‬      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪....‬القاضــي يف احملكمــة‬\n     ‫باالحســاء  وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫اجلزئية يف محافظة االحساء برقم ‪ 32240283‬وتاريخ ‪1432/06/21‬هـ  ‬\n       ‫املقيــدة باحملكمــة برقــم ‪ 32750534‬وتاريــخ ‪1432/06/21‬هــ  ففــي‬\n     ‫يــوم  الســبت املوافق‪1432/12/02‬ه ـ أفتتحــت اجللســة الســاعة ‪  10 : 30‬‬\n       ‫وفيهــا حضــر  املدعــي العــام  ‪....‬واملدعــى عليــه  ‪  ....‬ســعودي اجلنســية‬\n       ‫مبوجــب الســجل املدنــي رقــم   ‪....‬وادعــى املدعــي العــام قائــا يف دعــواه‬\n       ‫إنــه بتاريــخ ‪1432/5/1‬ه ـ قبــض عليــه مــن قبــل رجــال الضبــط اجلنائــي‬\n     ‫مبركــز شــرطة الرقيقــة مبحافظــة األحســاء إثــر اشــتراكه مــع املدعــو  ‬\n       ‫‪....‬بســرقة محطــة وقــود حتــت اإلنشــاء ( فــرزت لقضيــة الســرقة أوراق‬\n       ‫مســتقلة ومعاجلتهــا مــن قبــل جهــة االختصــاص ) وعنــد القبــض عليــه‬\n       ‫تبــن أنــه بحالــة ســكر ‪ ،‬وباستشــمامه تبــن انبعــاث رائحــة ا ملســكر‬\n       ‫مــن جوفــه ‪ ،‬وبتحليــل عينــة مــن ســوائله أثبــت تقريــر الســموم الشــرعية‬\n     ‫رقــم ( ‪ 753‬م ‪ .‬أ ) لعــام ‪1432‬ه ـ إيجابيتهــا ملركبــات احلشــيش املخــدر‬\n     ‫وباســتجواب املدعــى عليــه أقــر بصحــة واقعــة القبــض عليــه وتعاطيــه‬\n     ‫احلشــيش املخــدر ‪ ،‬وصــدق إقــراره شــرع ًا بذلــك ‪ ،‬كمــا أقــر حتقيق ـ ًا‬\n     ‫بشــربه املســكر وقيــادة الســيارة حتــت تأثيرهــا عنــد القبــض عليــه‬\n     ‫وقــد أســفر التحقيــق عــن توجيــه االتهــام لــه بشــرب املســكر وتعاطــي‬\n     ‫احلشــيش املخــدر وقيــادة الســيارة حتــت تأثيرهمــا‪ ،‬وذلــك لألدلــة‬\n     ‫والقرائــن التاليــة‪ :‬ـ‪ 1‬إقــراره املصــدق عليــه شــرع ًا وحتقيق ـ ًا املــدون‬\n     ‫علــى   الصفحــة رقــم (‪ )3‬مــن ملــف ضبــط اإلجــراءات واللفــة رقــم‬\n\n‫‪75‬‬\n\f‫(‪-2.)3‬تقريــر الدوريــات األمنيــة املرفــق صــورة منهــا علــى اللفــات رقــم  ‬\n  ‫(‪ 24‬ـ ‪-3 )26‬محضــر االستشــمام املرفــق صــورة منــه علــى اللفــة رقــم (‬\n  ‫‪-4 ) 20‬تقريــر الســموم الشــرعية املرفــق علــى اللفــة رقــم ( ‪ ) 33‬وببحــث‬\n  ‫ســوابقه لــم يعثــر لــه علــى ســوابق جنائيــة مســجلة وحيــث إن مــا أقــدم‬\n  ‫عليــه املذكــور ـ وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ـ فعــل محــرم‬\n  ‫ومعاقــب عليــه شــرع ًا ونظامـ ًا يف ضــوء الفقــرة الثانيــة مــن املــادة الثالثــة‬\n  ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n  ‫امللكــي الكــرمي رقــم ( م‪ ) 39/‬وتاريــخ ‪1432/7/8‬ه ـ أطلــب إثبــات‬\n  ‫مــا أســند إليــه واحلكــم عليــه مبــا يلــي ‪ :‬ـ ‪ 1‬ـ بعقوبــة حــد املســكر لقــاء‬\n  ‫شــربه لــه ولتعاطيــه احلشــيش املخــدر  ـ ‪ 2‬ـ بالعقوبــة املــواردة يف الفقــرة‬\n  ‫األولــى مــن املــادة ( ‪ ) 41‬مــن النظــام املشــار إليــه أعــاه لتعاطيه احلشــيش‬\n  ‫املخــدر ‪ 3‬ـ بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة ( ‪ ) 56‬مــن‬\n  ‫النظــام املشــار إليــه أعــاه وذلــك مبنعــه مــن الســفر إلــى خــارج البــاد ‪4.‬ـ‬\n  ‫إثبــات قيادتــه للســيارة حتــت تأثيــر شــرب املســكر وتعاطيــه احلشــيش‬\n  ‫املخــدر وإفهامــه بــأن عقوبتــه الــواردة يف الفقــرة األولــى مــن املــادة ( ‪68‬‬\n  ‫) مــن نظــام املــرور تقــرر مــن اجلهــة املختصــة هــذه دعــواي وبعرضهــا علــى‬\n  ‫املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي العــام صحيــح فقــد شــربت‬\n  ‫املســكر وتعاطيــت احلشــيش املخــدر وقــدت الســيارة حتــت تأثيرهمــا‬\n  ‫وأنــا تائــب إلــى اهلل تعالــى ونــادم علــى مــا صــدر منــي هكــذا أجــاب‬\n  ‫وبنــاء علــى مــا ســلف مــن الدعــوى واإلجابــة وإقــرار املدعــى عليــه جملــة‬\n  ‫وتفصيــا ومــا قــرره مــن ندمــه مــن توبتــه وخلــو ســجله مــن الســوابق‬\n  ‫وبنــاء علــى إقــراره بشــربه للمســكر وتعاطيــه احلشــيش (ملــا رواه انــس‬\n  ‫بــن مالــك رضــي اهلل عنــه أن النبــي صلــى اهلل عليــه وســلم أتــي برجــل قــد‬\n\n\n                                                                                           ‫‪76‬‬\n\f     ‫شــرب اخلمــر فجلــده بجريدتــن نحــو أربعــن قــال وفعلــه أبــو بكــر فلمــا‬\n     ‫كان عمــر استشــار النــاس فقــال عبــد الرحمــن بــن عــوف اخــف احلــدود‬\n     ‫ثمانــون فأمــر بــه عمــر متفــق عليــه وعــن علــي رضــي اهلل عنــه يف قصــة‬\n     ‫الوليــد بــن عقبــه قــال جلــد النبــي صلــى اهلل عليــه وســلم أربعــن وجلــد‬\n     ‫أبوبكــر أربعــن وجلــد عمــر ثمانــن وهــذا أحــب إلــي أخرجــه مســلم‬\n     ‫وعــن معاويــة رضــي اهلل عنــه عــن النبــي صلــى اهلل عليــه وســلم انــه قــال‬\n     ‫يف شــارب اخلمــر إذا شــرب فاجلــدوه أخرجــه احمــد واالربعــه وبنــاء عليــة‬\n     ‫فقــد ثبــت لــدي شــرب املدعــى عليــه للخمــر املســكر) ونظــر ًا لكــون‬\n     ‫العقوبــات الشــرعية واحلــدود تتداخــل وعليــه فعقوبــة املدعى عليه لشــربه‬\n     ‫للمســكر وتعاطيــه للحشــيش واحــدة وبنــاء علــى إقــراره بقيــادة الســيارة‬\n     ‫حتــت تأثيــر املســكر واحلشــيش وانطبــاق املــادة املذكــورة عليــه ونظــر ًا‬\n     ‫لكــون مــا طالــب بــه املدعــي العــام مــن املادتــن (‪ )56-41‬مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة  ال وجــه لــه فــإن العقوبــة حديــه‬\n                                                                       ‫وال زيــادة عليهــا‬\n     ‫وبنــاء علــى ذلــك كلــه فقــد قــررت مــا يلي ‪ :‬أوال‪ :‬ثبت لدي شــرب املدعى‬\n     ‫عليــه للمســكر وتعاطــي احلشــيش وقــررت عقوبتــه بجلــده ثمانــن جلــده‬\n     ‫دفعــة واحــدة حــد ًا ثانيــا‪ :‬ثبــت لــدي قيادتــه لســيارة حتــت تأثيــر املســكر‬\n     ‫واحلشــيش وأفهمتــه أن عقوبتــه علــى ذلــك عائــدة للجهــة املختصــة ‪:‬ثالثــا‪:‬‬\n     ‫رددت مــا طالــب بــه املدعــي العــام مــن تطبيق املادتــن (‪ )56-41‬من نظام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة ومبــا تقــدم حكمــت وبعرضــه‬\n     ‫علــى املدعــى عليــه قنــع بــه وبعرضــه علــى املدعــى العــام قــرر عــدم‬\n     ‫القناعــة وطلــب االســتئناف مكتفيــا مبــا قــدم عــن أالئحــة االعتراضيــة‬\n     ‫وأجبتــه لطلبــه وقــررت رفــع املعاملــة إلــى محكمــة االســتئناف باملنطقــة‬\n\n\n‫‪77‬‬\n\f‫الشــرقية حســب التعليمــات واهلل املوفــق  وصلــى اهلل علــى نبينــا محمــد‬\n                    ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1432/12/02‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم األحــد املوافــق ‪1434/4/14‬ه ـ‬\n‫افتتحــت اجللســة الرابعــة لهــذه القضيــة يف متــام الســاعة التاســعة وفيهــا‬\n‫حضــر املدعــي العــام واملدعــى عليــه  ‪ ....‬وقــد جــرت الكتابــة إلــى‬\n‫إدارة مكافحــة املخــدرات مبحافظــة االحســاء إلبــاغ املدعــى عليــه‬\n‫باحلضــور يــوم الثالثــاء املوافــق ‪1433/5/18‬هــ  فوردنــي خطــاب مديــر‬\n‫مكافحــة املخــدرات مبحافظــة االحســاء برقــم ‪22/3/3/95‬س وتاريــخ‬\n‫‪1434/1/3‬ه ـ املتضمــن مــا نصــه ( نفيدكــم بأنــه مت االتصــال بــه‬\n‫وبكفيلــه ولــم يتجــاوب ومت التعميــم عليــه ومت إيقافــه لكونــه مطلوبــا‬\n‫يف هــذه القضيــة ) أ‪ .‬ه ـ وقــد قــرر املدعــى عليــه قائــا لــم ابلــغ بــأي موعــد‬\n‫مــن اجلهــات املختصــة بالتبليــغ ولــم يبلــغ كفيلــي بذلــك وقــد توظفــت‬\n‫يف شــركة  ‪....‬بتاريــخ ‪2012/1/12‬م وقــد عقــدت الــزواج منــذ شــهر‬\n‫تقريبــا وأنــا تائــب إلــى اهلل تعالــى ونــادم علــى مــا صــدر منــي  هكــذا‬\n‫قــرر فبنــاء علــى مــا ســلف ونظــرا ملــا أبــداه املدعــى عليــه مــن التوبــة‬\n‫والنــدم وبنــاء علــى مــا قــرره أصحــاب الفضيلــة حفظهــم اهلل يف القــرار‬\n‫املشــار إليــه أعــاه وبنــاء علــى مــا جــرى عليــه العمــل مــن تطبيــق املــادة‬\n‫‪ 56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة يف مثــل هــذه‬\n‫احلالــة وأمــا املــادة ‪ 41‬مــن ذلــك النظــام فإنهــا توجــه إلــى املدعــى عليــه‬\n‫يف حالــة كونــه متهمــا بحيــازة احلشــيش ولــم تتضمــن الئحــة الدعــوى‬\n‫العامــة توجيــه االتهــام إلــى املدعــى عليــه بحيــازة املســكرات وبنــاء‬\n‫علــى ذلــك كلــه فقــد قــررت مــا يلــي ‪ - :‬أوال ‪ /‬رجعــت عمــا حكمــت‬\n‫بــه يف الفقــرة الثالثــة مــن تــرك تطبيــق املــادة ‪ 56‬مــن نظــام مكافحــة‬\n\n\n                                                                                         ‫‪78‬‬\n\f     ‫املخــدرات واملؤثــرات العقليــة وقــررت عقوبــة املدعــى عليــه مبنعــه مــن‬\n     ‫الســفر خــارج البــاد ملــدة ســنتني ‪ .‬ثانيــا ‪ /‬مــا زلــت علــى مــا حكمــت بــه‬\n     ‫يف الفقرتــن األولــى والثانيــة ومــا حكمــت بــه مــن رد الدعــوى العامــة‬\n     ‫بشــأن املــادة ‪ 41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n     ‫وبذلــك حكمــت وبعرضــه علــى املدعــى عليــه قــرر قناعتــه بــه وبعرضــه‬\n     ‫علــى املدعــي العــام قــرر عــدم القناعــة وطلــب االســتئناف مكتفيــا مبــا‬\n     ‫قــدم عــن تقــدمي الئحــة اعتراضيــة فأجبتــه لطلبــه وقــررت رد املعاملــة‬\n     ‫إلــى محكمــة االســتئناف باملنطقــة الشــرقية حســب التعليمــات لتقريــر‬\n     ‫مــا يرونــه أصحــاب الفضيلــة حفظهــم اهلل وأقفلــت اجللســة الســاعة‬\n     ‫التاســعة والنصــف وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                      ‫الــه وصحبــه وســلم حــرر يف ‪1434/4/14‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n     ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n     ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف‬\n     ‫برقــم ‪ 3418062‬وتاريــخ ‪1434/4/28‬هــ  املقيــدة لــدى احملكمــة برقــم‬\n     ‫‪ 34/1071220‬وتاريــخ ‪1434/5/1‬هــ  املرفــق بهــا القــرار الصــادر مــن‬\n     ‫فضيلــة القاضــي باحملكمــة الشــيخ   ‪ ....‬املســجل برقــم ‪32343839‬‬\n     ‫وتاريــخ ‪1432/12/2‬هــ  اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪....  /‬يف‬\n     ‫قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n     ‫ومفصــل فيــه ‪ .‬حيــث ســبق دراســة القراروصــورة ضبطــه وأوراق املعاملــة‬\n     ‫وباالطــاع علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة‬\n     ‫ضبطــه بنــاء علــى قرارنــا رقــم‪      38‬يف‪1433/1/5‬ه ـ قررنــا املصادقــة‬\n     ‫علــى احلكــم بعــد االجــراء االخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                          ‫محمــد وعلــى آلــه وصحبــه وســلم حرريف‪1434/6/3‬ه ـ‬\n‫‪79‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":73,"source_page_end":79,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5ca5177fd5f18d7d597c2c560b207a5aaebd2bd2d8d52f32b0a2cc16d52b7043","normalized_text_hash":"2f691e9df936c1fda115abf67877e838b9d5da787141c55c08e1deb4d1a13334","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p73-32343839"},{"id":"e1fdd52a-6ca8-5634-841a-d86147f299ad","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلشيش املخدر -إنكار -تعزير للتهمة -التعزير","document_number":"3454170","case_number":"33395222","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف وتعزير املدعى عليه باجللد باجلوف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/3","year":"1434","subject":"مخدرات -تعاطي احلشيش املخدر -إنكار -تعزير للتهمة -التعزير","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 3454170:‬تاريخه‪1434/3/3 :‬هـ‬\n                    ‫رقم الدعوى‪33395222 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪      331095191‬تاريخه‪1434/4/22:‬هـ‬\n\n\n\n‫مخــدرات ‪ -‬تعاطــي احلشــيش املخــدر‪ -‬إنــكار ‪ -‬تعزيــر للتهمــة ‪ -‬التعزير‬\n                                                                   ‫باجللد‬\n\n\n\n\n             ‫‪ .1‬املادة ‪ 56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n             ‫‪ .2‬املادة ‪ 41‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بتعاطيــه احلشــيش املخــدر وطلــب‬\n‫املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة الســجن واملنــع‬\n‫مــن الســفر‪ ،‬مت كشــف جــرم املدعــى عليــه حيــث كان ســجين ًا وطلــب‬\n‫حتويلــه إلــى املستشــفى العــام مدعي ـ ًا أن بيــده كســر وعنــد دخولــه‬\n‫قســم األشــعة مــد يــده إلــى جانــب الكرســي وأخــذ شــيئ ًا ثــم أبتلعــه‬\n‫وأثبــت إيجابيــة التحليــل  ملــادة احلشــيش املخــدر‪ ،‬أنكــر املدعــى عليــه‬\n‫الدعــوى‪ ،‬وبالبحــث عــن ســوابقه وجــد لــه ســوابق‪ ،‬عــدم ثبــوت اإلدانــة‬\n‫وصــدق احلكــم مــن محكمــة االســتئناف‬\n                                     ‫وتعزيــر املدعــى عليــه باجللــد ُ‬\n                                                              ‫باجلــوف ‪.‬‬\n\n\n\n                                                                                        ‫‪80‬‬\n\f     ‫اجلزائية بسكاكا‬\n                ‫ّ‬         ‫احلمد هلل وحده وبعد فلدي أنا ‪ .....‬رئيس احملكمة‬\n     ‫املســاعد وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫اجلزائيــة بســكاكا برقــم ‪ 33395222‬وتاريــخ ‪ 1433/06/11‬هــ  ‬\n       ‫املقيــدة باحملكمــة برقــم ‪ 331095191‬وتاريــخ ‪ 1433/06/10‬هــ  ففــي‬\n       ‫يــوم األحــد املوافــق ‪ 1433/12/26‬ه ـ افتتحــت اجللســة الســاعة ‪: 30‬‬\n       ‫‪ 10‬و فيهــا  قــدم املدعــي العــام ‪ ............‬دعــوى عامــة ضــد املدعــى عليــه‬\n       ‫هــذا احلاضــر ‪ ...............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n       ‫ا فيهــا إنــه بتاريــخ ‪1433/4/11‬ه ـ مت حتويــل‬     ‫‪ ...........‬أحــوال اجلــوف قائـ ً‬\n       ‫املدعى عليه من شــعبة ســجن ســكاكا إلى مستشــفى ‪  ............‬يرافقه‬\n       ‫مناوبــن مــن احلراســات حيــث كان يدعــي أن لديــه كســر يف يــده و يف‬\n       ‫قســم األشــعة قــام مبــد يــده علــى الكرســي املوجــود بجانبه و أخذ شــيء‬\n       ‫مــا وعنــد مشــاهدة املرافقــن معــه قــام علــى الفــور ببلعــه و لــم يســتطيع‬\n       ‫املناوبــن معرفــة مــا معــه و مت إعــداد محضــر بذلــك موقــع مــن قبلهــم‪.‬‬\n     ‫و قــد أثبــت التقريــر الكيميائــي الشــرعي مــن مركــز الســموم بتبــوك‬\n     ‫رقــم (‪ 1123‬م‪/‬م س ت) إيجابيــة عينــة البــول املدعــى عليــه أليــض املــادة‬\n     ‫الفعالــة للحشــيش و املــدرج باجلــدول األول فئــة (أ) يف تعميــم صاحــب‬\n     ‫الســمو امللكــي وزيــر الداخليــة رقــم ‪ 74831‬بتاريــخ ‪1431/07/09‬هــ‪.‬‬\n     ‫املدعــى عليــه ســجني لــدى شــعبة ســجن ســكاكا علــى قضيــة جنائيــة‪.‬‬\n     ‫و باســتجوابه أنكــر مــا نســب إليــه مــن اتهــام مــن ابتالعــه شــيئ ًا مــن‬\n     ‫احملظــورات أو املخــدرات‪ .‬و انتهــى التحقيــق إلــى توجيــه االتهــام ل ــ‪/‬‬\n     ‫‪ ..........‬بتعاطــي مــادة احلشــيش املخــدر املجــرم مبوجــب الفقــرة الثانيــة‬\n\n‫‪81‬‬\n\f‫مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة‬\n‫الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬و تاريــخ ‪1426/07/08‬ه ـ‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n‫فعــل مجــرم ومعاقــب عليــه نظام ـ ًا مــا يتعــن معــه إحالتــه للمحكمــة‬\n‫اجلزئيــة وفقـ ًا لنــص املادتــن (‪ )128-126‬مــن نظــام اإلجــراءات اجلزئيــة‬\n‫فإنــي أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه مبــا يلــي‪-1:‬‬\n‫الســجن وفق ـ ًا ملــا ورد يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام‬\n‫مكافحــة املخــدرات و املؤثــرات العقليــة‪ -2 .‬املنــع مــن الســفر خــارج‬\n‫اململكــة وفقـ ًا ملــا ورد بالفقــرة األولــى مــن املــادة (‪ )56‬مــن ذات النظــام‪.‬‬\n‫ا مــا ذكــره‬  ‫هــذه دعــواي‪.‬و بعــرض ذلــك علــى املدعــى عليــه أجــاب قائـ ً‬\n‫املدعــي العــام ضــدي يف دعــواه فغيــر صحيــح فلــم أقــم بتعاطــي مــادة‬\n‫احلشــيش املخــدر هكــذا أجــاب و بعــرض ذلــك علــى املدعــي العــام قــرر‬\n‫ا الصحيــح مــا ذكرتــه و بينتــي عليــه مــا يلــي‪-1 :‬مــا ورد باحملضــر‬            ‫قائـ ً‬\n‫املعــد مــن اجلهــة القابضــة لفــة رقــم (‪ )2‬صفحــة رقــم (‪ -2 .)11‬مــا جــاء‬\n‫بالتقريــر الكيميائــي لفــة رقــم (‪ .)14‬أطلــب الرجــوع إليهــا هكــذا قــرر‬\n‫و بالرجــوع إليهــا وجدتهــا مطابقــة ملــا ذكــره املدعــي العــام و مبواجهــة‬\n‫ا مــا ورد باحملضــر املعــد مــن اجلهــة القابضــة‬     ‫املدعــى عليــه بهــا قــرر قائـ ً‬\n‫صحيــح و ليــس فيــه مــا يــدل علــى مــا اتهمنــي بــه املدعــي العــام و أمــا مــا‬\n‫جــاء بالتقريــر الكيميائــي فــا علــم لــي بــه هكــذا قــرر و بعــرض ذلــك‬\n‫ا الصحيــح مــا ذكرتــه هكذا قــرر ورفعت‬              ‫علــى املدعــي العــام قــرر قائـ ً‬\n‫اجللســة للتأمــل إلــى يــوم األحــد ‪1434/03/01‬ه ـ الســاعة العاشــرة و‬\n‫النصــف ويف جلســة أخــرى يف يــوم  األحــد املوافــق‪ 1434/03/01‬ه ـ‬\n‫افتتحــت اجللســة الســاعة العاشــرة والنصــف وفيهــا حضــر املدعــي العــام‬\n\n\n                                                                                              ‫‪82‬‬\n\f     ‫واملدعــى عليــه ‪ ..........‬وبعــرض ســوابقه قــرر قائــا نعــم هــذه ســوابقي‬\n     ‫ثــاث ونلــت جزائــي عليهــا هكــذا قــرر وأقفلــت املرافعــه وبعــد ســماع‬\n     ‫الدعــوى واإلجابــة  وإلنــكار املدعــى عليــه دعــوى املدعــي العــام بقيامــه‬\n     ‫بتعاطــي مــادة احلشــيش املخــدر ولعــدم وجــود بينــة كافيــة لــدى املدعــي‬\n     ‫العــام إلدانــة املدعــى عليــه مبــا أســند إليــه مــن تعاطــي مــادة احلشــيش‬\n     ‫املخــدر وللتقريــر الكيمائــي الشــرعي رقــم (‪ )............‬الصــادر مــن‬\n     ‫مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية بتبــوك برقــم‬\n     ‫‪45/1221‬س م‪ 25/‬وتاريــخ ‪1433/4/26‬ه ـ املتضمــن إجابيــة عينــة بــول‬\n     ‫‪ ..........‬ملــادة احلشــيش‪0‬وحيث أن مــادة احلشــيش مــن املــواد املســكرة‬\n     ‫وجلميــع ماتقــدم بــه املدعــي العــام مــن إدلــة وقرائــن وبعــد اإلطــاع علــى‬\n     ‫املادتــن (‪)41.56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــه‬\n     ‫املشــار اليــه بدعــوى املدعــي العــام وخلــروج مــادة احلشــيش عــن إحاطتهمــا‬\n     ‫لعلــة اإلســكار ولوجــود ثــاث ســوابق مســجلة علــى املدعــى عليــه األولى‬\n     ‫حيــازة مخــدرات بقصــد اإلســتعمال يف ‪1431/7/22‬ه ـ والثانيــة نهــب‬\n     ‫قطــع غيــار وصــدم دوريــة أمنيــة يف ‪1431/7/2‬ه ـ والثالثــة ســرقة ســيارة‬\n     ‫يف‪1432/8/1‬ه ـ وذلــك حســب صحيفة ســوابقه املرفقــة لفه(‪  )12‬لذلك‬\n     ‫كلــه وبنــاءا عليــه لــم يثبــت لــدي إدانــة املدعــى عليــه ‪ ..........‬بتعاطي مادة‬\n     ‫احلشــيش املخــدر وتوجهــت التهمــة القويــة عليــه بذلــك وقــررت تعزيــره‬\n     ‫لقــاء ذلــك بجلــده خمســون جلــده دفعــة واحــدة وحكمــت بــرد دعــوى‬\n     ‫املدعــي العــام بشــأن تطبيــق املادتــن(‪ )41.56‬مــن نظــام مكافحــة‬\n     ‫املخــدرات واملؤثــرات العقليــة لعــدم شــموله بهمــا هــذا ماحكمــت بــه‬\n     ‫وتلــي عليهمــا فقنــع بــه املدعــى عليــه دون املدعــي العــام وطلــب متييــزه‬\n     ‫وأســتعد بتقــدمي الئحــة إعتراضيــة عليــه وقــرر فهمــه بتعليمــات التمييــز‬\n\n\n‫‪83‬‬\n\f‫وأفهمتــه بــأن عليــه احلضــور لهــذه احملكمــة يــوم اإلربعــاء ‪1434/3/4‬ه ـ‬\n‫إلســتالم نســخة احلكــم ففهــم ذلــك ورفعــت اجللســة لذلــك الــى يــوم‬\n‫اإلربعاء‪1434/3/4‬ه ـ ‪ 0‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/03/01‬ه ـ الســاعة احلاديــة‬\n                                                                           ‫عشــرة ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا  نحــن  قـض ــاة الدائ ــرة األولــى‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة اجلــوف علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بســكاكا برقــم‬\n‫‪  331095191‬وتاريــخ ‪1434/4/22‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪ .......... /‬املســجل برقــم  ‪3454170‬‬\n‫وتاريــخ ‪1434/3/3‬ه ـ اخلــاص بدعــوى  املدعــي العــام ضــد‪ ............. /‬يف‬\n‫قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه  مبــا هــو مــدون‬\n‫ومفصــل بــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‪ .‬فقــد‬\n‫قررنــا املصادقــة علــى احلكــم‪  .‬واهلل  املوفــق وصلــى اهلل علــى نبينــا‬\n                                             ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                       ‫‪84‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":80,"source_page_end":84,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"35026658cd0ef071fbc6e3f5fed7c5c851099af23ba05bd0af4da2876ef3fd49","normalized_text_hash":"0d6a9b0820b0e3adbfabbb0dd84eca4f9d96f31dfb9363e3479e8e15073c8398","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p80-3454170"},{"id":"58372c81-bac6-5509-8907-ab98d4cbde94","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلشيش املخدر -ترويج احلشيش املخدر -تستر على املروج -شهادة الشهود -إقرار املدعى عليه -التعزير بالسجن و اجللد و اإلبعاد عن الباد و مصادرة اجلوال و إلغاء الشريحة .","document_number":"34186238","case_number":"33612392","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/13","year":"1434","subject":"مخدرات -تعاطي احلشيش املخدر -ترويج احلشيش املخدر -تستر على املروج -شهادة الشهود -إقرار املدعى عليه -التعزير بالسجن و اجللد و اإلبعاد عن الباد و مصادرة اجلوال و إلغاء الشريحة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34186238 :‬تاريخه‪1434/4/13 :‬هـ‬\n                         ‫رقم الدعوى‪33612392 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪     34370699‬تاريخه‪1434/11/26 :‬هـ‬\n\n\n\n     ‫مخدرات ‪ -‬تعاطي احلشــيش املخدر ‪ -‬ترويج احلشــيش املخدر ‪ -‬تســتر‬\n     ‫علــى املــروج ‪ -‬شــهادة الشــهود ‪ -‬إقــرار املدعــى عليــه ‪ -‬التعزيــر بالســجن‬\n         ‫و اجللــد و اإلبعــاد عــن البــاد و مصــادرة اجلــوال و إلغــاء الشــريحة ‪.‬‬\n\n\n\n\n                                                ‫‪ - 1‬اإلقرار حجة شرعية ‪.‬‬\n             ‫‪ - 2‬املادة (‪ )38‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n             ‫‪ - 3‬املادة (‪ )53‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n              ‫‪ - 4‬املادة (‪ )56‬من نظام مكافحة املخدرات و املؤثرات العقلية‪.‬‬\n             ‫‪ - 5‬املادة (‪ )60‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي العــام علــى املدعــى عليــه بترويــج احلشــيش املخــدر ‪،‬‬\n     ‫وردت معلومــات لــدى مكافحــة املخــدرات عــن قيــام املدعــى عليــه‬\n     ‫بترويــج احلشــيش املخــدر ‪ ،‬وقــد مت متكــن املصــدر  مــن االتصــال بــه ‪،‬‬\n     ‫وطلــب كميــة  مــن احلشــيش املخــدر ‪ ،‬مببلــغ مائتــي ريــال ‪  ،‬فاســتعد‬\n     ‫املدعــى عليــه بذلــك ‪ ،‬ومت تزويــد املصــدر باملبلــغ املرقــم‪ ،‬ومت تفتيشــه‬\n     ‫بعــد تزويــده باملبلــغ ‪ ،‬وملــا تقابــل مــع املدعــى عليــه ‪ ،‬حتــت أنظــار الفرقــة‬\n     ‫القابضــة ‪  ،‬ســلم املصــدر املبلــغ املرقــم للمدعــى عليــه ‪ ،‬وطلــب املدعــى‬\n\n‫‪85‬‬\n\f‫عليــه مــن املصــدر االنصــراف مــن املوقــع ‪ ،‬وأبلغــه بأنــه عنــد توفــر قطعــة‬\n‫احلشــيش ســوف يعــاود االتصــال عليــه ‪ ،‬وبعــد عــدة أيــام اتصــل املدعــى‬\n‫عليــه علــى املصــدر ‪ ،‬يفيــده بتوفــر احلشــيش ‪ ،‬وكانــت املكاملــة حتــت‬\n‫ســماع الفرقــة القابضــة ‪ ،‬فتــم تفتيــش املصــدر ‪ ،‬ومت االنتقــال إلــى‬\n‫املــكان املتفــق عليــه ‪ ،‬وتقابــل املصــدر مــع املدعــى عليــه ‪ ،‬وقــام املدعــى‬\n‫عليــه ‪ ،‬بتســليم املصــدر قطعــة بنيــة اللــون ‪ ،‬يشــتبه أن تكــون مــن مــادة‬\n‫احلشــيش املخــدر ‪ ،‬بلــغ وزنهــا (‪ )4050‬أربعــة جرامــات وخمســن باملائــة‬\n‫مــن اجلــرام ‪ ،‬وكانــت العمليــة حتــت أنظــار الفرقــة القابضــة‪ ،‬و طلــب‬\n‫املدعــي العــام تعزيــر املدعــى عليــه بالســجن واجللــد والغرامــة واإلبعــاد‬\n‫عــن البــاد ومصــادرة الســيارة ومصــادرة اجلوالــن وإلغــاء شــريحتيهما‬\n‫ورد املبلــغ احلكومــي‪ ،‬وتعزيــره لقــاء تســتره علــى املــروج‪ ،‬أنكر املدعي‬\n‫عليــه مــا جــاء بدعــوى املدعــي العــام بطلــب البينــة مــن املدعــي العــام علــى‬\n‫دعــواه أحضــر شــاهديه و قــد شــهدا بصحــة الواقعــة و بعــرض شــهادتهما‬\n‫علــى املدعــى عليــه أقــر بصحــة مــا جــاء يف الشــهادة‪ ،‬صــدر احلكــم‬\n‫بتعزيــر املدعــى عليــه بالســجن و اجللــد و الغرامــة و مصــادرة اجلوالــن‬\n‫و إلزامــه بإعــادة املبلــغ احلكومــي و إلغــاء الشــريحة و إبعــاده خــارج‬\n‫اململكــة وال يســمح لــه بالعــودة إليهــا إال فيمــا تســمح بــه تعليمــات احلــج‬\n‫و العمــرة‪ ،‬قنــع املدعــي عليــه باحلكــم ‪ ،‬وقــرر املدعــي العــام اعتراضــه‬\n‫علــى احلكــم بــدون الئحــة‪ ،‬مت صــدق احلكــم مــن محكمــة االســتئناف‬\n                                                                                      ‫‪.‬‬\n\n\n\n\n                                                                                          ‫‪86‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪  ).....‬القاضــي يف احملكمــة اجلزائيــة‬\n     ‫مبكــة املكرمــة   وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n       ‫احملكمــة اجلزائيــة مبكــة املكرمــة برقم (‪ ).....‬وتاريــخ ‪1433/10/21‬‬\n     ‫هــ  املقيــدة باحملكمــة برقــم (‪ ).....‬وتاريــخ ‪ 1433/10/21‬هــ  ففــي يــوم  ‬\n     ‫الســبت املوافــق‪ 1434/02/23‬ه ـ افتتحــت اجللســة الســاعة ‪  11 : 45‬‬\n       ‫وفيهــا حضــر  املدعــي العــام وداعــى علــى احلاضــر معــه (‪ ).....‬اندونيســي‬\n       ‫ا انــه بنــاء علــى توفــر معلومــات لــدى‬\n                                                 ‫اجلنســية  اقامــة رقــم (‪ ).....‬قائ ـ ً‬\n       ‫مكافحــة املخــدرات عــن قيــام املدعــى عليــه بترويــج احلشــيش املخــدر‬\n       ‫بحــي (‪ ).....‬جــرى بتاريــخ ‪1433/9/25‬ه ـ متكــن املصــدر مــن التصــال‬\n       ‫علــى جــوال املدعــى عليــه رقــم (‪ ).....‬وطلــب منــه كميــة مــن احلشــيش‬\n       ‫املخــدر مببلــغ (‪ )200‬مائتــي  ريــال فاســتعد املدعــى عليــه بذلــك وطلــب‬\n       ‫مــن املصــدر احلضــور لــه بحــي (‪ ).....‬امــام مركــز الدفــاع املدنــي وجــرى‬\n       ‫تفتيــش املصــدر بعــد تزويــده باملبلــغ املرقــم وقــدرة (‪ )200‬مائتــا ريــال‬\n     ‫فتقابــل املصــدر مــع املدعــى عليــه حتــت أنظــار الفرقــة وقــام املصــدر‬\n     ‫بتســليم املدعــى عليــه املبلــغ املرقــم وطلــب املدعــى عليــه مــن املصــدر‬\n     ‫االنصــراف مــن املوقــع وابلغــه بأنــه عنــد توفــر قطعــة احلشــيش املخــدر‬\n     ‫ســوف يعــاود االتصــال بــه الســتالمها  ويف متــام الســاعة الثانيــة مــن صباح‬\n     ‫يــوم الثالثــاء املوفــق ‪1433/9/26‬ه ـ عــاود املدعــى عليــه االتصــال علــى‬\n     ‫املصــدر مــن جــوال رقــم (‪ ).....‬واخبــر املصــدر مبكاملــة مســموعة بــأن‬\n     ‫الكميــة املطلوبــة ســوف تكــون متوفــرة يف أيــام العيــد ويف يــوم الثالثــاء‬\n     ‫املوافــق ‪1433/10/3‬ه ـ ورد إتصــال مــن الرقــم (‪ ).....‬أفــاد فيــه املدعــى‬\n\n‫‪87‬‬\n\f  ‫عليــة بــأن كميــة احلشــيش املطلوبــة متوفــرة لديــة وطلــب مقابلــة املصــدر‬\n  ‫بحــي (‪ ).....‬وكانــت املكاملــة حتــت ســماع الفرقــة فتــم تفتيــش املصــدر‬\n  ‫وجــرى دفعــة حتــت انظــار الفرقــة فحضــر املدعــى عليــة علــى ســيارة مــن‬\n  ‫نــوع (‪ ).....‬حتمــل اللوحــة ســعودية رقــم (‪ ).....‬تعــود ملكيتهــا للمواطــن‬\n  ‫(‪ ).....‬ونــزل املدعــى عليــه مــن الســيارة التــي يقودهــا وتقابــل مــع املصــدر‬\n  ‫وقــام بتســليم املصــدر قطعــة بنيــة اللــون يشــتبة أن تكــون مــن مــادة‬\n  ‫احلشــيش املخــدر بلــغ وزنهــا (‪4050‬جــم) اربعــة جرامــات وخمســن باملائــة‬\n  ‫مــن اجلــرام وكانــت العمليــة حتــت االنظــار الفرقــة املنتشــرة باملوقــع‬\n  ‫واعطيــت االشــارة فتــم القبــض علــى املدعــى عليــة وبتفتيشــة شــخصي ًا‬\n  ‫لــم يعثــر معــه علــى اي شــي مــن املمنوعــات وعثــر معــه علــى جوالــن مــن‬\n  ‫نــوع (‪ ).....‬بشــريحتني (‪ ).....‬و(‪ ).....‬يحمــل  االول الرقــم املصنعــي (‪).....‬‬\n  ‫ولثانــي يحمــل الرقــم املصنعــي (‪ ).....‬واتضــح أنهمــا الرقمــان اللــذان‬\n  ‫اســتخدما يف عمليــة التنســيق للترويــج ومبناقشــته مــن قبــل الفرقــة‬\n  ‫القابضــة أقــر أمــام الفرقــة بواقعــة الضبــط  وباســتجواب املدعــى عليــه‬\n  ‫(‪ ).....‬أقــر بانــه قبــض عليــة مــن قبــل مكافحــة املخــدرات أثنــاء قيامــة‬\n  ‫ببيــع  قطعــة مــن احلشــيش املخــدر وانــه حصــل عليــة مــن شــخص اليعرفــه‬\n  ‫وقــد انتهــى التحقيــق الــى توجيــه االتهــام للمدعــى عليــه وهــذا فعل محرم‬\n  ‫شــرعا ومجــرم نظامــا وفقــا للفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام‬\n  ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n  ‫م‪ 39/‬وتاريــخ ‪1426/7/8‬ه ـ وتســترة علــى املــروج وحيــث أن ماقــام بــه‬\n  ‫املدعــى عليــه فعــل محــرم شــرع ًا ومجــرم ومعاقــب عليــة نظام ـ ًا وفقــا‬\n‫للمــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة  ‬\n  ‫لــذا اطلــب إثبــات مــا أســند إليــه واحلكــم عليــة بالعقوبــات األصليــة‬\n\n\n                                                                                         ‫‪88‬‬\n\f     ‫والتكميليــة التاليــة ‪ -1‬بالســجن واجللــد والغرمــة اســتناد للفقــرة (‪)1‬‬\n     ‫مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n     ‫املشــارإليه ‪ -2‬إبعــاد عــن البــاد بعــد االنتهــاء مــن تنفيــذ عقوبتــه وفقــا‬\n     ‫للفقــرة (‪ )2‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة املشــار إليــة ‪ -3‬الزامــه باعــادة املبلــغ احلكومــي املرقــم وقــدرة‬\n     ‫مائتــا (‪ )200‬الدارة مكافحــة املخــدرات بالعاصمــة املقدســة اســتناد‬\n     ‫لتعميــم صاحــب الســمو امللكــي وزيــر الداخليــة رقــم ‪65980/4/5/1‬‬\n     ‫وتاريــخ ‪1428/12/23_22‬ه ـ ‪ -4‬مصــادرة اجلوالــن ذوي الرقمــن‬\n     ‫املصنعــن (‪ ).....‬ورقــم(‪ ).....‬اســتناد للفقــرة (‪ )1‬مــن املــادة (‪ )53‬مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة  وإلغــاء شــريحتيهما اســتناد‬\n     ‫لبرقيــة ســمو وزيرالداخليــة رقــم ‪ 9798/5/1‬يف ‪1428/2/10_9‬ه ـ‬\n     ‫والنــص يف القــرار الشــرعي علــى إدخــال قيمتهــا مبوسســة النقــد‬\n     ‫العربــي الســعودي حلســاب املديريــة العامــة املكافحــة املخــدرات اســتناد‬\n     ‫لبرقيــة صاحــب الســمو امللكــي ولــي العهــد نائــب رئيــس مجلــس الــوزراء‬\n     ‫وزيــر الداخليــة رقــم ‪ 40656‬وتاريــخ ‪1430/6/8‬ه ـ ‪ -5‬تعزيــر لقــاء‬\n     ‫تســترة علــى املــروج اســتناد لتعميــم معالــي رئيــس الهيئــة رقــم ‪15596‬‬\n     ‫يف وزيرالداخليــة رقــم ‪ 9798/5/1‬يف ‪1428/2/10_9‬ه ـ والنــص يف‬\n     ‫القــرار الشــرعي علــى إدخــال قيمتهــا مبوسســة النقــد العربــي الســعودي‬\n     ‫حلســاب املديريــة العامــة املكافحــة املخــدرات اســتناد لبرقيــة صاحــب‬\n     ‫الســمو امللكــي ولــي العهــد نائــب رئيــس مجلــس الــوزراء وزيــر الداخليــة‬\n     ‫رقــم ‪ 40656‬وتاريــخ ‪1430/6/8‬ه ـ ‪ -5‬تعزيــر لقــاء تســترة علــى املــروج‬\n     ‫اســتناد لتعميــم معالــي رئيــس الهيئــة رقــم ‪ 15596‬يف‪1433/5/4‬ه ـ‬\n     ‫وبســؤال املدعــى عليــه عــن دعــوى املدعــى العــام أجــاب قائــا ماذكــره‬\n\n\n‫‪89‬‬\n\f‫املدعــى العــام يف دعــواه أعــاه غيــر صحيــح فأنــا لــم ابيــع وإمنــا أعطيــت‬\n‫املصــدر قطعــة مــن احلشــيش املخدرأمانــه عنــدي وأنــا الأعرفهــا فأنــا‬\n‫ال أشــرب الدخــان ومــن ثــم ســلمته مــا أعطانــي  إيــاه ومت القبــض علــي‬\n‫ا أطلــب‬  ‫هكــذا أجــاب وبســؤال املدعــى العــام عــن بينتــه أجــاب قائ ـ ً‬\n‫إمهالــي إلحضــار بينتــي وعليــه رفعــت اجللســة إلحضــار املدعــى العــام‬\n‫بينتــه ويف هــذا اليــوم األحــد املوافــق ‪1434/3/22‬ه ـ افتتحــت اجللســة‬\n‫ال مــن‬‫يف متــام الســاعة التاســعة وفيهــا أحضــر املدعــي العــام بينتــه ك ً‬\n‫‪ ).....( /‬ســعودي اجلنســية بالســجل املدنــي رقــم (‪ ).....‬و (‪ ).....‬ســعودي‬\n‫اجلنســية بالســجل املدنــي رقــم (‪ ).....‬وباستشــهادهما شــهد كل واحــد‬\n‫ا توفــر لدينــا معلومــات عــن قيــام املدعــى عليــه بترويــج‬     ‫منهمــا قائ ـ ً‬\n‫احلشــيش بحــي (‪ ).....‬جــرى متكــن املصــدر مــن االتصــال علــى جــوال‬\n‫املدعــى عليــه وطلــب منــه كميــة مــن احلشــيش املخــدر مببلــغ مائتــن‬\n‫ريــال فاســتعد املدعــى عليــه وطلــب مــن املصــدر احلضــور إليــه بحــي (‪).....‬‬\n‫أمــام مركــز الدفــاع املدنــي وجــرى تفتيــش املصــدر بعــد تزويــده باملبلــغ‬\n‫املرقــم ‪200‬مائنــان ريــال فقابــل املصــدر مــع املدعــى عليــه وقــام املصــدر‬\n‫بتســليمة املبلــغ املرقــم وطلــب املدعــى عليــه مــن املصــدر االنصــراف مــن‬\n‫املوقــع وأبلغــه بأنــه متــى ماتوفــر الكميــه ســيتصل عليــه عــاود املدعــى‬\n‫عليــه االتصــال علــى املصــدر وأخبــر املصــدر مبكاملــة مســموعة بــأن‬\n‫الكميــة املطلوبــة ســتكون متوفــرة يف أيــام العيــد ورد اتصــال مــن‬\n‫املدعــى عليــه أفــاد فيــه بــأن الكميــة مــن احلشــيش متوفــرة وطلــب‬\n‫املدعــى عليــه مــن املصــدر مقابلتــه بحــي (‪ ).....‬وكانــت املكاملــة حتــت‬\n‫ســماع الفرقــة مت تفتيــش املصــدر وجــرى دفعــه حتــت أنظــار الفرقــة‬\n‫حضــر املدعــى عليــه علىســيارة مــن نــوع (‪ ).....‬ونــزل املدعــى عليــه مــن‬\n\n\n                                                                                      ‫‪90‬‬\n\f     ‫الســيارة وتقابــل مــع املصــدر وقــام بتســليم املصــدر قطعــة بنيــة اللــون ولــم‬\n     ‫نشــاهد عمليــة االســتالم وال التســليم ثــم أعطيــت اإلشــارة فتــم القبــض‬\n     ‫عليــه وبتفتيشــه لــم يعثــر علــى أي شــي مــن املمنوعــات هــذه شــهادتنا‬\n     ‫ا ماجــاء يف شــهاد‬      ‫وبعــرض الشــهادة علــى املدعــى عليــه أجــاب قائ ـ ً‬\n     ‫الشــاهدين صحيحــة وأنــا ســلمت املصــدر وأنــا نــادم علــى مابــدر منــي‬\n     ‫وتائــب هــذه إجابتــي فبنــاء علــى ماتقــدم مــن الدعــوى واإلجابــة ومبــا أن‬\n     ‫املدعــى عليــه أقــر بدعــوى املدعــى العــام ومبــا أن اإلقــرار حجــة شــرعية‬\n     ‫علــى املقــر وبنــاء علــى املــادة ‪ 38،53،56،60‬لــذا وجلميــع ماتقــدم فقــد‬\n     ‫تقــرر لــي مــا يلــي أو ًال ثبــت لــدي إدانــة املدعــى عليــه مبــا أســند إليــه مــن‬\n     ‫ترويــج أربعــة جرامــات وخمســون باملائــة مــن احلشــيش املخــدر بقصــد‬\n     ‫التعاطــي ثاني ـ ًا قــررت ســجنه مــدة ســنة محســوب ًا منهــا مــدة إيقافــه يف‬\n     ‫هــذه القضيــة وجلــدة ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات كل‬\n     ‫دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى عشــرة أيــام وتغرميــه بألــف‬\n     ‫ريــال خلزينــة الدولــة تصــرف للمصالــح العامــة ثالث ـ ًا إبعــاد املدعــى عليــه‬\n     ‫خــارج اململكــة بعــد انتهــاء محكوميتــه واليســمح لــه بالعــودة إليهــا‬\n     ‫إالماتســمح بــه تعليمــات احلــج والعمــرة رابع ـ ًا مصــادرة اجلوالــن ذو‬\n     ‫الرقــم (‪ ).....‬و (‪ ).....‬وإلغــاء شــريحتهما وإيــداع مبلغهمــا مبوسســة النقــد‬\n     ‫العربــي الســعودي لصالــح املديريــة العامــة ملكافحــة املخــدرات كمــا‬\n     ‫قــررت إلزامــه بإعــادة املبلــغ املرقــم ووقــدره مائتــي ريــال وملــا ســبق كلــه‬\n     ‫حكمــت وبعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة باحلكــم‬\n     ‫كمــا قــرر املدعــى العــام االعتــراض ‪.‬وصلــى اهلل وســلم علــى ســيدنا‬\n                                                 ‫محمــد حــرر بتاريــخ ‪1434/3/22‬ه ـ‬\n     ‫احلمــدهلل وحــده وبعــد ويف هــذا اليــوم االربعــاء املوافــق ‪1434/9/16‬ه ـ‬\n\n\n‫‪91‬‬\n\f‫افتتحــت اجللســة وقــد عــادت املعاملــة مــن محكمــة االســتئناف مبكــة‬\n‫املكرمــة برقــم (‪ ).....‬يف ‪1434/7/18‬ه ـ وبرفقهــا قــرار الدائرة اجلزائية‬\n‫اخلامســة رقــم (‪ ).....‬يف ‪1434/7/10‬ه ـ واملذيــل مــن اصحــاب الفضيلــة‬\n‫بتوقيعاتهــم كال مــن رئيــس اســتئناف (‪ ).....‬و قاضــي اســتئناف (‪).....‬‬\n‫وقاضــي اســتئناف (‪ ).....‬ونــص احلاجــة منــه وبدارســة القــرار وصــورة‬\n‫ضبطــه تقــرر إعادتهــا لفضيلــة حاكمهــا ملالحظــة أن القــرار فيــه‬\n‫ســقط مــن الســطر الســابع مــن أســفل الصفحــة الثانيــة عنــد إحضــار‬\n‫املدعــي العــام لبينتــه كمــا يالحــظ أن هنــاك أغــاط مطبعيــة وإمالئيــة‬\n‫مؤشــر عليهــا بالقلــم الرصــاص فيالحــظ ذلــك وعليــه فأجيــب أصحــاب‬\n‫الفضيلــة بأنــه جــرى إكمــال الــازم حيــال مــا ذكــر وبــاهلل التوفيــق‬\n   ‫وصلــى اهلل وســلم علــى ســيدنا محمــد حــرر بتاريــخ ‪1434/9/16‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد  ويف يــوم االحــد املوافق ‪1434/12/22‬هـ افتتحت‬\n‫اجللســة الســاعة  التاســعة صباحــا وفيهــا عــادت املعاملــة مــن محكمــة‬\n                               ‫االســتئناف مبكــة املكرمــة برقــم ‪331847300‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ -:‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة املســاعد برقــم  (‪ )....‬وتاريخ‬\n‫‪1434/11/12‬ه ـ املرفــق بهــا القــرار الصــادر م ــن فضيلة الشــيخ ‪).....( /‬‬\n‫القاضــي باحملكمــة اجلزائيــة مبكــة املكرمــة برقــم (‪ ).....‬وتـ ـ ـ ـ ــاريخ‬\n‫‪1434/4/13‬هـ الـمتضم ــن دعوى املدعي العام ضد ‪ ).....( /‬اندونيســي‬\n‫اجلنســية املتهــم بترويــج احلشــيش املخــدر ‪ ،‬احملكوم فيــه مبا دون بباطن‬\n‫القــرار ‪ ،‬وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة قررنــا‬\n\n\n                                                                                  ‫‪92‬‬\n\f     ‫املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل‬\n                                ‫علــى نبينــا محمــد وعلــى آل ـ ـ ــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪93‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":85,"source_page_end":93,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c071b92baba00e3efdd2f1d57e16a52a1e947a5a6ccbd253097ef87db4768ea0","normalized_text_hash":"129f9f9539227c096fdb2b2b06f72e322b21d1b53c927f9f12957931cadcc9ee","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p85-34186238"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"390a20c0-7b08-532a-b69d-ac911675b3a6","document_type":"judgment","category":"judicial","subcategory":"general","title":"استعمال املخدرات -حيازة سيجارة حشيش -حيازة قارورة خمر تعاطي احلشيش -التستر على مصدر اخلمر واحلشيش -قيادة السيارة حتت تأثير تعاطي احلشيش املخدر -إقامة حد املسكر - التعزير بالسجن واجللد واإلبعاد.","document_number":"3432148","case_number":"3445259","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/06","year":"1434","subject":"استعمال املخدرات -حيازة سيجارة حشيش -حيازة قارورة خمر تعاطي احلشيش -التستر على مصدر اخلمر واحلشيش -قيادة السيارة حتت تأثير تعاطي احلشيش املخدر -إقامة حد املسكر - التعزير بالسجن واجللد واإلبعاد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 3432148 :‬تاريخه ‪1434/02/06:‬هـ‬\n                      ‫رقم الدعوى‪3445259 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪    34173165‬تاريخه‪1434/3/28:‬هـ‬\n\n\n\n‫اســتعمال املخــدرات ‪ -‬حيــازة ســيجارة حشــيش ‪ -‬حيــازة قــارورة خمــر‬\n‫ـ تعاطــي احلشــيش ‪ -‬التســتر علــى مصــدر اخلمــر واحلشــيش ‪ -‬قيــادة‬\n‫الســيارة حتــت تأثيــر تعاطــي احلشــيش املخــدر ‪ -‬إقامــة حــد املســكر ‪-‬‬\n                                    ‫التعزيــر بالســجن واجللــد واإلبعــاد‪.‬‬\n\n\n\n\n            ‫‪-1‬املادة (‪ )41‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n            ‫‪-2‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n            ‫‪-3‬املادة (‪ )60‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n\n\n\n\n‫توجيــه االتهــام للمدعــى عليهمــا‪ :‬األول بتعاطــي احلشــيش وحيــازة قــارورة‬\n‫مســكر بقصــد الشــرب وتســتره علــى مصــدر املســكر‪ ،‬والثانــي‬\n‫حيــازة ســيجارة حشــيش بقصــد التعاطــي‪ ،‬وتعاطيــه احلشــيش وتســتره‬\n‫علــى مصــدر احلشــيش‪ ،‬وقيادتــه للســيارة حتــت تأثيــر تعاطــي احلشــيش‬\n‫املخــدر‪ ،‬حيــث قبــض عليهمــا مــن قبــل إحــدى فــرق دوريــات األمــن يف‬\n‫إحــدى نقــاط التفتيــش يف الطريــق العــام ‪ ،‬حيــث مت اســتيقاف الســيارة‬\n‫التــي كان يقودهــا األول و يرافقــه الثانــي وبتفتيــش الســيارة وجــد حتــت‬\n‫مقعــد الســائق ســيجارة مخلوطــه باحلشــيش‪ ،‬كمــا عثــر علــى قــارورة‬\n\n                                                                                 ‫‪52‬‬\n\f       ‫بهــا ســائل مســكر‪ ،‬باســتجواب املدعــى عليــه األول اعتــرف بتعاطــي‬\n       ‫احلشــيش  وحيــازة قــارورة املســكر بقصــد الشــرب ولــم يــدل مبعلومــات‬\n     ‫عــن مصــدر مــا ضبــط‪ ،‬باســتجواب الثانــي اعتــرف بتعاطــي احلشــيش‪  ،‬‬\n       ‫وحيــازة ســيجارة احلشــيش بقصــد التعاطــي ‪ ،‬ولــم يــدل مبعلومــات عــن‬\n       ‫مصــدر ماضبــط‪ ،‬طلــب املدعــي العــام إثبــات إدانتهمــا مبــا نســب إليهــم‬\n       ‫وإجــراء املقتضــى الشــرعي لقــاء تعاطيهمــا احلشــيش املخــدر‪ ،‬احلكــم‬\n       ‫بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام مكافحــة‬\n       ‫املخــدرات بحــق الثانــي لقــاء مــا أســند إليــه‪ ،‬إبعادهمــا خــارج اململكــة‬\n       ‫بعــد انتهــاء تنفيــذ عقوبــة ســجنهما‪ ،‬تعزيــر األول لقــاء حيــازة املســكر‬\n       ‫بقصــد الشــرب‪ ،‬تعزيرهمــا لقــاء تســترهما علــى مصــدر ماضبــط‪ ،‬أقــر‬\n       ‫املدعــى عليهمــا مبــا نســب إليهمــا‪ ،‬صــدر احلكــم بإثبــات مــا أســند‬\n       ‫إليهــم و احلكــم عليهمــا بإقامــة حــد املســكر‪ ،‬التعزيــر بالســجن واجللــد‬\n       ‫واإلبعــاد‪ ،‬إثبــات قيــادة األول للســيارة حتــت تأثيــر احلشــيش املخــدر‬\n       ‫والعقوبــة يف ذلــك عائــدة للجهــة املختصــة‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                                           ‫االســتئناف ‪.‬‬\n\n\n\n\n‫‪53‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ............‬القاضــي يف احملكمــة‬\n‫اجلزائيــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة بالريــاض برقــم  وتاريــخ ‪ 1434/01/26‬هــ  املقيــدة‬\n‫باحملكمــة برقــم   وتاريــخ ‪ 1434/01/26‬هــ   ففــي يــوم   األربعــاء‬\n‫املوافــق‪ 1434/02/06‬ه ـ افتتحــت اجللســة الســاعة ‪  11 : 15‬وفيهــا قــدم‬\n                                         ‫املدعــي العــام دعــواه علــى كل مــن‪:‬‬\n‫‪ .......... -1‬البالــغ مــن العمــر( ‪ ) 24‬عام ـ ًا ‪ ،‬ســوداني اجلنســية مبوجــب‬\n‫بطاقــة رخصــة إقامــة  رقــم (‪  )..........‬أعــزب ‪ ،‬جامعــي ‪ ،‬مرافــق لوالــده‪،‬‬\n‫يقيــم  يف مدينــة الريــاض ‪ ،‬أوقــف بتاريــخ ‪1433/12/23‬ه ـ ‪ ،‬وأحيــل‬\n‫إلــى شــعبة ســجن امللــز مبوجــب أمــر اإلحالــة ومتديــد التوقيــف رقــم (ه ـ‬\n‫ر‪ )610/5/1‬وتاريــخ  ‪1434/1/3‬ه ـ ‪ ،‬اســتناد ًا لبرقيــة ســمو ولــي العهــد‬\n‫النائــب األول لرئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم (‪)..........‬‬\n                                 ‫وتاريــخ ‪1433/12/20‬ه ـ ‪ ،‬لكونــه أجنبــي‪.‬‬\n  ‫‪ .......... ، .2‬البالــغ مــن العمــر( ‪ ) 22‬عام ـ ًا ‪ ،‬ســوداني اجلنســية مبوجــب‬\n  ‫بطاقــة رخصــة إقامــة رقــم (‪  )..........‬أعــزب ‪ ،‬طالــب ‪ ،‬يقيــم  يف مدينــة‬\n  ‫الريــاض‪ ،‬أوقــف بتاريــخ ‪1433/12/23‬ه ـ ‪ ،‬وأحيــل إلــى شــعبة ســجن‬\n‫امللــز مبوجــب أمــر اإلحالــة ومتديــد التوقيــف رقم (ه ـ ر‪ )609/5/1‬وتاريخ  ‬\n  ‫‪1434/1/3‬ه ـ ‪ ،‬اســتناد ًا لبرقيــة ســمو ولــي العهــد النائــب األول لرئيــس‬\n  ‫مجلــس الــوزراء وزيــر الداخليــة رقــم (‪ )79425‬وتاريــخ ‪1433/12/20‬ه ـ‬\n                                                                ‫‪ ،‬لكونــه أجنبــي‪.‬‬\n  ‫حيــث إنــه بتاريــخ ‪1433/12/23‬ه ـ ‪ ،‬قبــض علــى املذكوريــن مــن قبــل‬\n\n                                                                                      ‫‪54‬‬\n\f     ‫إحــدى فــرق دوريــات األمــن يف أحــد نقــاط التفتيــش يف طريــق ‪ ....‬مــع ‪....‬‬\n     ‫حيــث مت اســتيقاف ســيارة مــن نــوع ‪ .....‬وحتمــل اللوحــة رقــم (‪)....‬بقيــادة‬\n     ‫األول ويرافقــه الثانــي ‪ ،‬وبتفتيــش الســيارة وجــد حتــت مقعــد الســائق‬\n     ‫ســيجارة تــزن (‪ )1.2‬جرام ـ ًا واحــد ًا وعشــري اجلــرام يشــتبه أن يكــون‬\n     ‫تبغهــا مخلــوط باحلشــيش املخــدر وعثــر أيض ـ ًا علــى قــارورة بهــا ســائل‬\n     ‫يشــتبه أن يكــون مــن املســكر ســعة (‪)0.6‬لتــر بهــا أكثــر مــن النصــف ‪.‬‬\n     ‫    وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز‬\n     ‫مراقبــة الســموم و الكيميــاء الطبيــة الشــرعية  املرفــق رقــم (‪/11773‬‬\n     ‫س) لعام‪1433‬ه ـ ايجابيــة مســتخلص التبــغ يف الســيجارة املضبوطــة‬\n     ‫للحشــيش وهــو مــن املــواد املخــدرة املدرجــة باجلــدول رقــم (‪ )1‬فئــة ( أ )‬\n     ‫امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬وايجابيــة عينــة‬\n               ‫الســائل املضبــوط يف القــارورة ملــادة الكحــول بنســبة  (‪.)%42‬‬\n     ‫    وبســماع أقــوال األول األوليــة واســتجوابه اعتــرف بتعاطــي احلشــيش‬\n     ‫املخــدر يف نفــس يــوم القبــض عليــه ‪ ،‬وحيــازة قــارورة املســكر بقصــد‬\n                           ‫الشــرب ‪ ،‬ولــم يــدل مبعلومــات عــن مصــدر ماضبــط‪.‬‬\n     ‫وبســماع أقــوال الثانــي األوليــة اعتــرف بتعاطــي احلشــيش املخــدر ‪،‬‬\n     ‫وباســتجوابه اعتــرف بحيــازة ماضبــط مــن ســيجارة حشــيش مخــدر‬\n     ‫لــه بقصــد التعاطــي ‪ ،‬واعتــرف بتعاطــي احلشــيش املخــدر ‪ ،‬ولــم يــدل‬\n                                                 ‫مبعلومــات عــن مصــدر ماضبــط‪.‬‬\n     ‫وقــد أســفرت إجــراءات التحقيــق عــن اتهــام األول‪ ..... /‬بتعاطي احلشــيش‬\n     ‫املخــدر ‪ ،‬وللثانــي‪ ،..... /‬بحيــازة ســيجارة مخلوط ـ ًا تبغهــا باحلشــيش‬\n     ‫املخــدر تــزن (‪ )1.2‬جرام ـ ًا واحــد ًا وعشــري اجلــرام بقصــد التعاطــي‬\n     ‫وتعاطيــه احلشــيش املخــدر‪ ،‬املجــرم مبوجــب املــادة (الثالثــة) مــن نظــام‬\n\n\n‫‪55‬‬\n\f  ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n  ‫( م ‪ )39 /‬وتاريــخ ‪1426/7/8‬ه ـ ‪ ،‬وحيــازة األول قــارورة املســكر ســعة‬\n  ‫(‪ )0.6‬لتــر بهــا أكثــر مــن النصــف بقصــد الشــرب ‪ ،‬وتســتر األول علــى‬\n  ‫مصــدر مــا ضبــط مــن مســكر‪  ،‬وتســتر الثانــي علــى مصــدر مــا ضبــط‬\n  ‫مــن حشــيش مخــدر املعاقــب علــى ذلــك شــرع ًا ‪ ،‬وقيادتــه للســيارة حتــت‬\n  ‫تأثيــر تعاطــي احلشــيش املخــدر املجــرم مبوجــب املــادة (‪ )68‬مــن نظــام‬\n‫املــرور الصــادر باملرســوم امللكــي رقــم (م‪ )85/‬وتاريــخ ‪1428/10/26‬هـ  ‬\n                                                   ‫وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n  ‫ا علــى‬ ‫‪ .1‬مــا تضمنــه اعترافهمــا حتقيق ـ ًا املنــوه عنــه املــدون تفصي ـ ً‬\n  ‫الصفحــات رقــم (‪ 1‬ـ ـ ‪ )4‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪.)16‬‬\n  ‫‪ .2‬مــا تضمنــه اعترافهمــا مبحضــر ســماع أقوالــه األوليــة املنــوه عنهمــا‬\n                                     ‫املــدون اللفــات مــن رقــم (‪ )3‬إلــى رقــم (‪.)6‬‬\n                 ‫‪ .3‬ما تضمنه محضر القبض املنوه عنه املرفق لفه رقم (‪.)1‬‬\n  ‫‪ .4‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــة‬\n                                                                             ‫رقــم(‪.)15‬‬\n  ‫وببحــث ســوابقهما عثــر لــأول علــى ســابقة مضاربــة ‪ ،‬ولــم يعثــر للثانــي‬\n  ‫علــى ســوابق مســجلة حتــى تاريخــه‪ .‬وحيــث إن مــا أقدم عليــه املذكوران‬\n  ‫فعــل محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا لــذا اطلــب إثبــات إدانتهمــا مبا‬\n                                                    ‫اســند إليهمــا واحلكــم باآلتــي ‪:‬‬\n  ‫‪ .1‬بإجــراء املقتضــى الشــرعي  بحقهمــا لقــاء تعاطيهمــا احلشــيش املخــدر‬\n  ‫‪ .2‬بالعقوبــة الــواردة يف الفقــرة (األولــى)   مــن املــادة (‪ )41‬مــن نظــام‬\n  ‫مكافحــة املخــدرات واملؤثــرات العقليــة املشــار إليــه بحــق الثانــي لقــاء‬\n                                                                       ‫مــا أســند إليــه‪.‬‬\n\n\n                                                                                             ‫‪56‬‬\n\f     ‫‪ .3‬إبعــاد األول والثانــي إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبــة‬\n     ‫ســجنهما وعــدم الســماح لهمــا بالعــودة إليهــا مــرة أخــرى وفق ـ ًا للفقــرة‬\n                              ‫(الثانيــة) مــن املــادة (‪ )56‬مــن النظــام املشــار إليــه ‪.‬‬\n          ‫‪ .4‬بعقوبة تعزيرية بحق األول لقاء حيازته املسكر بقصد الشرب ‪.‬‬\n             ‫‪ .5‬بعقوبة تعزيرية بحقهما لقاء تسترهما على مصدر ما ضبط ‪.‬‬\n     ‫‪ .6‬النظــر فيمــا يتعلــق بقيــادة األول الســيارة حتــت تأثيــر تعاطي احلشــيش‬\n     ‫املخــدر وفــق البنــد (ثاني ـاً) مــن املرســوم امللكــي رقــم(م‪ )85/‬وتاريــخ‬\n     ‫‪1428/10/26‬هــ‪ .‬وبعــرض دعــوى املدعــي العــام علــى املدعــى عليهمــا‬\n     ‫احلاضريــن يف هــذه اجللســة أجــاب كل واحــد منهمــا قائــا‪ :‬مــا جــاء‬\n     ‫بدعــوى املدعــي العــام كلــه صحيــح مــا عــدا التســتر فقــد اشــترينا‬\n     ‫هــذه األشــياء مــن أنــاس ال نعرفهــم هكــذا قــررا‪ .‬بعــد ذلــك جــرى منــا‬\n     ‫الرجــوع إلــى أوراق املعاملــة وقــد وجــدت علــى اللفــة رقــم (‪ )15‬التقريــر‬\n     ‫الكيميائــي املرفــق برقــم (‪/11773‬س) واملتوافــق مــع مــا جــاء يف الئحــة‬\n     ‫الدعــوى كمــا أننــي لــم أجــد يف البينــات التــي قدمهــا املدعــي العــام‬\n     ‫مــا يــدل علــى التســتر فبنــاء علــى مــا تقــدم وإلقــرار املدعــى عليهمــا‬\n     ‫مبــا نســب إليهمــا ومبــا أن مــا قامــا بــه فعــل محــرم يســتدعي إقامــة‬\n     ‫حــد املســكر عليهمــا وتعزيرهمــا وملــا جــاء باملــواد احلاديــة واألربعــن‬\n     ‫والسادســة واخلمســن مــن نظــام مكافحــة املخــدرات ولعــدم وجــود‬\n     ‫ســوابق علــى املدعــى عليهمــا ســوى ســابقة مضاربــة علــى األول ممــا‬\n     ‫يتوجــه معــه مراعــات ذلــك والتخفيــف عليهمــا بتطبيــق املــادة الســتني مــن‬\n     ‫نظــام مكافحــة املخــدرات عليهمــا ولعــدم وجــود البينــة علــى تســترهما‬\n     ‫علــى املصــدر لذلــك كلــه فقــد ثبــت لــدي إدانــة املدعــى عليهمــا بحيــازة‬\n     ‫ســيجارة مخلــوط تبغهــا باحلشــيش املخــدر  تــزن جرامــا واحــدا وعشــري‬\n\n\n‫‪57‬‬\n\f  ‫اجلــرام بقصــد التعاطــي وتعاطــي احلشــيش املخــدر وحيــازة األول قــارورة‬\n  ‫مســكر ســعة (‪ )0،6‬لتــر بهــا أكثــر مــن النصــف بقصــد الشــرب‬\n  ‫وقيــادة األول للســيارة حتــت تأثيــر تعاطــي احلشــيش املخــدر وصــدر منــا‬\n  ‫مــا يلــي‪ :‬أوال‪ :‬حكمــت بســجن كل واحــد مــن املدعــى عليهمــا ملــدة‬\n  ‫ثالثــة أشــهر تبــدأ مــن تاريــخ إيقافهمــا للحيــازة بقصــد التعاطــي‪ .‬ثانيــا‪:‬‬\n  ‫حكمــت بإقامــة حــد املســكر علــى املدعــى عليهمــا وذلــك بجلــد كل‬\n  ‫واحــد منهمــا ثمانــن جلــدة دفعــة واحــدة‪ .‬ثالثــا‪ :‬حكمــت بإبعــاد املدعــى‬\n  ‫عليهمــا مــن اململكــة العربيــة الســعودية بعــد تنفيــذ العقوبــة احملكــوم‬\n  ‫بهــا عليهمــا وعــدم الســماح لهمــا بالعــودة مــا عــدا مــا تســمح بــه تعليمــات‬\n  ‫احلــج والعمــرة‪ .‬رابعــا‪ :‬حكمــت بجلــد املدعــى عليــه األول ثالثــن جلــدة‬\n  ‫دفعــة واحــدة حليــازة املســكر بقصــد شــربه‪ .‬خامســا‪ :‬حكمــت بــرد‬\n  ‫دعــوى املدعــي العــام حيــال مطالبتــه تعزيــر املدعــى عليهمــا للتســتر لعدم‬\n  ‫ثبوتــه‪ .‬سادســا‪ :‬أفهمــت املدعــى عليــه األول بــأن عقوبتــه علــى قيــادة‬\n  ‫الســيارة حتــت تأثيــر احلشــيش املخــدر عائــدة للجهــة املختصــة‪ .‬وبعــرض‬\n  ‫احلكــم علــى املدعــى عليهمــا واملدعــي العــام قنــع املدعــى عليهمــا وقــرر‬\n  ‫املدعــي العــام اعتراضــه علــى احلكــم بــدون الئحــة اعتراضيــة مكتفيــا‬\n  ‫مبــا جــاء بــأوراق املعاملــة‪ .‬واختتمــت اجللســة الســاعة ‪. 12:00‬وبــاهلل‬\n  ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                       ‫حــرر يف  ‪ 1434/02/06‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة األولــى  ‬\n  ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض‬\n  ‫برقــم ‪ ...‬وتاريــخ ‪1434/2/27‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n  ‫القاضــي باحملكمــة الشــيخ‪ ...../‬املســجل برقــم‪ .....‬وتاريــخ  ‪1434/2/6‬‬\n\n\n                                                                                          ‫‪58‬‬\n\f     ‫ه ـ اخلــاص بدعــوى  املدعــي  العــام  ضــد  كل  مــن‪ ...-2 ...-1/‬يف قضيــة‬\n     ‫مخــدرات علــى النحــو املوضــح بالقــرار وانتهــاء نظــر القضيــه  بحكــم‬\n     ‫فضيلتــه مبــا هــو مــدون ومفصــل بــه وبدراســة القــرار وصــورة ضبطــه‬\n              ‫وأوراق املعاملــة لــم يظهــر موجــب للمالحظــة  وبــاهلل التوفيــق ‪.‬‬\n\n\n\n\n‫‪59‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":52,"source_page_end":59,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7a5f0bfa4a2cde746b45ab25c95ebe128b810a9ace77b51bec3a2d2de1ecb2ac","normalized_text_hash":"0b87eceb778113df12624cb3b38cf410dda13bb8158a678d5c5778470221f6fd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p52-3432148"},{"id":"279d3f88-ddde-551e-8190-baae3e066a47","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلشيش املخدر واحلبوب احملظورة -حيازة احلشيش املخدر واحلبوب احملظورة -ترويج احلشيش املخدر واحلبوب احملظورة -تسليم احلشيش املخدر واحلبوب احملظورة - رجوع عن إقرار -وجود سوابق قضائية على املدعى عليه -ثبوت إدانة املدعى عليه -صرف نظر عن اإلدانة بالترويج -تعزير بالسجن واجللدواملنع من السفر والغرامة -مصاردة اجلوال والشريحة","document_number":"34203080","case_number":"3480271","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/1","year":"1434","subject":"مخدرات -تعاطي احلشيش املخدر واحلبوب احملظورة -حيازة احلشيش املخدر واحلبوب احملظورة -ترويج احلشيش املخدر واحلبوب احملظورة -تسليم احلشيش املخدر واحلبوب احملظورة - رجوع عن إقرار -وجود سوابق قضائية على املدعى عليه -ثبوت إدانة املدعى عليه -صرف نظر عن اإلدانة بالترويج -تعزير بالسجن واجللدواملنع من السفر والغرامة -مصاردة اجلوال والشريحة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 34203080 :‬تاريخه‪1434/5/1 :‬هـ  ‬\n                       ‫رقم الدعوى‪3480271 :‬‬\n       ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪  34269418‬تاريخه‪1434/7/16 :‬هـ‬\n\n\n\n‫مخــدرات‪ -‬تعاطــي احلشــيش املخــدر واحلبــوب احملظــورة ‪ -‬حيــازة‬\n‫احلشــيش املخــدر واحلبــوب احملظــورة ‪ -‬ترويــج احلشــيش املخــدر‬\n‫واحلبــوب احملظــورة ‪ -‬تســليم احلشــيش املخــدر واحلبــوب احملظــورة ‪-‬‬\n‫رجــوع عــن إقــرار ‪ -‬وجــود ســوابق قضائيــة علــى املدعــى عليــه ‪ -‬ثبــوت‬\n‫إدانــة املدعــى عليــه‪ -‬صــرف نظــر عن اإلدانة بالترويج ‪ -‬تعزير بالســجن‬\n‫واجللدواملنــع مــن الســفر والغرامــة ‪ -‬مصــاردة اجلــوال والشــريحة‬\n                                                              ‫املســتخدمة‪.‬‬\n\n\n\n\n‫‪ -1‬الفقــرة (‪ )2‬مــن املــادة (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام‬\n                                     ‫مكافحــة املخــدرات واﻤﻟﺆﺛﺮات اﻟﻌﻘﻠﻴﺔ‪.‬‬\n‫‪ -2‬والفقــرة (‪ )2-1‬مــن املــادة (‪ )29‬واملــادة (‪ )9‬مــن نظــام الســجن‬\n                                                                  ‫والتوقيــف‪.‬‬\n\n\n\n‫أقيمــت علــى املدعــى عليهمــا دعــوى جنائيــة لقيــام املدعــى عليــه األول‬\n‫بتســليم املخــدرات للمدعــى عليــه الثانــي ومحاولــة الثانــي إدخالهــا‬\n‫للســجن‪ ،‬أنكــر املدعــى عليهمــا الدعــوى وأقــر املدعــى عليــه الثانــي‬\n‫بواقعــة القبــض‪ ،‬مت القبــض علــى املدعــى عليهمــا وبحوزتهــم مــادة‬\n\n                                                                                  ‫‪60‬‬\n\f      ‫احلشــيش   أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة‬\n      ‫للمخدرات‪،‬كمــا تبــن وجــود ســوابق متعــددة وطلــب املدعــي العــام‬\n     ‫تطبيــق النظــام مــن نظــام مكافحــة املخــدرات واﻤﻟﺆﺛﺮات اﻟﻌﻘﻠﻴﺔ ‬\n      ‫ونظــام الســجن والتوقيــف‪ ،‬حكمــت احملكمــة بثبــوت إدانــة املدعــى‬\n      ‫عليــه الثانــي باحليــازة وتوجهــت التهمــة لــأول بتســليم احلبــوب احملظــورة‬\n      ‫وصــرف النظــر عــن إدانــة املدعــى عليهمــا بالترويــج‪ ،‬وســجن الثانــي‬\n      ‫ثمــان ســنوات وغرامــة ماليــة قدرها ثالثة آالف ري ــال‪ ،‬وجلده خمســمائة‬\n      ‫جلــدة مفرقــة علــى عشــر دفعــات بــن كل دفعــة وأخــرى أســبوعا‪،‬‬\n      ‫ومنعــه مــن الســفر خــارج البــاد بعــد انتهــاء محكوميتــه مــدة مماثلــة‬\n      ‫حملكوميتــه‪ ،‬وســجن املدعــى عليــه الثانــي ثــاث ســنوات تســتأنف‬\n      ‫بعــد انتهــاء محكوميتــه حليازتــه املخــدرات‪ ،‬ومصــادرة شــرائح اجلــوال‪،‬‬\n      ‫وســجن املدعــى عليــه األول ثمــان ســنوات‪ ،‬وجلــده خمســمائة جلــدة‬\n      ‫مفرقــة علــى عشــر دفعــات بــن كل دفعــة وأخــرى أســبوعا‪ ،‬اعتــرض‬\n      ‫املدعــى عليهمــا علــى احلكــم‪ ،‬صــدق احلكــم مــن محكمة االســتئناف‪.‬‬\n\n\n\n\n‫‪61‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪..........‬وتاريــخ‬\n‫‪1434/02/18‬ه ـ املقيــدة باحملكمــة برقــم ‪ 1434/02/17..........‬ه ـ‬\n‫ففــي يــوم الســبت املوافــق‪ 1434/02/23‬ه ـ افتتحــت اجللســة الســاعة ‪15‬‬\n‫‪ / 11 :‬وفيهــا تقــدم املدعــي العــام ‪.......... /‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ( ‪ )..........‬وتكليــف رقــم ( ‪ )..........‬وتاريــخ ‪/ 06‬‬\n‫‪1433 / 03‬ه ـ بالئحــة دعــوى وفيهــا أدعــي علــى ‪)43(..........-1  /‬عامـ ًا‬\n‫‪ ،‬ســعودي اجلنســية‪ ،‬مبوجــب الهويــة الوطنيــة رقم(‪)..........‬متســبب‪،‬‬\n‫موقــوف بالســجن العــام مبحافظــة جــدة علــى ذمــة قضيــة أخــرى مبوجــب‬\n                    ‫مذكــرة توقيــف رقــم (‪)..........‬وتاريخ‪1422/12/9‬هــ‪.‬‬\n‫‪ )43(..........-2‬عام ـ ًا ‪ ،‬ســعودي اجلنســية‪،‬مبوجب الهويــة الوطنيــة‬\n‫رقــم(‪ )..........‬متســبب‪،‬موقوف بالســجن العــام مبحافظــة جــدة علــى ذمــة‬\n                    ‫قضيــة أخــرى رقــم (‪ )..........‬وتاريخ‪14331/9/4‬هــ‪.‬‬\n ‫بتاريخ ‪1433/11/30‬هـ مت القبض على املدعى عليهما من قبل ضابط‬\n ‫وحــدة املستشــفيات باملديريــة العامــة للســجون مبحافظــة جــدة بشــعبة‬\n ‫االصالحيــة حيــث مت ضبــط (‪)152.9‬مائــة وإثنــان وخمســن جرام ـ ًا‬\n ‫وتســعة أعشــار اجلــرام مــن مــادة احلشــيش املخــدر و(‪ )3‬ثــاث شــرائح‬\n ‫جــوال بحــوزة الثانــي كمــا مت العثــور علــى قطعة تــزن (‪ )114‬مائة وأربعة‬\n‫عشــر جرامـ ًا مــن مــادة احلشــيش املخــدر و(‪ )276‬مائتــن وســت وســبعني ‬\n ‫حبــة حتتــوي علــى مــادة اإلمفيتامــن املؤثــرة عقليـ ًا و(‪ )28‬ثمان وعشــرين‬\n\n                                                                                    ‫‪62‬‬\n\f       ‫حبــة حتتــوي علــى مــادة الكلونازيبــام حتــت كرســي األول‪،‬ومجموعــة‬\n     ‫مــن أوراق الشــامكان يضعهــا األول يف فنيلتــه الداخليــة مــن األمــام‪  .‬‬\n       ‫و أثبــت التقريــر الكيميائــي الشــرعي رقــم (‪ )..........‬لعام‪1433‬ه ـ‬\n       ‫إيجابيــة العينــة(أ) ممــا مت ضبطــه وإرســاله للتحليــل ملــادة احلشــيش‬\n       ‫املخــدر واحتواءهــا علــى املــادة الفعالــة لــه وايجابيــة العينــة(ب) ممــا مت‬\n       ‫ضبطــه وإرســاله للتحليــل ملــادة احلشــيش املخــدر واحتواءهــا علــى املــادة‬\n       ‫الفعالــة لــه واحتــواء العينــه (ج) ممــا مت ضبطــه وإرســاله للتحليــل ملــادة‬\n       ‫األمفيتامــن املؤثــرة عقليــا واحتــواء العينــه (د) ممــا مت ضبطــه وإرســاله‬\n       ‫للتحليــل لعقــار الكاونازيبــام املؤثــر عقليـ ًا املدرجــة باجلــدول رقــم (‪)2-1‬‬\n       ‫فئــة (أ‪،‬ب‪ ،‬د) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬‬\n       ‫وباســتجواب املدعــى عليــه الثاني‪/‬أقــر بحيــازة(‪ )114‬مائــة وأربعــة عشــر‬\n                                ‫جرامـ ًا مــن احلشــيش املخــدر وثالثــة شــرائح جــوال ‪.‬‬\n       ‫وإنتهى التحقيق إلى توجيه اإلتهام إلى املدعى عليه األول بتســلم(‪)114‬‬\n       ‫مائــة وأربعــة عشــر جرامـ ًا مــن احلشــيش املخــدر و (‪  )276‬مائتــن وســت‬\n       ‫وســبعني حبــة حتتــوي علــى مــادة األمفيتامــن املؤثــرة عقليــا و(‪)28‬ثمــان‬\n       ‫وعشــرين حبــة حتتــوي علــى مــادة الكلونازيبــام املؤثــرة عقلي ـ ًا بقصــد‬\n       ‫الترويــج‪ ،‬واتهــام الثانــي‪ 00000/‬بتســلم(‪)152.9‬مائه واثنــان وخمســن‬\n       ‫جرامـ ًا وتســعة أعشــار اجلــرام مــن احلشــيش املخــدر لــذات القصــد و(‪)3‬‬\n       ‫ثــاث شــرائح جــوال ومحاولــة إدخالهــا الســجن العــام‪ ،‬اســتنادا للفقــرة‬\n       ‫(‪ )2‬مــن املــادة الثالثــة مــن نظــام مكافحــة املخدرات واملؤثــرات العقلية‪،‬‬\n       ‫والفقــرة (‪ )2-1‬مــن املــادة (‪ )29‬مــن نظــام الســجن والتوقيــف ‪ ،‬وذلــك‬\n                                                            ‫لألدلــة والقرائــن التاليــة ‪-:‬‬\n       ‫‪-1‬مــا ورد يف إقــراره الثانــي املنــوه عنــه املــدون بدفتــر التحقيــق صفحــة‬\n\n\n‫‪63‬‬\n\f                                                 ‫(‪ )6‬واملرفــق لفــة رقــم (‪.)23‬‬\n‫‪-2‬مــا ورد يف محضــر املواجهــه املــدون بدفتــر التحقيــق صفحــه (‪)7‬‬\n                                                     ‫واملرفــق لفــه رقــم (‪)23‬‬\n   ‫ال املرفق لفة رقم (‪. )1‬‬ ‫‪ -3‬ما ورد يف محضر الضبط املنوه عنه تفصي ً‬\n‫‪ -4‬مــا ورد بالتقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــة‬\n                                                                   ‫رقــم(‪. )33‬‬\n‫وباالطــاع علــى صحيفــة ســوابقهما عثــر لــاول علــى تســع ســوابق (‬\n‫اربــع ســوابق حيــازة واســتعمال املخــدرات احداهــا مقترنــه بشــرب‬\n‫املســكرات وســابقة شــرب املســكرات مقترنــه بدخــول منــازل لغــرض‬\n‫ســيء وســابقه شــرب املســكرات مقترنــه بحيــازة مســكر وســابقة‬\n‫شــرب املســكرات وســابقة نشــل وســابقة ســرقه وعثــر للثانــي علــى‬\n‫تســع ســوابق ثــاث ســوابق شــرب املســكرات احدهــا مقترنــه بســرقة‬\n‫ســيارات وحيــازة املخــدرات وســابقه ســرقه وســابقه تكويــن عصابــه‬\n‫للســرقه وســابقه ســرقة ســيارات مقترنــه بالســلب وســابقة ســرقة‬\n‫اســطوانة غــاز مقترنــه بدخــول منــازل لغــرض ســيء وســابقة حيــازة‬\n                               ‫املخــدرات ‪ ،‬وســابقة اســتعمال مخــدرات ‪).‬‬\n‫وحيــث إن مــا أقــدم عليــه املدعــى عليهمــا وهمــا بكامــل أهليتهمــا‬\n‫املعتبــرة شــرعا مــن األفعــال احملرمــة شــرع ًا واملجرمــة نظام ـ ًا طبقــا‬\n‫للمــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫الصــادر باملرســوم امللكــي رقــم م‪ 39/‬وتاريــخ ‪1426/7/8‬ه ــواملعاقب‬\n‫عليهــا اســتنادا للمــواد (‪ )41،38‬مــع مراعــاة مــا ورد باملــادة (‪)62‬مــن ذات‬\n‫النظــام وللفقــرة (‪ )2‬مــن املــادة (‪ )29‬مــن نظــام الســجن والتوقيــف ‪ ،‬لــذا‬\n‫فإنــه يتعــن إحالتهمــا إلــى احملكمــة اجلزئيــة مبحافظــة جــدة اســتناد ًا‬\n\n\n                                                                                   ‫‪64‬‬\n\f     ‫للمادتــن (‪ )126 , 128‬مــن نظــام اإلجــراءات اجلزائيــة لطلــب إثبــات مــا‬\n     ‫أســند إليهمــا ومعاقبتهمــا بالعقوبــات األصليــة والتكميليــة التاليــة ‪-:‬‬\n     ‫‪-1‬بالســجن واجللــد والغرامــة لقــاء مــا أســند إليهمــا اســتناد ًا للفقــرة (‪)1‬‬\n     ‫وتشــديد العقوبــة علــى األول إســتناد ًا للحالة(ج)مــن الفقرة(‪)2‬مــن املــادة‬\n                                                             ‫(‪ )38‬مــن نظــام املخــدرات‬\n     ‫‪-2‬معاقبتهمــا بالســجن إســتناد ًا للفقرة(‪)2‬والفقرة(‪)1‬أيض ـ ًا لــأول مــن‬\n                                        ‫املــادة(‪ )29‬مــن نظــام الســجن والتوقيــف ‪.‬‬\n     ‫‪-3‬مصــادرة الشــرائح املضبوطــة مــن نــوع موبايلــي اســتناد ًا للمــادة (‪)9‬‬\n                                                        ‫مــن نظــام الســجن والتوقيــف ‪.‬‬\n     ‫‪-4‬منعهمــا مــن الســفر خلــارج اململكــة بعــد انتهــاء تنفيــذ عقوبتهمــا‬\n     ‫اســتنادا للفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام املخــدرات املشــار إليــه‪.‬‬\n     ‫كمــا اطلــب تشــديد العقوبــة عليهمــا لقــاء تعــدد ســوابقهما التــي‬\n     ‫لــم تردعهمــا عقوباتهــا إســتناد ًا لتعميــم ســمو نائــب وزيــر الداخليــة‬\n     ‫رقــم(‪ )93958/5/5/1‬وتاريخ‪1429/8/23‬ه ــوبسؤال املدعــى عليــه‬\n     ‫ا مــا ذكــره املدعــي‬  ‫األول ‪..........‬عــن دعــوى املدعــي العــام أجــاب قائ ـ ً‬\n     ‫العــام مــن اتهامــي بتســليم الكميــات وحيازتهــا فهــذا كلــه غيــر‬\n     ‫صحيــح وعلــي الســوابق التــي ذكرهــا هــذه إجابتــي وبســؤال املدعــى‬\n     ‫ا مــا ذكــره‬  ‫عليــه الثانــي ‪..........‬عــن دعــوى املدعــي العــام أجــاب قائ ـ ً‬\n     ‫املدعــي العــام مــن انــه قبــض علــي وبحوزتــي احلشــيش فهــذا صحيــح‬\n     ‫وأمــا مــا ذكــره مــن اتهامــي بالترويــج فهــذا غيــر صحيــح والصحيــح‬\n     ‫ذهبــت للمستشــفى للعــاج ووجــدت كيــس علــى األرض وأخذتــه بــدون‬\n     ‫قصــد منــي وضبــط بداخلــه املضبوطــات وعلــى الســوابق التــي ذكرهــا‬\n     ‫هــذه إجابتــي‪ .‬وبســؤال املدعــي العــام عــن بينتــه طلــب إمهالــه إلحضارهــا‬\n\n\n‫‪65‬‬\n\f‫فاســتجبت لطلبــه ‪ .‬رفعــت اجللســة بتاريــخ ‪1434 / 02 / 23‬ه ـ الســاعة‬\n‫احلاديــة عشــر والنصــف‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                    ‫وعلــى آلــه وصحبــه وســلم‪     .‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبحافظــة جــدة املســاعد برقــم ‪..........‬وتاريــخ‬\n‫‪1434/02/18‬ه ــاملقيدة باحملكمة برقم ‪ 1434/02/17..........‬هـ ففي‬\n‫يــوم اإلثنــن املوافــق ‪ 1434/04/29‬ه ـ افتتحــت اجللســة الســاعة الثامنــة‬\n‫وخمس وأربعون دقيقة ‪ ،‬وفيها حضر املدعي واملدعى عليهما وبســؤال‬\n‫ا لقــد مت طلــب البينــة مــن خــال‬    ‫املدعــي العــام عــن بينتــه أجــاب قائ ـ ً‬\n‫أربــع طلبــات وملتــرد لــذا اكتفــى مبــا ورد بــأوراق املعاملــة هــذه إجابتــي‬\n‫وبســؤال املدعــى عليــه الثانــي عــن قصــده مــن احليــازة اجــاب ليــس لــي‬\n‫قصــد هــذا وقــد جــرى االطــاع علــى إقــرار املدعــى عليــه الثانــي واملرفــق‬\n‫باملعاملــة علــى لفــة رقــم ‪ 23‬وعلــى محضــر املواجهــه واملرفــق علــى لفــة‬\n‫رقــم ‪ 3‬وعلــى التقريــر الكيميائــي الشــرعي رقــم ‪..........‬لعــام ‪1433‬ه ـ‬\n‫واملرفــق علــى لفــة رقــم ‪ 33‬يتضمــن ايجابيــة مــامت ضبطــه واحتــواء املــادة‬\n‫املضبوطــه علــى احلشــيش املخــدرو علــى مــادة اإلمفيتامــن املؤثــرة عقليـ ًا‬\n‫وعلــى عقــار الكلونازيبــام املؤثــرة عقليــا ًســو علــى محضــر االســتجواب‬\n‫ومحضــر القبــض وعلــى صحيفتــي ســوابقهما فوجــد كمــا ذكــر‬\n‫ـاء علــى ماتقــدم مــن الدعــوى واإلجابــه ومــا قــرره‬        ‫املدعــي العــام فبنـ ً‬\n‫الطرفــان وحيــث صــادق املدعــى عليــه الثانــي علــى حيــازة احلشــيش‬\n‫واعتــرف بشــرائح اجلــوال وال بينــة للمدعــي علــى املدعــى عليــه األول ‪...‬‬\n‫وملــا تضمنــه التقريــر الكيميائــي الشــرعي املشــار اليــه اعــاه ومحضــر‬\n\n\n                                                                                          ‫‪66‬‬\n\f     ‫القبــض ومحضــر االســتجواب ولتعــدد ســوابقهما وحيــث ماقامــا بــه فعل‬\n     ‫محــرم شــرع ًا يســتحق اعليــه العقوبــة طبق ـ ًا للقواعــد الشــرعية كمــا‬\n     ‫يســتحق املدعــى عليــه الثانــي العقوبــة وفقـ ًا للمادتــن ‪ 56 ، 39‬مــن نظــام‬\n     ‫مكافحــة املخــدرات كمــا يســتحق العقوبــة وفقــا للمادتــن ‪9 ، 29‬‬\n     ‫مــن نظــام الســجن والتوقيــف ولــكل مــا تقــدم فقــد ثبــت لــدي إدانــة‬\n     ‫املدعــى عليــه الثانــي بحيــازة مائــة واربعــه عشــر جرام ـ ًا مــن احلشــيش‬\n     ‫املخــدر بــدون قصــد الترويــج والتعاطــي وثــاث شــرائح جــوال وتوجــه‬\n     ‫الشــبهه بإدانــة املدعــى عليــه األول بتســليم مائــة وأربعــة عشــر جرامــا‬\n     ‫مــن احلشــيش ومائتــان وســت وســبعون حبــه مــن حبــوب اإلمفيتامــن‬\n     ‫وثمــان وعشــرون حبــه مــن حبــوب الكلونازيبــام بقصــد الترويــج كمــا‬\n     ‫تتوجــه الشــبه بإدانــة املدعــى عليــه الثانــي بتســليم مائــة واثنــان وخمســون‬\n     ‫جرام ـ ًا وتســعة أعشــار اجلــرام مــن احلشــيش املخــدر بقصــد الترويــج‬\n     ‫وقــررت تعزيرهمــا لقــاء مــا اســند إليهمــا مبــا يلــي أوالً‪ :‬صــرف النظــر‬\n     ‫عــن إدانــة املدعــى عليهمــا بالترويــج ومعاقبتهمــا وفــق املــادة ‪38‬مــن نظــام‬\n     ‫مكافحــة املخــدرات وللمدعــى عليــه االول املــادة ‪ 56‬مــن ذات النظــام‬\n     ‫واملــادة ‪29‬مــن نظــام الســجن والتوقيــف ثاني ـاً‪ :‬مجــازات املدعــى عليــه‬\n     ‫الثانــي بســجنه خمــس ســنوات وغرامــه ماليــة قدرهــا ‪ 3000‬ثالثــة آالف‬\n     ‫ريــال ومنعــه مــن الســفر خــارج البــاد بعــد انتهــاء محكوميتــه مــدة‬\n     ‫مماثلــة حملكوميتــه وذلــك وفــق املادتــن ‪ 56 ، 39‬مــن نظــام مكافحــة‬\n     ‫املخــدرات ثانيــا ســجن املدعــى عليــه الثانــي ثــاث ســنوات تســتأنف بعــد‬\n     ‫انتهــاء محكوميتــه حليــازة املخــدرات ومصــادرة شــرائح اجلــوال وذلــك‬\n     ‫وفــق املادتــن ‪ 9 ، 29‬مــن نظــام الســجن والتوقيــف ثالثـاً‪ :‬ســجن املدعــى‬\n     ‫عليــه األول ثمــان ســنوات وجلــده ‪ 500‬خمســمائة جلــده مفرقــه علــى‬\n\n\n‫‪67‬‬\n\f‫عشــر دفعــات بــن كل دفعــة واخــرى عشــرة أيــام وذلــك لقــاء التهمــة‬\n‫رابع ـ ًا ‪ :‬جلــد املدعــى عليــه الثانــي خمســمائة جلــده مفرقــه علــى عشــر‬\n‫دفعــات بــن كل دفعــة وأخــرى عشــرة أيــام وذلــك لقــاء تهمــة الترويــج‬\n‫وبذلــك حكمــت‪ ،‬وبعــرض احلكــم علــى املدعــي العــام واملدعــى عليهما‬\n‫قــرر املدعــي العــام معارضتــه بالئحــة وقــرر املدعــى عليهمــا املعارضــه‬\n‫بالئحه‪،‬جــرى النطــق باحلكــم بتاريــخ ‪1434/4/29‬ه ـ الســاعة التاســعة‬\n‫‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‬\n‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة‬\n‫االســتئناف يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة جــدة برقــم‪..........‬‬\n‫وتاريخ‪1434/6/26‬هاملرفق بها القرار رقم‪ ..........‬وتاريخ‪1434/5/1‬هـ‬\n‫الصــادر مــن فضيلــة الشــيخ‪........../‬القاضي باحملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة املتضمــن دعــوى املدعــي العــام ضــد‪ .......... /‬ســعودي‬\n‫اجلنســية ورفيقــه يف قضيــة مخــدرات احملكــوم فيــه مبــا دون بباطــن‬\n‫القــرار ‪ ،‬وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة قررنــا‬\n‫املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                 ‫وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪68‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":60,"source_page_end":68,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4c4a3024ee0fe513d970ecefc2f3f3fe2841e3a429b47f37cf42cb3edca7273c","normalized_text_hash":"4fef6128f60cc3e0d132316bd3a0f1259d5ca67797cc820a612d4ab90afc7399","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p60-34203080"},{"id":"a876df2f-56e5-50fd-b4f4-cd2884bbc1b0","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -مسكر -تعاطي احلشيش -شرب املسكر -إقامة حد املسكر -منع من السفر.","document_number":"3442674","case_number":"3481710","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/20","year":"1434","subject":"مخدرات -مسكر -تعاطي احلشيش -شرب املسكر -إقامة حد املسكر -منع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪  3442674 :‬تاريخه ‪1434/02/20 :‬هـ‬\n                           ‫رقم الدعوى‪3481710 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34238706‬تاريخه‪1434/06/12 :‬هـ‬\n\n\n\n     ‫مخــدرات ‪ -‬مســكر ‪ -‬تعاطــي احلشــيش ‪ -‬شــرب املســكر ‪ -‬إقامــة حــد‬\n                                               ‫املســكر ‪ -‬منــع مــن الســفر‪.‬‬\n\n\n\n\n     ‫اب‬ ‫ال ْم ُر َو ْالَ ْي ِس ُر َوا َأل َ‬\n     ‫نص ُ‬                                ‫نا ْ َ‬   ‫آم ُنو ْا ِإ َّ َ‬  ‫‪ -1‬قول اهلل تعالى «( َيـا َأ ُّي َها ا َّلذِ َ‬\n                                                                  ‫ين َ‬\n               ‫ون )‪.‬‬ ‫وه َل َع َّل ُك ْم ُت ْفل ُِح َ‬\n                                                   ‫اج َتن ُِب ُ‬                 ‫س ِّم ْن َع َملِ َّ‬\n                                                                 ‫الش ْي َطانِ فَ ْ‬                    ‫َوا َأل ْز َال ُم ِر ْج ٌ‬\n              ‫‪ -2‬املادة (‪ )56/1‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n\n\n\n\n     ‫تقــدم مواطــن ملركــز الشــرطة ببــاغ تضمــن تعرضــه للعقــوق والتهديــد‬\n     ‫مــن قبــل ابنــه املتعاطــي للمســكر واحلشــيش‪ ،‬فــرزت أوراق بقضيــة‬\n     ‫العقــوق ـ طلــب املدعــي العــام إقامــة حــد املســكر علــى املدعــى عليــه‬\n     ‫لشــربه املســكر وتعاطيــه احلشــيش‪ ،‬أقــر املدعــى عليــه مبــا نســب إليــه‬\n     ‫‪ ،‬صــدر احلكــم  بإثبــات إدانــة املدعــى عليــه  بشــرب املســكر وتعاطــي‬\n     ‫احلشــيش‪ ،‬احلكــم بإقامــة حــد املســكر علــى املدعــى عليــه ومنعــه مــن‬\n                             ‫الســفر‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪69‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة مــن فضيلــة الرئيــس‬\n‫برقم  وتاريخ ‪ 1434 / 2 / 18‬هـ املقيدة باحملكمة برقم  وتاريخ ‪/ 18‬‬\n‫‪ 1434 / 2‬ه ـ واملتعلقــة بدعــوى املدعــي العــام ‪ ......./‬ضــد ‪ ،....... /‬حامــل‬\n‫الســجل املدنــي رقــم (‪ )....‬ففــي يــوم  األربعــاء ‪1434/ 2 / 20‬ه ـ فتحــت‬\n‫اجللســة الســاعة ‪  10 : 00‬وفيهــا حضــر  املدعــي العــام واملدعــى عليــه‬\n‫املدونــة هويتــه بعاليــه وقــدم املدعــي العــام الئحــة الدعــوى املتضمنــة مــا‬\n‫يلــي ‪ ( :‬أدعــي علــى‪ ،‬البالــغ مــن العمــر (‪ )23‬عام ـ ًا ‪ ،‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ )....‬غيــر محصــن‪ ،‬عاطــل عــن العمــل‪،‬‬\n‫وأحيــل لســجن محافظــة ‪ ....‬اســتناد ًا للقــرار الــوزاري رقــم (‪)1900‬‬\n‫وتاريــخ ‪1428/7/9‬ه ـ ‪ ،‬حيــث أنــه بتاريــخ ‪1433/12/10‬ه ـ ورود‬\n‫بــاغ الــى مركــز شــرطة صفــوى مــن املواطــن‪ /‬مفــاده قيــام ابنــه الــذي‬\n‫يســكن لديــه يف منزلــه يف محافظــة ‪ ....‬باالعتــداء عليــه وتهديــده بآلــة‬\n‫حــادة وبقيامــه بعقــوق والديــه والتلفــظ عليهمــا كمــا أفــاد بــأن أبنــه‬\n‫املذكــور يقــوم بتعاطــي املخــدرات (أفــرزت أوراق مســتقلة بقضيــة‬\n‫العقــوق وعوجلــت مــن قبــل جهــة االختصــاص)‪ .‬وباســتجواب املدعــى‬\n‫عليــه أقــر بقيامــه بشــرب املســكر وأن أخــر مــرة شــرب املســكر فيهــا‬\n‫هــو قبــل القبــض عليــه بيومــن وأنــه يتعاطــى احلشــيش املخــدر وآخــر‬\n‫مــرة تعاطــى احلشــيش املخــدر قبــل ســنة ونصــف مــن القبــض عليــه‪.‬‬\n‫وقــد أســفر التحقيــق معــه الــى توجيــه االتهــام لــه وبشــرب املســكر‬\n‫وتعاطــي احلشــيش املخــدر ‪ ،‬وذلــك لألدلــة والقرائــن التاليــة ‪ -1:‬إقــرار‬\n\n                                                                                      ‫‪70‬‬\n\f       ‫املدعــى عليــه واملــدون علــى صــورة ملــف التحقيــق واملرفقــة علــى اللفتــن‬\n       ‫رقــم (‪ )11.10‬واملــدون علــى الصفحتــن رقــم ( ‪ )3.2‬مــن ملــف ضبــط‬\n       ‫إجــراءات قضيــة ‪ -2.‬مــا جــاء يف إفــادة املواطــن ‪ /‬واملدونــة علــى صــورة‬\n       ‫تقريــر األحــوال األمنيــة واملرفــق علــى اللفــة رقــم (‪ .)5-1‬وبالبحــث عــن‬\n       ‫ســوابقه عثــر لــه علــى ســابقة عقــوق والديــن‪ .‬وحيــث إن مــا أقــدم عليــه‬\n       ‫املذكــور ‪ -‬وهــو بكامــل أهليتــه املعتبــرة شــرعا ‪ -‬فعــل محــرم ومعاقــب‬\n     ‫عليــه شــرع ًا ونظام ـ ًا لــذا اطلــب مــا يلــي‪ :‬أوال‪ :‬اثبــات شــربه للمســكر  ‬\n       ‫واحلكــم عليــه بحــد الســكر ‪ .‬ثانيــا‪ :‬إثبــات مــا اســند إليــه حيــال تعاطــي‬\n       ‫احلشــيش املخــدر وفــق الفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام‬\n       ‫مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم عليــه مبــا يلــي ‪-1 :‬‬\n       ‫عقوبــة الســجن الــواردة بالفقــرة رقــم(‪ )1‬مــن املــادة رقــم(‪ )41‬مــن النظــام‬\n       ‫‪ -2 .‬منعــه مــن الســفر وفــق الفقــرة (‪ )1‬مــن املــادة رقــم(‪ )56‬مــن النظــام‪.‬‬\n       ‫وبــاهلل التوفيــق) ا‪ .‬ه ـ وبعــرض الدعــوى علــى املدعــى عليــه أجــاب بقولــه‬\n       ‫مــا جــاء يف االتهــام املوجــه لــي كلــه صحيــح هــذا جوابــي فبنــاء علــى مــا‬\n       ‫تقــدم مــن الدعــوى واإلجابــة وبنــاء علــى إقــرار املدعــى عليــه مبــا نســب‬\n       ‫إليــه ولقولــه تعالــى ‪( :‬يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n       ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) فقــد‬\n       ‫حكمــت مبــا يلــي ‪-1 :‬ثبــوت إدانــة املدعــى عليــه بشــرب املســكر‬\n       ‫وتعاطــي احلشــيش املخــدر ‪ -2‬جلــد املدعــى عليــه ثمانــن جلــدة حــد‬\n       ‫املســكر  وأفهمتــه بانطبــاق املــادة ‪ 1/56‬مــن نظــام املخــدرات عليــه‬\n       ‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام عــدم قناعتــه ورغبتــه‬\n       ‫رفــع احلكــم حملكمــة االســتئناف بــدون الئحــة اعتراضيــة وقــرر‬\n       ‫املدعــى عليــه قناعتــه وبــاهلل التوفيــق وقــد مت االنتهــاء مــن حتريــره يف‬\n\n‫‪71‬‬\n\f         ‫متــام الســاعة ‪ 10 : 20‬مــن يــوم األربعــاء ‪1434/ 2 / 20‬ه ـ ‪،،،‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم  الســبت ‪1434/ 5 / 4‬ه ـ فتحــت اجللســة‬\n‫الســاعة (‪  )9 : 30‬وقــد وردتنــا املعاملــة وبرفقهــا قــرار أصحــاب الفضيلــة‬\n‫قضــاة محكمــة االســتئناف باملنطقــة الشــرقية رقــم ‪ 34193816‬يف‬\n‫‪1434/4/21‬ه ـ املتضمــن املالحظــة مبــا نصــه ‪( :‬أوال ‪ :‬أن إجابــة املدعــى‬\n‫عليــه غيــر مكتملــة ‪ .‬ثاني ـ ًا ‪ /‬أفهــم فضيلتــه بانطبــاق املــادة ‪ 1/56‬ولــم‬\n‫يبينهــا حتــى تعلــم لــدى جهــات التنفيــذ) ا‪.‬ه ـ واجلــواب أنــه قــد حضــر يف‬\n‫هــذه اجللســة املدعــى عليــه وجــرى اســتدراك النقــص املشــار إليــه وأخــذ‬\n‫توقيعــه عليــه كمــا جــرى اســتدراكه يف القــرار وأمــا املــادة ‪ 1/56‬فهــي‬\n‫املنــع مــن الســفر مــدة ســنتني وبــاهلل التوفيــق وقــد مت االنتهــاء مــن حتريره‬\n                                                    ‫يف متــام الســاعة (‪.  )9 : 45‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم  الثالثــاء ‪1434/ 6 / 27‬هــ  فتحــت‬\n‫اجللســة الســاعة (‪  )9 : 15‬وقــد وردتنــا املعاملــة وبرفقهــا قــرار أصحــاب‬\n‫الفضيلــة قضــاة محكمــة االســتئناف باملنطقــة الشــرقية رقــم   يف‬\n‫‪1434/6/12‬ه ـ املتضمــن املصادقــة علــى احلكــم  وبــاهلل التوفيــق وقــد‬\n                      ‫مت االنتهــاء مــن حتريــره يف متــام الســاعة (‪.  )9 : 25‬‬\n\n\n\n\n                                                                                        ‫‪72‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":69,"source_page_end":72,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"42b53ff85b8724a126f24086f5ab47b71c9472d3e127e6a4081a35bd47e090d2","normalized_text_hash":"c02615501cba80b0cfd4e2f32ac422a4fe42dbd8721d8970acc87802226bbfd6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p69-3442674"},{"id":"54421161-31e1-5b41-89b8-0c5e3c4dbdf1","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلشيش املخدر -شرب املسكر -قيادة السيارة حتت تأثير املسكر اإلقرار -إقامة حد املسكر -املنع من السفر -1ما رواه أنس بن مالك رضي اهلل عنه أن النبي صلى اهلل عليه وسلم ( :أتى برجل قد شرب اخلمر فجلده بجريدتن نحو أربعن قال وفعله أبو بكر فلما كان عمر استشار الناس فقال عبدالرحمن بن عوف أخف احلدود ثمانون فأمر به) متفق عليه -2وعن علي رضي اهلل عنه يف قصة الوليد بن عقبة قال ( :جلد","document_number":"32343839","case_number":"32240283","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1432/12/02","year":"1434","subject":"مخدرات -تعاطي احلشيش املخدر -شرب املسكر -قيادة السيارة حتت تأثير املسكر اإلقرار -إقامة حد املسكر -املنع من السفر -1ما رواه أنس بن مالك رضي اهلل عنه أن النبي صلى اهلل عليه وسلم ( :أتى برجل قد شرب اخلمر فجلده بجريدتن نحو أربعن قال وفعله أبو بكر فلما كان عمر استشار الناس فقال عبدالرحمن بن عوف أخف احلدود ثمانون فأمر به) متفق عليه -2وعن علي رضي اهلل عنه يف قصة الوليد بن عقبة قال ( :جلد","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 32343839 :‬تاريخه‪1432/12/02 :‬هـ‬\n                        ‫رقم الدعوى‪32240283 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫تاريخه‪1434/6/6 :‬هـ‬        ‫‪34232106‬‬\n\n\n\n     ‫مخــدرات ‪ -‬تعاطــي احلشــيش املخــدر ‪ -‬شــرب املســكر ‪ -‬قيــادة الســيارة‬\n      ‫حتــت تأثيــر املســكر ـ اإلقــرار ‪ -‬إقامــة حــد املســكر ‪ -‬املنــع مــن الســفر‬\n\n\n\n\n     ‫‪-1‬مــا رواه أنــس بــن مالــك رضــي اهلل عنــه أن النبــي صلــى اهلل عليــه‬\n     ‫وســلم ‪ ( :‬أتــى برجــل قــد شــرب اخلمــر فجلــده بجريدتــن نحــو أربعــن‬\n     ‫قــال وفعلــه أبــو بكــر فلمــا كان عمــر استشــار النــاس فقــال عبدالرحمن‬\n                         ‫بــن عــوف أخــف احلــدود ثمانــون فأمــر بــه) متفــق عليــه‬\n     ‫‪-2‬وعــن علــي رضــي اهلل عنــه يف قصــة الوليــد بــن عقبــة قــال ‪ ( :‬جلــد‬\n     ‫النبــي صلــى اهلل عليــه وســلم أربعــن وجلــد أبــو بكــر أربعــن وجلــد عمــر‬\n                                       ‫ثمانــن وهكــذا أحــب إلـ َّـي ) أخرجــه مســلم‬\n     ‫‪-3‬وعــن معاويــة رضــي اهلل عنــه عــن النبــي صلــى اهلل عليــه وســلم ‪ ( :‬أنــه‬\n                ‫قــال شــارب اخلمــر إذا شــرب فاجلــدوه ) أخرجــه أحمــد واألربعــة‬\n                  ‫‪-4‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر  و تعاطــي‬\n     ‫احلشــيش املخــدر و قيــادة الســيارة حتــت تأثيرهمــا وطلــب املدعــي العــام‬\n     ‫إثبــات  مــا أســند للمدعــى عليــه واحلكــم عليــه بعقوبة حد املســكر لقاء‬\n\n‫‪73‬‬\n\f‫تعاطيــه للحشــيش ‪ .‬العقوبــة الــواردة يف الفقــرة األولــى من املادة (‪ )41‬من‬\n‫نظــام مكافحــة املخــدرات لتعاطيــه احلشــيش املخــدر ‪ ،‬العقوبــة الــواردة‬\n‫يف الفقــرة األولــى مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات وذلــك‬\n‫مبنعــه مــن الســفر خــارج البــاد ‪ ،‬إثبــات قيادتــه للســيارة حتــت تأثيــر‬\n‫شــرب املســكر و تعاطيــه احلشــيش املخــدر و إفهامــه بــأن عقوبتــه عائــدة‬\n‫للجهــة املختصــة حيــث انــه قبــض عليــه مــن قبــل رجــال الضبــط اجلنائــي‬\n‫إثــر اشــتراكه مــع أحــد األشــخاص بســرقة محطــة وقــود حتــت اإلنشــاء‬\n‫وعنــد القبــض عليــه تبــن أنــه بحالــة ســكر وباستشــمامه تبــن انبعــاث‬\n‫رائحــة املســكر مــن جوفــه وبتحليــل ســوائله أثبــت تقريــر الســموم‬\n‫الشــرعية إيجابيتهمــا ملركبــات احلشــيش ‪،‬كمــا أقــر املدعــى عليــه مبــا‬\n‫نســب إليــه بنــاء علــى مــا تقــدم حكمــت احملكمــة بإقامــة حــد املســكر‬\n‫عليــه بجلــده ثمانــن جلــدة واملنــع مــن الســفر ملــدة ســنتني وصــرف النظــر‬\n‫عــن تطبيــق املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات وإثبــات إدانــة‬\n‫املدعــى عليــه بقيــادة الســيارة حتــت تأثيــر املســكر و عقوبتــه يف ذلــك‬\n‫عائــدة للجهــة املختصــة‪ ،‬قنــع املدعــى عليــه باحلكــم وقــرر املدعــي العــام‬\n ‫االعتــراض مــن غيــر الئحــة وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n                                                                                    ‫‪74‬‬\n\f     ‫اجلزئيــة‬\n        ‫ّ‬      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪....‬القاضــي يف احملكمــة‬\n     ‫باالحســاء  وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫اجلزئية يف محافظة االحساء برقم ‪ 32240283‬وتاريخ ‪1432/06/21‬هـ  ‬\n       ‫املقيــدة باحملكمــة برقــم ‪ 32750534‬وتاريــخ ‪1432/06/21‬هــ  ففــي‬\n     ‫يــوم  الســبت املوافق‪1432/12/02‬ه ـ أفتتحــت اجللســة الســاعة ‪  10 : 30‬‬\n       ‫وفيهــا حضــر  املدعــي العــام  ‪....‬واملدعــى عليــه  ‪  ....‬ســعودي اجلنســية‬\n       ‫مبوجــب الســجل املدنــي رقــم   ‪....‬وادعــى املدعــي العــام قائــا يف دعــواه‬\n       ‫إنــه بتاريــخ ‪1432/5/1‬ه ـ قبــض عليــه مــن قبــل رجــال الضبــط اجلنائــي‬\n     ‫مبركــز شــرطة الرقيقــة مبحافظــة األحســاء إثــر اشــتراكه مــع املدعــو  ‬\n       ‫‪....‬بســرقة محطــة وقــود حتــت اإلنشــاء ( فــرزت لقضيــة الســرقة أوراق‬\n       ‫مســتقلة ومعاجلتهــا مــن قبــل جهــة االختصــاص ) وعنــد القبــض عليــه‬\n       ‫تبــن أنــه بحالــة ســكر ‪ ،‬وباستشــمامه تبــن انبعــاث رائحــة ا ملســكر‬\n       ‫مــن جوفــه ‪ ،‬وبتحليــل عينــة مــن ســوائله أثبــت تقريــر الســموم الشــرعية‬\n     ‫رقــم ( ‪ 753‬م ‪ .‬أ ) لعــام ‪1432‬ه ـ إيجابيتهــا ملركبــات احلشــيش املخــدر‬\n     ‫وباســتجواب املدعــى عليــه أقــر بصحــة واقعــة القبــض عليــه وتعاطيــه‬\n     ‫احلشــيش املخــدر ‪ ،‬وصــدق إقــراره شــرع ًا بذلــك ‪ ،‬كمــا أقــر حتقيق ـ ًا‬\n     ‫بشــربه املســكر وقيــادة الســيارة حتــت تأثيرهــا عنــد القبــض عليــه‬\n     ‫وقــد أســفر التحقيــق عــن توجيــه االتهــام لــه بشــرب املســكر وتعاطــي‬\n     ‫احلشــيش املخــدر وقيــادة الســيارة حتــت تأثيرهمــا‪ ،‬وذلــك لألدلــة‬\n     ‫والقرائــن التاليــة‪ :‬ـ‪ 1‬إقــراره املصــدق عليــه شــرع ًا وحتقيق ـ ًا املــدون‬\n     ‫علــى   الصفحــة رقــم (‪ )3‬مــن ملــف ضبــط اإلجــراءات واللفــة رقــم‬\n\n‫‪75‬‬\n\f‫(‪-2.)3‬تقريــر الدوريــات األمنيــة املرفــق صــورة منهــا علــى اللفــات رقــم  ‬\n  ‫(‪ 24‬ـ ‪-3 )26‬محضــر االستشــمام املرفــق صــورة منــه علــى اللفــة رقــم (‬\n  ‫‪-4 ) 20‬تقريــر الســموم الشــرعية املرفــق علــى اللفــة رقــم ( ‪ ) 33‬وببحــث‬\n  ‫ســوابقه لــم يعثــر لــه علــى ســوابق جنائيــة مســجلة وحيــث إن مــا أقــدم‬\n  ‫عليــه املذكــور ـ وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ـ فعــل محــرم‬\n  ‫ومعاقــب عليــه شــرع ًا ونظامـ ًا يف ضــوء الفقــرة الثانيــة مــن املــادة الثالثــة‬\n  ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n  ‫امللكــي الكــرمي رقــم ( م‪ ) 39/‬وتاريــخ ‪1432/7/8‬ه ـ أطلــب إثبــات‬\n  ‫مــا أســند إليــه واحلكــم عليــه مبــا يلــي ‪ :‬ـ ‪ 1‬ـ بعقوبــة حــد املســكر لقــاء‬\n  ‫شــربه لــه ولتعاطيــه احلشــيش املخــدر  ـ ‪ 2‬ـ بالعقوبــة املــواردة يف الفقــرة‬\n  ‫األولــى مــن املــادة ( ‪ ) 41‬مــن النظــام املشــار إليــه أعــاه لتعاطيه احلشــيش‬\n  ‫املخــدر ‪ 3‬ـ بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة ( ‪ ) 56‬مــن‬\n  ‫النظــام املشــار إليــه أعــاه وذلــك مبنعــه مــن الســفر إلــى خــارج البــاد ‪4.‬ـ‬\n  ‫إثبــات قيادتــه للســيارة حتــت تأثيــر شــرب املســكر وتعاطيــه احلشــيش‬\n  ‫املخــدر وإفهامــه بــأن عقوبتــه الــواردة يف الفقــرة األولــى مــن املــادة ( ‪68‬‬\n  ‫) مــن نظــام املــرور تقــرر مــن اجلهــة املختصــة هــذه دعــواي وبعرضهــا علــى‬\n  ‫املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي العــام صحيــح فقــد شــربت‬\n  ‫املســكر وتعاطيــت احلشــيش املخــدر وقــدت الســيارة حتــت تأثيرهمــا‬\n  ‫وأنــا تائــب إلــى اهلل تعالــى ونــادم علــى مــا صــدر منــي هكــذا أجــاب‬\n  ‫وبنــاء علــى مــا ســلف مــن الدعــوى واإلجابــة وإقــرار املدعــى عليــه جملــة‬\n  ‫وتفصيــا ومــا قــرره مــن ندمــه مــن توبتــه وخلــو ســجله مــن الســوابق‬\n  ‫وبنــاء علــى إقــراره بشــربه للمســكر وتعاطيــه احلشــيش (ملــا رواه انــس‬\n  ‫بــن مالــك رضــي اهلل عنــه أن النبــي صلــى اهلل عليــه وســلم أتــي برجــل قــد‬\n\n\n                                                                                           ‫‪76‬‬\n\f     ‫شــرب اخلمــر فجلــده بجريدتــن نحــو أربعــن قــال وفعلــه أبــو بكــر فلمــا‬\n     ‫كان عمــر استشــار النــاس فقــال عبــد الرحمــن بــن عــوف اخــف احلــدود‬\n     ‫ثمانــون فأمــر بــه عمــر متفــق عليــه وعــن علــي رضــي اهلل عنــه يف قصــة‬\n     ‫الوليــد بــن عقبــه قــال جلــد النبــي صلــى اهلل عليــه وســلم أربعــن وجلــد‬\n     ‫أبوبكــر أربعــن وجلــد عمــر ثمانــن وهــذا أحــب إلــي أخرجــه مســلم‬\n     ‫وعــن معاويــة رضــي اهلل عنــه عــن النبــي صلــى اهلل عليــه وســلم انــه قــال‬\n     ‫يف شــارب اخلمــر إذا شــرب فاجلــدوه أخرجــه احمــد واالربعــه وبنــاء عليــة‬\n     ‫فقــد ثبــت لــدي شــرب املدعــى عليــه للخمــر املســكر) ونظــر ًا لكــون‬\n     ‫العقوبــات الشــرعية واحلــدود تتداخــل وعليــه فعقوبــة املدعى عليه لشــربه‬\n     ‫للمســكر وتعاطيــه للحشــيش واحــدة وبنــاء علــى إقــراره بقيــادة الســيارة‬\n     ‫حتــت تأثيــر املســكر واحلشــيش وانطبــاق املــادة املذكــورة عليــه ونظــر ًا‬\n     ‫لكــون مــا طالــب بــه املدعــي العــام مــن املادتــن (‪ )56-41‬مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة  ال وجــه لــه فــإن العقوبــة حديــه‬\n                                                                       ‫وال زيــادة عليهــا‬\n     ‫وبنــاء علــى ذلــك كلــه فقــد قــررت مــا يلي ‪ :‬أوال‪ :‬ثبت لدي شــرب املدعى‬\n     ‫عليــه للمســكر وتعاطــي احلشــيش وقــررت عقوبتــه بجلــده ثمانــن جلــده‬\n     ‫دفعــة واحــدة حــد ًا ثانيــا‪ :‬ثبــت لــدي قيادتــه لســيارة حتــت تأثيــر املســكر‬\n     ‫واحلشــيش وأفهمتــه أن عقوبتــه علــى ذلــك عائــدة للجهــة املختصــة ‪:‬ثالثــا‪:‬‬\n     ‫رددت مــا طالــب بــه املدعــي العــام مــن تطبيق املادتــن (‪ )56-41‬من نظام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة ومبــا تقــدم حكمــت وبعرضــه‬\n     ‫علــى املدعــى عليــه قنــع بــه وبعرضــه علــى املدعــى العــام قــرر عــدم‬\n     ‫القناعــة وطلــب االســتئناف مكتفيــا مبــا قــدم عــن أالئحــة االعتراضيــة‬\n     ‫وأجبتــه لطلبــه وقــررت رفــع املعاملــة إلــى محكمــة االســتئناف باملنطقــة‬\n\n\n‫‪77‬‬\n\f‫الشــرقية حســب التعليمــات واهلل املوفــق  وصلــى اهلل علــى نبينــا محمــد‬\n                    ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1432/12/02‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم األحــد املوافــق ‪1434/4/14‬ه ـ‬\n‫افتتحــت اجللســة الرابعــة لهــذه القضيــة يف متــام الســاعة التاســعة وفيهــا‬\n‫حضــر املدعــي العــام واملدعــى عليــه  ‪ ....‬وقــد جــرت الكتابــة إلــى‬\n‫إدارة مكافحــة املخــدرات مبحافظــة االحســاء إلبــاغ املدعــى عليــه‬\n‫باحلضــور يــوم الثالثــاء املوافــق ‪1433/5/18‬هــ  فوردنــي خطــاب مديــر‬\n‫مكافحــة املخــدرات مبحافظــة االحســاء برقــم ‪22/3/3/95‬س وتاريــخ‬\n‫‪1434/1/3‬ه ـ املتضمــن مــا نصــه ( نفيدكــم بأنــه مت االتصــال بــه‬\n‫وبكفيلــه ولــم يتجــاوب ومت التعميــم عليــه ومت إيقافــه لكونــه مطلوبــا‬\n‫يف هــذه القضيــة ) أ‪ .‬ه ـ وقــد قــرر املدعــى عليــه قائــا لــم ابلــغ بــأي موعــد‬\n‫مــن اجلهــات املختصــة بالتبليــغ ولــم يبلــغ كفيلــي بذلــك وقــد توظفــت‬\n‫يف شــركة  ‪....‬بتاريــخ ‪2012/1/12‬م وقــد عقــدت الــزواج منــذ شــهر‬\n‫تقريبــا وأنــا تائــب إلــى اهلل تعالــى ونــادم علــى مــا صــدر منــي  هكــذا‬\n‫قــرر فبنــاء علــى مــا ســلف ونظــرا ملــا أبــداه املدعــى عليــه مــن التوبــة‬\n‫والنــدم وبنــاء علــى مــا قــرره أصحــاب الفضيلــة حفظهــم اهلل يف القــرار‬\n‫املشــار إليــه أعــاه وبنــاء علــى مــا جــرى عليــه العمــل مــن تطبيــق املــادة‬\n‫‪ 56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة يف مثــل هــذه‬\n‫احلالــة وأمــا املــادة ‪ 41‬مــن ذلــك النظــام فإنهــا توجــه إلــى املدعــى عليــه‬\n‫يف حالــة كونــه متهمــا بحيــازة احلشــيش ولــم تتضمــن الئحــة الدعــوى‬\n‫العامــة توجيــه االتهــام إلــى املدعــى عليــه بحيــازة املســكرات وبنــاء‬\n‫علــى ذلــك كلــه فقــد قــررت مــا يلــي ‪ - :‬أوال ‪ /‬رجعــت عمــا حكمــت‬\n‫بــه يف الفقــرة الثالثــة مــن تــرك تطبيــق املــادة ‪ 56‬مــن نظــام مكافحــة‬\n\n\n                                                                                         ‫‪78‬‬\n\f     ‫املخــدرات واملؤثــرات العقليــة وقــررت عقوبــة املدعــى عليــه مبنعــه مــن‬\n     ‫الســفر خــارج البــاد ملــدة ســنتني ‪ .‬ثانيــا ‪ /‬مــا زلــت علــى مــا حكمــت بــه‬\n     ‫يف الفقرتــن األولــى والثانيــة ومــا حكمــت بــه مــن رد الدعــوى العامــة‬\n     ‫بشــأن املــادة ‪ 41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n     ‫وبذلــك حكمــت وبعرضــه علــى املدعــى عليــه قــرر قناعتــه بــه وبعرضــه‬\n     ‫علــى املدعــي العــام قــرر عــدم القناعــة وطلــب االســتئناف مكتفيــا مبــا‬\n     ‫قــدم عــن تقــدمي الئحــة اعتراضيــة فأجبتــه لطلبــه وقــررت رد املعاملــة‬\n     ‫إلــى محكمــة االســتئناف باملنطقــة الشــرقية حســب التعليمــات لتقريــر‬\n     ‫مــا يرونــه أصحــاب الفضيلــة حفظهــم اهلل وأقفلــت اجللســة الســاعة‬\n     ‫التاســعة والنصــف وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                      ‫الــه وصحبــه وســلم حــرر يف ‪1434/4/14‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n     ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n     ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف‬\n     ‫برقــم ‪ 3418062‬وتاريــخ ‪1434/4/28‬هــ  املقيــدة لــدى احملكمــة برقــم‬\n     ‫‪ 34/1071220‬وتاريــخ ‪1434/5/1‬هــ  املرفــق بهــا القــرار الصــادر مــن‬\n     ‫فضيلــة القاضــي باحملكمــة الشــيخ   ‪ ....‬املســجل برقــم ‪32343839‬‬\n     ‫وتاريــخ ‪1432/12/2‬هــ  اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪....  /‬يف‬\n     ‫قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n     ‫ومفصــل فيــه ‪ .‬حيــث ســبق دراســة القراروصــورة ضبطــه وأوراق املعاملــة‬\n     ‫وباالطــاع علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة‬\n     ‫ضبطــه بنــاء علــى قرارنــا رقــم‪      38‬يف‪1433/1/5‬ه ـ قررنــا املصادقــة‬\n     ‫علــى احلكــم بعــد االجــراء االخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                          ‫محمــد وعلــى آلــه وصحبــه وســلم حرريف‪1434/6/3‬ه ـ‬\n‫‪79‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":73,"source_page_end":79,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5ca5177fd5f18d7d597c2c560b207a5aaebd2bd2d8d52f32b0a2cc16d52b7043","normalized_text_hash":"2f691e9df936c1fda115abf67877e838b9d5da787141c55c08e1deb4d1a13334","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p73-32343839"},{"id":"e1fdd52a-6ca8-5634-841a-d86147f299ad","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلشيش املخدر -إنكار -تعزير للتهمة -التعزير","document_number":"3454170","case_number":"33395222","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف وتعزير املدعى عليه باجللد باجلوف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/3","year":"1434","subject":"مخدرات -تعاطي احلشيش املخدر -إنكار -تعزير للتهمة -التعزير","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 3454170:‬تاريخه‪1434/3/3 :‬هـ‬\n                    ‫رقم الدعوى‪33395222 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪      331095191‬تاريخه‪1434/4/22:‬هـ‬\n\n\n\n‫مخــدرات ‪ -‬تعاطــي احلشــيش املخــدر‪ -‬إنــكار ‪ -‬تعزيــر للتهمــة ‪ -‬التعزير‬\n                                                                   ‫باجللد‬\n\n\n\n\n             ‫‪ .1‬املادة ‪ 56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n             ‫‪ .2‬املادة ‪ 41‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بتعاطيــه احلشــيش املخــدر وطلــب‬\n‫املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة الســجن واملنــع‬\n‫مــن الســفر‪ ،‬مت كشــف جــرم املدعــى عليــه حيــث كان ســجين ًا وطلــب‬\n‫حتويلــه إلــى املستشــفى العــام مدعي ـ ًا أن بيــده كســر وعنــد دخولــه‬\n‫قســم األشــعة مــد يــده إلــى جانــب الكرســي وأخــذ شــيئ ًا ثــم أبتلعــه‬\n‫وأثبــت إيجابيــة التحليــل  ملــادة احلشــيش املخــدر‪ ،‬أنكــر املدعــى عليــه‬\n‫الدعــوى‪ ،‬وبالبحــث عــن ســوابقه وجــد لــه ســوابق‪ ،‬عــدم ثبــوت اإلدانــة‬\n‫وصــدق احلكــم مــن محكمــة االســتئناف‬\n                                     ‫وتعزيــر املدعــى عليــه باجللــد ُ‬\n                                                              ‫باجلــوف ‪.‬‬\n\n\n\n                                                                                        ‫‪80‬‬\n\f     ‫اجلزائية بسكاكا‬\n                ‫ّ‬         ‫احلمد هلل وحده وبعد فلدي أنا ‪ .....‬رئيس احملكمة‬\n     ‫املســاعد وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫اجلزائيــة بســكاكا برقــم ‪ 33395222‬وتاريــخ ‪ 1433/06/11‬هــ  ‬\n       ‫املقيــدة باحملكمــة برقــم ‪ 331095191‬وتاريــخ ‪ 1433/06/10‬هــ  ففــي‬\n       ‫يــوم األحــد املوافــق ‪ 1433/12/26‬ه ـ افتتحــت اجللســة الســاعة ‪: 30‬‬\n       ‫‪ 10‬و فيهــا  قــدم املدعــي العــام ‪ ............‬دعــوى عامــة ضــد املدعــى عليــه‬\n       ‫هــذا احلاضــر ‪ ...............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n       ‫ا فيهــا إنــه بتاريــخ ‪1433/4/11‬ه ـ مت حتويــل‬     ‫‪ ...........‬أحــوال اجلــوف قائـ ً‬\n       ‫املدعى عليه من شــعبة ســجن ســكاكا إلى مستشــفى ‪  ............‬يرافقه‬\n       ‫مناوبــن مــن احلراســات حيــث كان يدعــي أن لديــه كســر يف يــده و يف‬\n       ‫قســم األشــعة قــام مبــد يــده علــى الكرســي املوجــود بجانبه و أخذ شــيء‬\n       ‫مــا وعنــد مشــاهدة املرافقــن معــه قــام علــى الفــور ببلعــه و لــم يســتطيع‬\n       ‫املناوبــن معرفــة مــا معــه و مت إعــداد محضــر بذلــك موقــع مــن قبلهــم‪.‬‬\n     ‫و قــد أثبــت التقريــر الكيميائــي الشــرعي مــن مركــز الســموم بتبــوك‬\n     ‫رقــم (‪ 1123‬م‪/‬م س ت) إيجابيــة عينــة البــول املدعــى عليــه أليــض املــادة‬\n     ‫الفعالــة للحشــيش و املــدرج باجلــدول األول فئــة (أ) يف تعميــم صاحــب‬\n     ‫الســمو امللكــي وزيــر الداخليــة رقــم ‪ 74831‬بتاريــخ ‪1431/07/09‬هــ‪.‬‬\n     ‫املدعــى عليــه ســجني لــدى شــعبة ســجن ســكاكا علــى قضيــة جنائيــة‪.‬‬\n     ‫و باســتجوابه أنكــر مــا نســب إليــه مــن اتهــام مــن ابتالعــه شــيئ ًا مــن‬\n     ‫احملظــورات أو املخــدرات‪ .‬و انتهــى التحقيــق إلــى توجيــه االتهــام ل ــ‪/‬‬\n     ‫‪ ..........‬بتعاطــي مــادة احلشــيش املخــدر املجــرم مبوجــب الفقــرة الثانيــة‬\n\n‫‪81‬‬\n\f‫مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة‬\n‫الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬و تاريــخ ‪1426/07/08‬ه ـ‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n‫فعــل مجــرم ومعاقــب عليــه نظام ـ ًا مــا يتعــن معــه إحالتــه للمحكمــة‬\n‫اجلزئيــة وفقـ ًا لنــص املادتــن (‪ )128-126‬مــن نظــام اإلجــراءات اجلزئيــة‬\n‫فإنــي أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه مبــا يلــي‪-1:‬‬\n‫الســجن وفق ـ ًا ملــا ورد يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام‬\n‫مكافحــة املخــدرات و املؤثــرات العقليــة‪ -2 .‬املنــع مــن الســفر خــارج‬\n‫اململكــة وفقـ ًا ملــا ورد بالفقــرة األولــى مــن املــادة (‪ )56‬مــن ذات النظــام‪.‬‬\n‫ا مــا ذكــره‬  ‫هــذه دعــواي‪.‬و بعــرض ذلــك علــى املدعــى عليــه أجــاب قائـ ً‬\n‫املدعــي العــام ضــدي يف دعــواه فغيــر صحيــح فلــم أقــم بتعاطــي مــادة‬\n‫احلشــيش املخــدر هكــذا أجــاب و بعــرض ذلــك علــى املدعــي العــام قــرر‬\n‫ا الصحيــح مــا ذكرتــه و بينتــي عليــه مــا يلــي‪-1 :‬مــا ورد باحملضــر‬            ‫قائـ ً‬\n‫املعــد مــن اجلهــة القابضــة لفــة رقــم (‪ )2‬صفحــة رقــم (‪ -2 .)11‬مــا جــاء‬\n‫بالتقريــر الكيميائــي لفــة رقــم (‪ .)14‬أطلــب الرجــوع إليهــا هكــذا قــرر‬\n‫و بالرجــوع إليهــا وجدتهــا مطابقــة ملــا ذكــره املدعــي العــام و مبواجهــة‬\n‫ا مــا ورد باحملضــر املعــد مــن اجلهــة القابضــة‬     ‫املدعــى عليــه بهــا قــرر قائـ ً‬\n‫صحيــح و ليــس فيــه مــا يــدل علــى مــا اتهمنــي بــه املدعــي العــام و أمــا مــا‬\n‫جــاء بالتقريــر الكيميائــي فــا علــم لــي بــه هكــذا قــرر و بعــرض ذلــك‬\n‫ا الصحيــح مــا ذكرتــه هكذا قــرر ورفعت‬              ‫علــى املدعــي العــام قــرر قائـ ً‬\n‫اجللســة للتأمــل إلــى يــوم األحــد ‪1434/03/01‬ه ـ الســاعة العاشــرة و‬\n‫النصــف ويف جلســة أخــرى يف يــوم  األحــد املوافــق‪ 1434/03/01‬ه ـ‬\n‫افتتحــت اجللســة الســاعة العاشــرة والنصــف وفيهــا حضــر املدعــي العــام‬\n\n\n                                                                                              ‫‪82‬‬\n\f     ‫واملدعــى عليــه ‪ ..........‬وبعــرض ســوابقه قــرر قائــا نعــم هــذه ســوابقي‬\n     ‫ثــاث ونلــت جزائــي عليهــا هكــذا قــرر وأقفلــت املرافعــه وبعــد ســماع‬\n     ‫الدعــوى واإلجابــة  وإلنــكار املدعــى عليــه دعــوى املدعــي العــام بقيامــه‬\n     ‫بتعاطــي مــادة احلشــيش املخــدر ولعــدم وجــود بينــة كافيــة لــدى املدعــي‬\n     ‫العــام إلدانــة املدعــى عليــه مبــا أســند إليــه مــن تعاطــي مــادة احلشــيش‬\n     ‫املخــدر وللتقريــر الكيمائــي الشــرعي رقــم (‪ )............‬الصــادر مــن‬\n     ‫مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية بتبــوك برقــم‬\n     ‫‪45/1221‬س م‪ 25/‬وتاريــخ ‪1433/4/26‬ه ـ املتضمــن إجابيــة عينــة بــول‬\n     ‫‪ ..........‬ملــادة احلشــيش‪0‬وحيث أن مــادة احلشــيش مــن املــواد املســكرة‬\n     ‫وجلميــع ماتقــدم بــه املدعــي العــام مــن إدلــة وقرائــن وبعــد اإلطــاع علــى‬\n     ‫املادتــن (‪)41.56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــه‬\n     ‫املشــار اليــه بدعــوى املدعــي العــام وخلــروج مــادة احلشــيش عــن إحاطتهمــا‬\n     ‫لعلــة اإلســكار ولوجــود ثــاث ســوابق مســجلة علــى املدعــى عليــه األولى‬\n     ‫حيــازة مخــدرات بقصــد اإلســتعمال يف ‪1431/7/22‬ه ـ والثانيــة نهــب‬\n     ‫قطــع غيــار وصــدم دوريــة أمنيــة يف ‪1431/7/2‬ه ـ والثالثــة ســرقة ســيارة‬\n     ‫يف‪1432/8/1‬ه ـ وذلــك حســب صحيفة ســوابقه املرفقــة لفه(‪  )12‬لذلك‬\n     ‫كلــه وبنــاءا عليــه لــم يثبــت لــدي إدانــة املدعــى عليــه ‪ ..........‬بتعاطي مادة‬\n     ‫احلشــيش املخــدر وتوجهــت التهمــة القويــة عليــه بذلــك وقــررت تعزيــره‬\n     ‫لقــاء ذلــك بجلــده خمســون جلــده دفعــة واحــدة وحكمــت بــرد دعــوى‬\n     ‫املدعــي العــام بشــأن تطبيــق املادتــن(‪ )41.56‬مــن نظــام مكافحــة‬\n     ‫املخــدرات واملؤثــرات العقليــة لعــدم شــموله بهمــا هــذا ماحكمــت بــه‬\n     ‫وتلــي عليهمــا فقنــع بــه املدعــى عليــه دون املدعــي العــام وطلــب متييــزه‬\n     ‫وأســتعد بتقــدمي الئحــة إعتراضيــة عليــه وقــرر فهمــه بتعليمــات التمييــز‬\n\n\n‫‪83‬‬\n\f‫وأفهمتــه بــأن عليــه احلضــور لهــذه احملكمــة يــوم اإلربعــاء ‪1434/3/4‬ه ـ‬\n‫إلســتالم نســخة احلكــم ففهــم ذلــك ورفعــت اجللســة لذلــك الــى يــوم‬\n‫اإلربعاء‪1434/3/4‬ه ـ ‪ 0‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/03/01‬ه ـ الســاعة احلاديــة‬\n                                                                           ‫عشــرة ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا  نحــن  قـض ــاة الدائ ــرة األولــى‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة اجلــوف علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بســكاكا برقــم‬\n‫‪  331095191‬وتاريــخ ‪1434/4/22‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪ .......... /‬املســجل برقــم  ‪3454170‬‬\n‫وتاريــخ ‪1434/3/3‬ه ـ اخلــاص بدعــوى  املدعــي العــام ضــد‪ ............. /‬يف‬\n‫قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه  مبــا هــو مــدون‬\n‫ومفصــل بــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‪ .‬فقــد‬\n‫قررنــا املصادقــة علــى احلكــم‪  .‬واهلل  املوفــق وصلــى اهلل علــى نبينــا‬\n                                             ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                       ‫‪84‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":80,"source_page_end":84,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"35026658cd0ef071fbc6e3f5fed7c5c851099af23ba05bd0af4da2876ef3fd49","normalized_text_hash":"0d6a9b0820b0e3adbfabbb0dd84eca4f9d96f31dfb9363e3479e8e15073c8398","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p80-3454170"},{"id":"58372c81-bac6-5509-8907-ab98d4cbde94","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلشيش املخدر -ترويج احلشيش املخدر -تستر على املروج -شهادة الشهود -إقرار املدعى عليه -التعزير بالسجن و اجللد و اإلبعاد عن الباد و مصادرة اجلوال و إلغاء الشريحة .","document_number":"34186238","case_number":"33612392","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/13","year":"1434","subject":"مخدرات -تعاطي احلشيش املخدر -ترويج احلشيش املخدر -تستر على املروج -شهادة الشهود -إقرار املدعى عليه -التعزير بالسجن و اجللد و اإلبعاد عن الباد و مصادرة اجلوال و إلغاء الشريحة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34186238 :‬تاريخه‪1434/4/13 :‬هـ‬\n                         ‫رقم الدعوى‪33612392 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪     34370699‬تاريخه‪1434/11/26 :‬هـ‬\n\n\n\n     ‫مخدرات ‪ -‬تعاطي احلشــيش املخدر ‪ -‬ترويج احلشــيش املخدر ‪ -‬تســتر‬\n     ‫علــى املــروج ‪ -‬شــهادة الشــهود ‪ -‬إقــرار املدعــى عليــه ‪ -‬التعزيــر بالســجن‬\n         ‫و اجللــد و اإلبعــاد عــن البــاد و مصــادرة اجلــوال و إلغــاء الشــريحة ‪.‬‬\n\n\n\n\n                                                ‫‪ - 1‬اإلقرار حجة شرعية ‪.‬‬\n             ‫‪ - 2‬املادة (‪ )38‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n             ‫‪ - 3‬املادة (‪ )53‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n              ‫‪ - 4‬املادة (‪ )56‬من نظام مكافحة املخدرات و املؤثرات العقلية‪.‬‬\n             ‫‪ - 5‬املادة (‪ )60‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي العــام علــى املدعــى عليــه بترويــج احلشــيش املخــدر ‪،‬‬\n     ‫وردت معلومــات لــدى مكافحــة املخــدرات عــن قيــام املدعــى عليــه‬\n     ‫بترويــج احلشــيش املخــدر ‪ ،‬وقــد مت متكــن املصــدر  مــن االتصــال بــه ‪،‬‬\n     ‫وطلــب كميــة  مــن احلشــيش املخــدر ‪ ،‬مببلــغ مائتــي ريــال ‪  ،‬فاســتعد‬\n     ‫املدعــى عليــه بذلــك ‪ ،‬ومت تزويــد املصــدر باملبلــغ املرقــم‪ ،‬ومت تفتيشــه‬\n     ‫بعــد تزويــده باملبلــغ ‪ ،‬وملــا تقابــل مــع املدعــى عليــه ‪ ،‬حتــت أنظــار الفرقــة‬\n     ‫القابضــة ‪  ،‬ســلم املصــدر املبلــغ املرقــم للمدعــى عليــه ‪ ،‬وطلــب املدعــى‬\n\n‫‪85‬‬\n\f‫عليــه مــن املصــدر االنصــراف مــن املوقــع ‪ ،‬وأبلغــه بأنــه عنــد توفــر قطعــة‬\n‫احلشــيش ســوف يعــاود االتصــال عليــه ‪ ،‬وبعــد عــدة أيــام اتصــل املدعــى‬\n‫عليــه علــى املصــدر ‪ ،‬يفيــده بتوفــر احلشــيش ‪ ،‬وكانــت املكاملــة حتــت‬\n‫ســماع الفرقــة القابضــة ‪ ،‬فتــم تفتيــش املصــدر ‪ ،‬ومت االنتقــال إلــى‬\n‫املــكان املتفــق عليــه ‪ ،‬وتقابــل املصــدر مــع املدعــى عليــه ‪ ،‬وقــام املدعــى‬\n‫عليــه ‪ ،‬بتســليم املصــدر قطعــة بنيــة اللــون ‪ ،‬يشــتبه أن تكــون مــن مــادة‬\n‫احلشــيش املخــدر ‪ ،‬بلــغ وزنهــا (‪ )4050‬أربعــة جرامــات وخمســن باملائــة‬\n‫مــن اجلــرام ‪ ،‬وكانــت العمليــة حتــت أنظــار الفرقــة القابضــة‪ ،‬و طلــب‬\n‫املدعــي العــام تعزيــر املدعــى عليــه بالســجن واجللــد والغرامــة واإلبعــاد‬\n‫عــن البــاد ومصــادرة الســيارة ومصــادرة اجلوالــن وإلغــاء شــريحتيهما‬\n‫ورد املبلــغ احلكومــي‪ ،‬وتعزيــره لقــاء تســتره علــى املــروج‪ ،‬أنكر املدعي‬\n‫عليــه مــا جــاء بدعــوى املدعــي العــام بطلــب البينــة مــن املدعــي العــام علــى‬\n‫دعــواه أحضــر شــاهديه و قــد شــهدا بصحــة الواقعــة و بعــرض شــهادتهما‬\n‫علــى املدعــى عليــه أقــر بصحــة مــا جــاء يف الشــهادة‪ ،‬صــدر احلكــم‬\n‫بتعزيــر املدعــى عليــه بالســجن و اجللــد و الغرامــة و مصــادرة اجلوالــن‬\n‫و إلزامــه بإعــادة املبلــغ احلكومــي و إلغــاء الشــريحة و إبعــاده خــارج‬\n‫اململكــة وال يســمح لــه بالعــودة إليهــا إال فيمــا تســمح بــه تعليمــات احلــج‬\n‫و العمــرة‪ ،‬قنــع املدعــي عليــه باحلكــم ‪ ،‬وقــرر املدعــي العــام اعتراضــه‬\n‫علــى احلكــم بــدون الئحــة‪ ،‬مت صــدق احلكــم مــن محكمــة االســتئناف‬\n                                                                                      ‫‪.‬‬\n\n\n\n\n                                                                                          ‫‪86‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪  ).....‬القاضــي يف احملكمــة اجلزائيــة‬\n     ‫مبكــة املكرمــة   وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n       ‫احملكمــة اجلزائيــة مبكــة املكرمــة برقم (‪ ).....‬وتاريــخ ‪1433/10/21‬‬\n     ‫هــ  املقيــدة باحملكمــة برقــم (‪ ).....‬وتاريــخ ‪ 1433/10/21‬هــ  ففــي يــوم  ‬\n     ‫الســبت املوافــق‪ 1434/02/23‬ه ـ افتتحــت اجللســة الســاعة ‪  11 : 45‬‬\n       ‫وفيهــا حضــر  املدعــي العــام وداعــى علــى احلاضــر معــه (‪ ).....‬اندونيســي‬\n       ‫ا انــه بنــاء علــى توفــر معلومــات لــدى‬\n                                                 ‫اجلنســية  اقامــة رقــم (‪ ).....‬قائ ـ ً‬\n       ‫مكافحــة املخــدرات عــن قيــام املدعــى عليــه بترويــج احلشــيش املخــدر‬\n       ‫بحــي (‪ ).....‬جــرى بتاريــخ ‪1433/9/25‬ه ـ متكــن املصــدر مــن التصــال‬\n       ‫علــى جــوال املدعــى عليــه رقــم (‪ ).....‬وطلــب منــه كميــة مــن احلشــيش‬\n       ‫املخــدر مببلــغ (‪ )200‬مائتــي  ريــال فاســتعد املدعــى عليــه بذلــك وطلــب‬\n       ‫مــن املصــدر احلضــور لــه بحــي (‪ ).....‬امــام مركــز الدفــاع املدنــي وجــرى‬\n       ‫تفتيــش املصــدر بعــد تزويــده باملبلــغ املرقــم وقــدرة (‪ )200‬مائتــا ريــال‬\n     ‫فتقابــل املصــدر مــع املدعــى عليــه حتــت أنظــار الفرقــة وقــام املصــدر‬\n     ‫بتســليم املدعــى عليــه املبلــغ املرقــم وطلــب املدعــى عليــه مــن املصــدر‬\n     ‫االنصــراف مــن املوقــع وابلغــه بأنــه عنــد توفــر قطعــة احلشــيش املخــدر‬\n     ‫ســوف يعــاود االتصــال بــه الســتالمها  ويف متــام الســاعة الثانيــة مــن صباح‬\n     ‫يــوم الثالثــاء املوفــق ‪1433/9/26‬ه ـ عــاود املدعــى عليــه االتصــال علــى‬\n     ‫املصــدر مــن جــوال رقــم (‪ ).....‬واخبــر املصــدر مبكاملــة مســموعة بــأن‬\n     ‫الكميــة املطلوبــة ســوف تكــون متوفــرة يف أيــام العيــد ويف يــوم الثالثــاء‬\n     ‫املوافــق ‪1433/10/3‬ه ـ ورد إتصــال مــن الرقــم (‪ ).....‬أفــاد فيــه املدعــى‬\n\n‫‪87‬‬\n\f  ‫عليــة بــأن كميــة احلشــيش املطلوبــة متوفــرة لديــة وطلــب مقابلــة املصــدر‬\n  ‫بحــي (‪ ).....‬وكانــت املكاملــة حتــت ســماع الفرقــة فتــم تفتيــش املصــدر‬\n  ‫وجــرى دفعــة حتــت انظــار الفرقــة فحضــر املدعــى عليــة علــى ســيارة مــن‬\n  ‫نــوع (‪ ).....‬حتمــل اللوحــة ســعودية رقــم (‪ ).....‬تعــود ملكيتهــا للمواطــن‬\n  ‫(‪ ).....‬ونــزل املدعــى عليــه مــن الســيارة التــي يقودهــا وتقابــل مــع املصــدر‬\n  ‫وقــام بتســليم املصــدر قطعــة بنيــة اللــون يشــتبة أن تكــون مــن مــادة‬\n  ‫احلشــيش املخــدر بلــغ وزنهــا (‪4050‬جــم) اربعــة جرامــات وخمســن باملائــة‬\n  ‫مــن اجلــرام وكانــت العمليــة حتــت االنظــار الفرقــة املنتشــرة باملوقــع‬\n  ‫واعطيــت االشــارة فتــم القبــض علــى املدعــى عليــة وبتفتيشــة شــخصي ًا‬\n  ‫لــم يعثــر معــه علــى اي شــي مــن املمنوعــات وعثــر معــه علــى جوالــن مــن‬\n  ‫نــوع (‪ ).....‬بشــريحتني (‪ ).....‬و(‪ ).....‬يحمــل  االول الرقــم املصنعــي (‪).....‬‬\n  ‫ولثانــي يحمــل الرقــم املصنعــي (‪ ).....‬واتضــح أنهمــا الرقمــان اللــذان‬\n  ‫اســتخدما يف عمليــة التنســيق للترويــج ومبناقشــته مــن قبــل الفرقــة‬\n  ‫القابضــة أقــر أمــام الفرقــة بواقعــة الضبــط  وباســتجواب املدعــى عليــه‬\n  ‫(‪ ).....‬أقــر بانــه قبــض عليــة مــن قبــل مكافحــة املخــدرات أثنــاء قيامــة‬\n  ‫ببيــع  قطعــة مــن احلشــيش املخــدر وانــه حصــل عليــة مــن شــخص اليعرفــه‬\n  ‫وقــد انتهــى التحقيــق الــى توجيــه االتهــام للمدعــى عليــه وهــذا فعل محرم‬\n  ‫شــرعا ومجــرم نظامــا وفقــا للفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام‬\n  ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n  ‫م‪ 39/‬وتاريــخ ‪1426/7/8‬ه ـ وتســترة علــى املــروج وحيــث أن ماقــام بــه‬\n  ‫املدعــى عليــه فعــل محــرم شــرع ًا ومجــرم ومعاقــب عليــة نظام ـ ًا وفقــا‬\n‫للمــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة  ‬\n  ‫لــذا اطلــب إثبــات مــا أســند إليــه واحلكــم عليــة بالعقوبــات األصليــة‬\n\n\n                                                                                         ‫‪88‬‬\n\f     ‫والتكميليــة التاليــة ‪ -1‬بالســجن واجللــد والغرمــة اســتناد للفقــرة (‪)1‬‬\n     ‫مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n     ‫املشــارإليه ‪ -2‬إبعــاد عــن البــاد بعــد االنتهــاء مــن تنفيــذ عقوبتــه وفقــا‬\n     ‫للفقــرة (‪ )2‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة املشــار إليــة ‪ -3‬الزامــه باعــادة املبلــغ احلكومــي املرقــم وقــدرة‬\n     ‫مائتــا (‪ )200‬الدارة مكافحــة املخــدرات بالعاصمــة املقدســة اســتناد‬\n     ‫لتعميــم صاحــب الســمو امللكــي وزيــر الداخليــة رقــم ‪65980/4/5/1‬‬\n     ‫وتاريــخ ‪1428/12/23_22‬ه ـ ‪ -4‬مصــادرة اجلوالــن ذوي الرقمــن‬\n     ‫املصنعــن (‪ ).....‬ورقــم(‪ ).....‬اســتناد للفقــرة (‪ )1‬مــن املــادة (‪ )53‬مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة  وإلغــاء شــريحتيهما اســتناد‬\n     ‫لبرقيــة ســمو وزيرالداخليــة رقــم ‪ 9798/5/1‬يف ‪1428/2/10_9‬ه ـ‬\n     ‫والنــص يف القــرار الشــرعي علــى إدخــال قيمتهــا مبوسســة النقــد‬\n     ‫العربــي الســعودي حلســاب املديريــة العامــة املكافحــة املخــدرات اســتناد‬\n     ‫لبرقيــة صاحــب الســمو امللكــي ولــي العهــد نائــب رئيــس مجلــس الــوزراء‬\n     ‫وزيــر الداخليــة رقــم ‪ 40656‬وتاريــخ ‪1430/6/8‬ه ـ ‪ -5‬تعزيــر لقــاء‬\n     ‫تســترة علــى املــروج اســتناد لتعميــم معالــي رئيــس الهيئــة رقــم ‪15596‬‬\n     ‫يف وزيرالداخليــة رقــم ‪ 9798/5/1‬يف ‪1428/2/10_9‬ه ـ والنــص يف‬\n     ‫القــرار الشــرعي علــى إدخــال قيمتهــا مبوسســة النقــد العربــي الســعودي‬\n     ‫حلســاب املديريــة العامــة املكافحــة املخــدرات اســتناد لبرقيــة صاحــب‬\n     ‫الســمو امللكــي ولــي العهــد نائــب رئيــس مجلــس الــوزراء وزيــر الداخليــة‬\n     ‫رقــم ‪ 40656‬وتاريــخ ‪1430/6/8‬ه ـ ‪ -5‬تعزيــر لقــاء تســترة علــى املــروج‬\n     ‫اســتناد لتعميــم معالــي رئيــس الهيئــة رقــم ‪ 15596‬يف‪1433/5/4‬ه ـ‬\n     ‫وبســؤال املدعــى عليــه عــن دعــوى املدعــى العــام أجــاب قائــا ماذكــره‬\n\n\n‫‪89‬‬\n\f‫املدعــى العــام يف دعــواه أعــاه غيــر صحيــح فأنــا لــم ابيــع وإمنــا أعطيــت‬\n‫املصــدر قطعــة مــن احلشــيش املخدرأمانــه عنــدي وأنــا الأعرفهــا فأنــا‬\n‫ال أشــرب الدخــان ومــن ثــم ســلمته مــا أعطانــي  إيــاه ومت القبــض علــي‬\n‫ا أطلــب‬  ‫هكــذا أجــاب وبســؤال املدعــى العــام عــن بينتــه أجــاب قائ ـ ً‬\n‫إمهالــي إلحضــار بينتــي وعليــه رفعــت اجللســة إلحضــار املدعــى العــام‬\n‫بينتــه ويف هــذا اليــوم األحــد املوافــق ‪1434/3/22‬ه ـ افتتحــت اجللســة‬\n‫ال مــن‬‫يف متــام الســاعة التاســعة وفيهــا أحضــر املدعــي العــام بينتــه ك ً‬\n‫‪ ).....( /‬ســعودي اجلنســية بالســجل املدنــي رقــم (‪ ).....‬و (‪ ).....‬ســعودي‬\n‫اجلنســية بالســجل املدنــي رقــم (‪ ).....‬وباستشــهادهما شــهد كل واحــد‬\n‫ا توفــر لدينــا معلومــات عــن قيــام املدعــى عليــه بترويــج‬     ‫منهمــا قائ ـ ً‬\n‫احلشــيش بحــي (‪ ).....‬جــرى متكــن املصــدر مــن االتصــال علــى جــوال‬\n‫املدعــى عليــه وطلــب منــه كميــة مــن احلشــيش املخــدر مببلــغ مائتــن‬\n‫ريــال فاســتعد املدعــى عليــه وطلــب مــن املصــدر احلضــور إليــه بحــي (‪).....‬‬\n‫أمــام مركــز الدفــاع املدنــي وجــرى تفتيــش املصــدر بعــد تزويــده باملبلــغ‬\n‫املرقــم ‪200‬مائنــان ريــال فقابــل املصــدر مــع املدعــى عليــه وقــام املصــدر‬\n‫بتســليمة املبلــغ املرقــم وطلــب املدعــى عليــه مــن املصــدر االنصــراف مــن‬\n‫املوقــع وأبلغــه بأنــه متــى ماتوفــر الكميــه ســيتصل عليــه عــاود املدعــى‬\n‫عليــه االتصــال علــى املصــدر وأخبــر املصــدر مبكاملــة مســموعة بــأن‬\n‫الكميــة املطلوبــة ســتكون متوفــرة يف أيــام العيــد ورد اتصــال مــن‬\n‫املدعــى عليــه أفــاد فيــه بــأن الكميــة مــن احلشــيش متوفــرة وطلــب‬\n‫املدعــى عليــه مــن املصــدر مقابلتــه بحــي (‪ ).....‬وكانــت املكاملــة حتــت‬\n‫ســماع الفرقــة مت تفتيــش املصــدر وجــرى دفعــه حتــت أنظــار الفرقــة‬\n‫حضــر املدعــى عليــه علىســيارة مــن نــوع (‪ ).....‬ونــزل املدعــى عليــه مــن‬\n\n\n                                                                                      ‫‪90‬‬\n\f     ‫الســيارة وتقابــل مــع املصــدر وقــام بتســليم املصــدر قطعــة بنيــة اللــون ولــم‬\n     ‫نشــاهد عمليــة االســتالم وال التســليم ثــم أعطيــت اإلشــارة فتــم القبــض‬\n     ‫عليــه وبتفتيشــه لــم يعثــر علــى أي شــي مــن املمنوعــات هــذه شــهادتنا‬\n     ‫ا ماجــاء يف شــهاد‬      ‫وبعــرض الشــهادة علــى املدعــى عليــه أجــاب قائ ـ ً‬\n     ‫الشــاهدين صحيحــة وأنــا ســلمت املصــدر وأنــا نــادم علــى مابــدر منــي‬\n     ‫وتائــب هــذه إجابتــي فبنــاء علــى ماتقــدم مــن الدعــوى واإلجابــة ومبــا أن‬\n     ‫املدعــى عليــه أقــر بدعــوى املدعــى العــام ومبــا أن اإلقــرار حجــة شــرعية‬\n     ‫علــى املقــر وبنــاء علــى املــادة ‪ 38،53،56،60‬لــذا وجلميــع ماتقــدم فقــد‬\n     ‫تقــرر لــي مــا يلــي أو ًال ثبــت لــدي إدانــة املدعــى عليــه مبــا أســند إليــه مــن‬\n     ‫ترويــج أربعــة جرامــات وخمســون باملائــة مــن احلشــيش املخــدر بقصــد‬\n     ‫التعاطــي ثاني ـ ًا قــررت ســجنه مــدة ســنة محســوب ًا منهــا مــدة إيقافــه يف‬\n     ‫هــذه القضيــة وجلــدة ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات كل‬\n     ‫دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى عشــرة أيــام وتغرميــه بألــف‬\n     ‫ريــال خلزينــة الدولــة تصــرف للمصالــح العامــة ثالث ـ ًا إبعــاد املدعــى عليــه‬\n     ‫خــارج اململكــة بعــد انتهــاء محكوميتــه واليســمح لــه بالعــودة إليهــا‬\n     ‫إالماتســمح بــه تعليمــات احلــج والعمــرة رابع ـ ًا مصــادرة اجلوالــن ذو‬\n     ‫الرقــم (‪ ).....‬و (‪ ).....‬وإلغــاء شــريحتهما وإيــداع مبلغهمــا مبوسســة النقــد‬\n     ‫العربــي الســعودي لصالــح املديريــة العامــة ملكافحــة املخــدرات كمــا‬\n     ‫قــررت إلزامــه بإعــادة املبلــغ املرقــم ووقــدره مائتــي ريــال وملــا ســبق كلــه‬\n     ‫حكمــت وبعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة باحلكــم‬\n     ‫كمــا قــرر املدعــى العــام االعتــراض ‪.‬وصلــى اهلل وســلم علــى ســيدنا‬\n                                                 ‫محمــد حــرر بتاريــخ ‪1434/3/22‬ه ـ‬\n     ‫احلمــدهلل وحــده وبعــد ويف هــذا اليــوم االربعــاء املوافــق ‪1434/9/16‬ه ـ‬\n\n\n‫‪91‬‬\n\f‫افتتحــت اجللســة وقــد عــادت املعاملــة مــن محكمــة االســتئناف مبكــة‬\n‫املكرمــة برقــم (‪ ).....‬يف ‪1434/7/18‬ه ـ وبرفقهــا قــرار الدائرة اجلزائية‬\n‫اخلامســة رقــم (‪ ).....‬يف ‪1434/7/10‬ه ـ واملذيــل مــن اصحــاب الفضيلــة‬\n‫بتوقيعاتهــم كال مــن رئيــس اســتئناف (‪ ).....‬و قاضــي اســتئناف (‪).....‬‬\n‫وقاضــي اســتئناف (‪ ).....‬ونــص احلاجــة منــه وبدارســة القــرار وصــورة‬\n‫ضبطــه تقــرر إعادتهــا لفضيلــة حاكمهــا ملالحظــة أن القــرار فيــه‬\n‫ســقط مــن الســطر الســابع مــن أســفل الصفحــة الثانيــة عنــد إحضــار‬\n‫املدعــي العــام لبينتــه كمــا يالحــظ أن هنــاك أغــاط مطبعيــة وإمالئيــة‬\n‫مؤشــر عليهــا بالقلــم الرصــاص فيالحــظ ذلــك وعليــه فأجيــب أصحــاب‬\n‫الفضيلــة بأنــه جــرى إكمــال الــازم حيــال مــا ذكــر وبــاهلل التوفيــق‬\n   ‫وصلــى اهلل وســلم علــى ســيدنا محمــد حــرر بتاريــخ ‪1434/9/16‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد  ويف يــوم االحــد املوافق ‪1434/12/22‬هـ افتتحت‬\n‫اجللســة الســاعة  التاســعة صباحــا وفيهــا عــادت املعاملــة مــن محكمــة‬\n                               ‫االســتئناف مبكــة املكرمــة برقــم ‪331847300‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ -:‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة املســاعد برقــم  (‪ )....‬وتاريخ‬\n‫‪1434/11/12‬ه ـ املرفــق بهــا القــرار الصــادر م ــن فضيلة الشــيخ ‪).....( /‬‬\n‫القاضــي باحملكمــة اجلزائيــة مبكــة املكرمــة برقــم (‪ ).....‬وتـ ـ ـ ـ ــاريخ‬\n‫‪1434/4/13‬هـ الـمتضم ــن دعوى املدعي العام ضد ‪ ).....( /‬اندونيســي‬\n‫اجلنســية املتهــم بترويــج احلشــيش املخــدر ‪ ،‬احملكوم فيــه مبا دون بباطن‬\n‫القــرار ‪ ،‬وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة قررنــا‬\n\n\n                                                                                  ‫‪92‬‬\n\f     ‫املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل‬\n                                ‫علــى نبينــا محمــد وعلــى آل ـ ـ ــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪93‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":85,"source_page_end":93,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c071b92baba00e3efdd2f1d57e16a52a1e947a5a6ccbd253097ef87db4768ea0","normalized_text_hash":"129f9f9539227c096fdb2b2b06f72e322b21d1b53c927f9f12957931cadcc9ee","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p85-34186238"}]$archive_payload$::jsonb) AS x LIMIT 25
